/* 古诗词文言文数据库 - 古诗词300首 + 文言文100篇 */
const CLASSICS_DATA = {
  // ===== 古诗词 =====
  poems: [
    { title: '静夜思', author: '李白', dynasty: '唐', content: '床前明月光，疑是地上霜。举头望明月，低头思故乡。', translation: '明亮的月光洒在床前，白花花的好像地上结了一层霜。抬起头望着天上明月，低下头思念起远方的家乡。', appreciation: '这首诗用浅白的语言写游子的乡愁，读来亲切动人。', category: '思乡' },
    { title: '春晓', author: '孟浩然', dynasty: '唐', content: '春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。', translation: '春天的夜晚睡得香甜不知不觉天就亮了，醒来只听到到处是鸟儿鸣叫。想起昨夜风雨声声，不知院子里的花被吹落了多少。', appreciation: '诗人写春晨初醒的感受，用鸟鸣和风雨表现春光可爱与惜春之情。', category: '春景' },
    { title: '咏鹅', author: '骆宾王', dynasty: '唐', content: '鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。', translation: '鹅啊鹅啊鹅，你弯着脖子朝天空鸣叫。洁白的羽毛浮在碧绿的水上，红红的脚掌拨动着清澈的水波。', appreciation: '这是诗人七岁时的作品，用鲜亮的色彩和生动的动作描绘了鹅水上嬉戏的样子。', category: '咏物' },
    { title: '登鹳雀楼', author: '王之涣', dynasty: '唐', content: '白日依山尽，黄河入海流。欲穷千里目，更上一层楼。', translation: '夕阳依傍着远山慢慢落下，黄河水滚滚流向大海。想要看到更远的千里风光，就要再登上一层楼。', appreciation: '诗中蕴含站得高看得远的哲理，激励人不断向上追求更高境界。', category: '哲理' },
    { title: '望庐山瀑布', author: '李白', dynasty: '唐', content: '日照香炉生紫烟，遥看瀑布挂前川。飞流直下三千尺，疑是银河落九天。', translation: '阳光照在香炉峰上腾起紫色云烟，远远望去瀑布像挂在山前。水流从高处直冲而下有三千尺，让人怀疑是银河从九天之上倾泻下来。', appreciation: '诗人用奇特的想象把瀑布写得雄伟壮观，展现磅礴气势。', category: '写景' },
    { title: '绝句', author: '杜甫', dynasty: '唐', content: '两个黄鹂鸣翠柳，一行白鹭上青天。窗含西岭千秋雪，门泊东吴万里船。', translation: '两只黄鹂在翠绿的柳枝上鸣叫，一行白鹭飞上蔚蓝天空。窗户里含着西岭千年不化的积雪，门前停泊着远航东吴的万里船。', appreciation: '诗人用四句写四种景物，色彩鲜明动静相宜，表现春日生机。', category: '春景' },
    { title: '春夜喜雨', author: '杜甫', dynasty: '唐', content: '好雨知时节，当春乃发生。随风潜入夜，润物细无声。野径云俱黑，江船火独明。晓看红湿处，花重锦官城。', translation: '好雨懂得时节，正当春天万物生长时便下了起来。它随微风在夜里悄悄降临，细细滋润万物没有一点声音。田间小路和云都黑沉沉的，江上只有船上的灯火独自明亮。明早再看那红润湿润的地方，锦官城的花一定沉甸甸地开满。', appreciation: '诗人以细腻笔触写春雨润物，表达对春雨的喜悦和对丰收的期盼。', category: '春景' },
    { title: '江畔独步寻花', author: '杜甫', dynasty: '唐', content: '黄四娘家花满蹊，千朵万朵压枝低。留连戏蝶时时舞，自在娇莺恰恰啼。', translation: '黄四娘家门前的小路上开满了花，千朵万朵把枝条都压得低垂。蝴蝶留恋不舍地飞舞，娇俏的黄莺自由自在地啼叫。', appreciation: '诗人写江边漫步所见的繁花蝶舞莺啼，表现春光烂漫心情轻松。', category: '春景' },
    { title: '游子吟', author: '孟郊', dynasty: '唐', content: '慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。', translation: '慈爱的母亲手中穿针引线，为出门在外的儿子缝制衣裳。临行前密密地缝着，只怕儿子迟迟不能回家。谁说小草那一点点心意，能报答得了春天阳光般的母爱呢？', appreciation: '诗中用密密缝衣的细节表现母爱，最后以寸草春晖的比喻赞美母爱的伟大。', category: '亲情' },
    { title: '回乡偶书', author: '贺知章', dynasty: '唐', content: '少小离家老大回，乡音无改鬓毛衰。儿童相见不相识，笑问客从何处来。', translation: '年少时离家年老才回来，家乡口音没变只是两鬓的头发已经花白。孩子们见了都不认识，笑着问这位客人是从哪里来的。', appreciation: '诗人写久别回乡的感慨，以儿童的发问反衬岁月流逝物是人非的伤感。', category: '思乡' },
    { title: '咏柳', author: '贺知章', dynasty: '唐', content: '碧玉妆成一树高，万条垂下绿丝绦。不知细叶谁裁出，二月春风似剪刀。', translation: '高高的柳树像是用碧玉装扮而成，千万条柳枝像绿色丝带垂下来。不知这细细的柳叶是谁裁剪出来的，原来是二月的春风像剪刀一样剪出来的。', appreciation: '诗人把春风比作剪刀，想象新奇，写出柳树的柔美和春天的活力。', category: '春景' },
    { title: '凉州词', author: '王之涣', dynasty: '唐', content: '黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关。', translation: '黄河奔流直上仿佛连着白云，一座孤城矗立在万仞高山之间。羌笛何必吹奏那哀怨的折杨柳曲，春风本来就吹不到玉门关外啊。', appreciation: '诗中写边塞的荒凉孤寂，含蓄地表达戍边将士的思乡之情。', category: '边塞' },
    { title: '出塞', author: '王昌龄', dynasty: '唐', content: '秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山。', translation: '秦汉时的明月照着秦汉时的边关，万里出征的将士至今未还。只要像飞将军李广那样的良将还在，决不让胡人的骑兵越过阴山。', appreciation: '诗人借古讽今，表达对良将的渴望和保家卫国的豪情。', category: '边塞' },
    { title: '芙蓉楼送辛渐', author: '王昌龄', dynasty: '唐', content: '寒雨连江夜入吴，平明送客楚山孤。洛阳亲友如相问，一片冰心在玉壶。', translation: '冷雨连夜洒满江天来到吴地，清晨送别友人只见楚山孤影。洛阳的亲友如果问起我的情况，就说我像玉壶里的冰一样清白高洁。', appreciation: '诗人以冰心玉壶自喻，表达自己高洁的品格和坚守操守的决心。', category: '送别' },
    { title: '鹿柴', author: '王维', dynasty: '唐', content: '空山不见人，但闻人语响。返景入深林，复照青苔上。', translation: '空旷的山中看不见人影，只隐约听到有人说话的声音。夕阳的余晖照进深林，又反射在青苔之上。', appreciation: '诗人以动衬静，以光写幽，表现出山林的寂静和空灵之美。', category: '写景' },
    { title: '送元二使安西', author: '王维', dynasty: '唐', content: '渭城朝雨浥轻尘，客舍青青柳色新。劝君更尽一杯酒，西出阳关无故人。', translation: '渭城清晨的雨沾湿了轻尘，客舍旁的柳树青翠一新。劝你再喝尽这一杯酒，向西出了阳关就再没有老朋友了。', appreciation: '诗中写雨后送别的场景，以一杯酒寄托深厚的离情别意。', category: '送别' },
    { title: '九月九日忆山东兄弟', author: '王维', dynasty: '唐', content: '独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。', translation: '独自一人在异乡做客，每到佳节就加倍思念亲人。遥想兄弟们登高的地方，都插着茱萸唯独少了我一个人。', appreciation: '诗人从自己和兄弟两方面写思念，把思乡怀亲之情写得真切动人。', category: '思乡' },
    { title: '古朗月行', author: '李白', dynasty: '唐', content: '小时不识月，呼作白玉盘。又疑瑶台镜，飞在青云端。', translation: '小时候不认识月亮，把它叫做白玉盘。又怀疑那是瑶台的仙镜，飞到了青云的上面。', appreciation: '诗人以儿童的口吻写对月亮的好奇想象，天真烂漫富有童趣。', category: '咏物' },
    { title: '望天门山', author: '李白', dynasty: '唐', content: '天门中断楚江开，碧水东流至此回。两岸青山相对出，孤帆一片日边来。', translation: '天门山被长江从中冲开，碧绿的江水东流到这里回旋。两岸的青山相对而出，一片孤帆从太阳那边驶来。', appreciation: '诗人写天门山的雄奇和长江的壮阔，展现出开阔豪迈的气象。', category: '写景' },
    { title: '别董大', author: '高适', dynasty: '唐', content: '千里黄云白日曛，北风吹雁雪纷纷。莫愁前路无知己，天下谁人不识君。', translation: '千里黄云遮蔽了白日显得昏暗，北风送着大雁纷飞的大雪纷纷落下。不要发愁前方的路上没有知己，天下有谁不认识您呢？', appreciation: '诗人在送别中以豪迈的语言鼓励友人，一扫送别的悲凉，显得慷慨昂扬。', category: '送别' },
    { title: '赠汪伦', author: '李白', dynasty: '唐', content: '李白乘舟将欲行，忽闻岸上踏歌声。桃花潭水深千尺，不及汪伦送我情。', translation: '我正乘着船将要出发，忽然听到岸上有人踏着节拍唱歌。桃花潭的水纵然有千尺之深，也比不上汪伦送别我的情谊深。', appreciation: '诗人以水深喻情深，把抽象的友谊写得具体可感，真挚动人。', category: '送别' },
    { title: '黄鹤楼送孟浩然之广陵', author: '李白', dynasty: '唐', content: '故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流。', translation: '老朋友在黄鹤楼与我辞别，在这柳絮如烟繁花似锦的三月顺江而下扬州。孤帆的远影消失在碧蓝的天边，只看见长江水向天际流去。', appreciation: '诗人写送别友人时目送孤帆远去的情景，含蓄地表达了依依惜别之情。', category: '送别' },
    { title: '早发白帝城', author: '李白', dynasty: '唐', content: '朝辞白帝彩云间，千里江陵一日还。两岸猿声啼不住，轻舟已过万重山。', translation: '清晨告别彩云环绕的白帝城，千里之外的江陵一天就能返回。两岸猿猴的叫声还在耳边回响，轻快的小船已穿过万重山峦。', appreciation: '诗人写遇赦归来时顺江而下的轻快心情，全诗洋溢着喜悦与畅快。', category: '写景' },
    { title: '月下独酌', author: '李白', dynasty: '唐', content: '花间一壶酒，独酌无相亲。举杯邀明月，对影成三人。', translation: '在花丛中摆一壶酒，独自斟饮没有亲人相伴。举起酒杯邀请明月共饮，加上自己的影子正好成了三个人。', appreciation: '诗人以邀月对饮写孤独，又以浪漫想象化解寂寞，显出旷达的胸怀。', category: '抒怀' },
    { title: '独坐敬亭山', author: '李白', dynasty: '唐', content: '众鸟高飞尽，孤云独去闲。相看两不厌，只有敬亭山。', translation: '群鸟高飞远去无影无踪，一片孤云也悠闲地独自飘走。彼此相看却从不厌倦的，只有我和这敬亭山了。', appreciation: '诗人写鸟去云闲的孤寂，又以与山相对写物我相知的情怀，寄托孤高寂寞的心境。', category: '抒怀' },
    { title: '江雪', author: '柳宗元', dynasty: '唐', content: '千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。', translation: '千山万岭不见飞鸟的踪影，千条万条小路也不见人迹。只有一只孤舟上披蓑戴笠的老翁，独自在风雪的寒江上垂钓。', appreciation: '诗人以空旷寂静的雪景衬托孤舟独钓的老翁，表现出孤高不屈的品格。', category: '写景' },
    { title: '寻隐者不遇', author: '贾岛', dynasty: '唐', content: '松下问童子，言师采药去。只在此山中，云深不知处。', translation: '在松树下询问童子，他说师傅采药去了。师傅就在这座山里，只是云雾深重不知在哪里。', appreciation: '诗人以问答形式写寻访隐者不遇，含蓄地表现了隐者的高洁和山林的幽深。', category: '抒怀' },
    { title: '枫桥夜泊', author: '张继', dynasty: '唐', content: '月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。', translation: '月亮落下乌鸦啼叫霜气满天，江边的枫树和渔火陪伴着愁眠的我。姑苏城外的寒山寺，半夜的钟声传到了客船上。', appreciation: '诗人写夜泊枫桥的所见所闻，以钟声衬托愁绪，意境清冷悠远。', category: '思乡' },
    { title: '渔歌子', author: '张志和', dynasty: '唐', content: '西塞山前白鹭飞，桃花流水鳜鱼肥。青箬笠，绿蓑衣，斜风细雨不须归。', translation: '西塞山前白鹭自由飞翔，桃花飘落春水上涨鳜鱼正肥。戴着青竹笠披着绿蓑衣，斜风细雨中不必要回家。', appreciation: '词中描绘了一幅清新的渔父图，表现出悠然自得的隐逸情趣。', category: '写景' },
    { title: '塞下曲', author: '卢纶', dynasty: '唐', content: '月黑雁飞高，单于夜遁逃。欲将轻骑逐，大雪满弓刀。', translation: '月黑风高的夜里大雁飞得高高，单于趁着夜色偷偷逃跑。想要率轻骑兵去追击，大雪落满了弓箭和佩刀。', appreciation: '诗人写边塞将士雪夜追敌的场面，表现了英勇豪迈的气概。', category: '边塞' },
    { title: '早春呈水部张十八员外', author: '韩愈', dynasty: '唐', content: '天街小雨润如酥，草色遥看近却无。最是一年春好处，绝胜烟柳满皇都。', translation: '京城街上飘洒的小雨润滑如酥，远看草色青青走近却看不大清。这正是一年里春光最好的时候，远远胜过满城绿柳的暮春。', appreciation: '诗人准确地写出了早春草色若隐若现的特点，表达了对早春的喜爱。', category: '春景' },
    { title: '望洞庭', author: '刘禹锡', dynasty: '唐', content: '湖光秋月两相和，潭面无风镜未磨。遥望洞庭山水翠，白银盘里一青螺。', translation: '湖光和秋月相互映衬，湖面没有风像没有打磨的铜镜。远远望去洞庭湖山水一片青翠，就像白银盘里放着一只青色的田螺。', appreciation: '诗人以银盘青螺的比喻写洞庭山水，想象奇巧，色彩明丽。', category: '写景' },
    { title: '浪淘沙', author: '刘禹锡', dynasty: '唐', content: '九曲黄河万里沙，浪淘风簸自天涯。如今直上银河去，同到牵牛织女家。', translation: '弯弯曲曲的黄河裹挟着万里黄沙，波浪翻滚风浪颠簸来自天涯。如今我要乘风直上银河去，一同到牵牛织女的家中。', appreciation: '诗人写黄河的雄伟，又驰骋想象上溯银河，豪迈浪漫。', category: '写景' },
    { title: '赋得古原草送别', author: '白居易', dynasty: '唐', content: '离离原上草，一岁一枯荣。野火烧不尽，春风吹又生。远芳侵古道，晴翠接荒城。又送王孙去，萋萋满别情。', translation: '原野上茂盛的青草，每年枯萎一次又繁荣一次。野火也烧不尽它，春风一吹又蓬勃生长。远处的芳草蔓延到古道，阳光下翠绿的草色连着荒城。又在这里送别友人远去，茂盛的青草也满是离别之情。', appreciation: '诗人借野草顽强的生命力，写出离别之情，前四句传诵千古。', category: '送别' },
    { title: '忆江南', author: '白居易', dynasty: '唐', content: '江南好，风景旧曾谙。日出江花红胜火，春来江水绿如蓝。能不忆江南？', translation: '江南好啊，那里的风景我曾十分熟悉。太阳升起时江边的花比火还要红，春天到来时江水绿得像蓝草。怎么能不回忆江南呢？', appreciation: '词中用鲜明的色彩回忆江南春色，表达了对江南的深情眷恋。', category: '写景' },
    { title: '悯农（其一）', author: '李绅', dynasty: '唐', content: '锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。', translation: '农民在正午的烈日下锄禾，汗水滴落在禾苗下的泥土里。有谁知道盘中的饭菜，每一粒都饱含着辛苦的劳动？', appreciation: '诗人写农民劳作的辛苦，劝人珍惜粮食，语言朴素而意味深长。', category: '悯农' },
    { title: '悯农（其二）', author: '李绅', dynasty: '唐', content: '春种一粒粟，秋收万颗子。四海无闲田，农夫犹饿死。', translation: '春天播下一粒粟种，秋天能收获万颗粮食。天下没有一块荒田，可是农民仍有饿死的。', appreciation: '诗人以丰收反衬农民的悲惨命运，揭露了赋税沉重的社会现实。', category: '悯农' },
    { title: '清明', author: '杜牧', dynasty: '唐', content: '清明时节雨纷纷，路上行人欲断魂。借问酒家何处有，牧童遥指杏花村。', translation: '清明节这天细雨纷纷飘落，路上行人伤心落魄好像丢了魂。请问哪里有喝酒的酒家，牧童远远指着杏花盛开的村庄。', appreciation: '诗中写清明时节雨中行人的愁绪，结尾以杏花村酒家点染，意境悠远。', category: '节日' },
    { title: '江南春', author: '杜牧', dynasty: '唐', content: '千里莺啼绿映红，水村山郭酒旗风。南朝四百八十寺，多少楼台烟雨中。', translation: '千里江南莺啼婉转绿树映着红花，水乡山城酒旗在风中飘扬。南朝留下的四百八十座寺庙，多少楼台掩映在迷蒙的烟雨中。', appreciation: '诗人写江南春景的辽阔与迷蒙，又抒发对历史兴亡的感慨。', category: '春景' },
    { title: '泊秦淮', author: '杜牧', dynasty: '唐', content: '烟笼寒水月笼沙，夜泊秦淮近酒家。商女不知亡国恨，隔江犹唱后庭花。', translation: '轻烟笼罩着寒水月光笼罩着沙滩，夜里停泊在秦淮河靠近酒家。歌女不懂得亡国的悲痛，隔着江还在唱那首亡国之音后庭花。', appreciation: '诗人借商女唱曲讽刺统治者醉生梦死，表达了对国事的忧虑。', category: '咏史' },
    { title: '山行', author: '杜牧', dynasty: '唐', content: '远上寒山石径斜，白云生处有人家。停车坐爱枫林晚，霜叶红于二月花。', translation: '顺着弯曲的石径远远登上寒山，白云飘起的地方有人家居住。停下车是因为喜爱这傍晚的枫林，经霜的枫叶比二月的春花还红。', appreciation: '诗人写秋山红叶之美，一反悲秋的俗套，赞美了秋天的生机。', category: '秋景' },
    { title: '秋夕', author: '杜牧', dynasty: '唐', content: '银烛秋光冷画屏，轻罗小扇扑流萤。天阶夜色凉如水，卧看牵牛织女星。', translation: '银烛的秋光照着冷清的画屏，拿着轻巧的罗扇扑打飞舞的萤火虫。宫殿台阶前夜色清凉如水，躺着仰望天上的牵牛织女星。', appreciation: '诗中写宫女秋夜的孤寂生活，含蓄地表现了她的幽怨和寂寞。', category: '秋景' },
    { title: '乐游原', author: '李商隐', dynasty: '唐', content: '向晚意不适，驱车登古原。夕阳无限好，只是近黄昏。', translation: '傍晚时分心里有些不痛快，驾着车登上古老的乐游原。夕阳下的景色无限美好，只是可惜已经接近黄昏了。', appreciation: '诗人借夕阳美景抒发好景不长的感慨，含蓄地寄寓了迟暮之叹。', category: '抒怀' },
    { title: '商山早行', author: '温庭筠', dynasty: '唐', content: '晨起动征铎，客行悲故乡。鸡声茅店月，人迹板桥霜。', translation: '清晨起来赶路车马铃铛叮当响，旅途中思念家乡心中悲伤。鸡鸣声里茅草客店挂着残月，板桥的寒霜上印着行人的足迹。', appreciation: '诗人用六个名词组成早行图景，把旅途的辛苦和思乡写得真切动人。', category: '思乡' },
    { title: '元日', author: '王安石', dynasty: '宋', content: '爆竹声中一岁除，春风送暖入屠苏。千门万户曈曈日，总把新桃换旧符。', translation: '在爆竹声中旧的一年过去了，春风把暖意送进了屠苏酒里。千家万户迎着初升的太阳，都把旧的桃符换成新的桃符。', appreciation: '诗人写春节热闹欢庆的景象，也寄寓了推行新法的除旧布新之意。', category: '节日' },
    { title: '泊船瓜洲', author: '王安石', dynasty: '宋', content: '京口瓜洲一水间，钟山只隔数重山。春风又绿江南岸，明月何时照我还。', translation: '京口和瓜洲只隔着一条长江，钟山也只隔着几重山峦。春风又吹绿了长江南岸，明月什么时候才能照着我回家？', appreciation: '诗人用一个绿字写出春风的活力，表达了深切的思乡之情。', category: '思乡' },
    { title: '书湖阴先生壁', author: '王安石', dynasty: '宋', content: '茅檐长扫净无苔，花木成畦手自栽。一水护田将绿绕，两山排闼送青来。', translation: '茅草屋檐下经常打扫干干净净没有青苔，花草树木成行成畦都是主人亲手栽种。一条小河环绕着绿油油的农田，两座青山推开门把青翠送来。', appreciation: '诗人写农家院落的整洁清幽，赞美了主人的勤劳和生活情趣。', category: '写景' },
    { title: '六月二十七日望湖楼醉书', author: '苏轼', dynasty: '宋', content: '黑云翻墨未遮山，白雨跳珠乱入船。卷地风来忽吹散，望湖楼下水如天。', translation: '乌云像打翻的墨汁还没遮住山头，白色的雨点像跳动的珍珠乱打进船里。一阵狂风卷地而来忽然把云吹散，望湖楼下湖水平静得像天空一样。', appreciation: '诗人写夏日暴雨来去迅速的景象，色彩对比鲜明，画面感极强。', category: '夏景' },
    { title: '饮湖上初晴后雨', author: '苏轼', dynasty: '宋', content: '水光潋滟晴方好，山色空蒙雨亦奇。欲把西湖比西子，淡妆浓抹总相宜。', translation: '晴天时西湖水光波动的样子最美，雨天时山色迷蒙也很奇妙。要把西湖比作美女西施，无论是淡妆还是浓抹都同样合适。', appreciation: '诗人以美人喻西湖，写出了西湖晴雨皆宜的美，成为千古名喻。', category: '写景' },
    { title: '题西林壁', author: '苏轼', dynasty: '宋', content: '横看成岭侧成峰，远近高低各不同。不识庐山真面目，只缘身在此山中。', translation: '从正面看是连绵的山岭从侧面看是陡峭的山峰，远近高低看去各不相同。认不清庐山的真实面目，只因为自己就身处在这座山中。', appreciation: '诗中写庐山千姿百态，又蕴含当局者迷旁观者清的哲理。', category: '哲理' },
    { title: '惠崇春江晚景', author: '苏轼', dynasty: '宋', content: '竹外桃花三两枝，春江水暖鸭先知。蒌蒿满地芦芽短，正是河豚欲上时。', translation: '竹林外开放着三两枝桃花，江水变暖鸭子最先察觉。满地是蒌蒿芦芽还很短，正是河豚要逆流而上的时候。', appreciation: '诗人为画作题诗，把画中的春景写得生机盎然富有情趣。', category: '春景' },
    { title: '夏日绝句', author: '李清照', dynasty: '宋', content: '生当作人杰，死亦为鬼雄。至今思项羽，不肯过江东。', translation: '活着就要做人中的豪杰，死了也要做鬼中的英雄。至今人们还思念项羽，他宁死不肯渡江逃回江东。', appreciation: '诗人借赞项羽讽刺南宋偏安苟且，表达了慷慨悲壮的爱国情怀。', category: '咏史' },
    { title: '示儿', author: '陆游', dynasty: '宋', content: '死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。', translation: '本来就知道人死后万事皆空，只悲痛没能看到祖国统一。当朝廷军队收复中原那一天，家祭时别忘了告诉你的父亲。', appreciation: '诗人在临终前仍念念不忘收复失地，表现出深沉执着的爱国之情。', category: '爱国' },
    { title: '秋夜将晓出篱门迎凉有感', author: '陆游', dynasty: '宋', content: '三万里河东入海，五千仞岳上摩天。遗民泪尽胡尘里，南望王师又一年。', translation: '三万里长的黄河东流入海，五千仞高的华山直插云天。沦陷区百姓的眼泪在胡尘里已经流尽，向南盼望朝廷大军又是一年。', appreciation: '诗人写大好河山的壮丽和遗民的苦难，表达对收复中原的渴望。', category: '爱国' },
    { title: '四时田园杂兴（其一）', author: '范成大', dynasty: '宋', content: '昼出耘田夜绩麻，村庄儿女各当家。童孙未解供耕织，也傍桑阴学种瓜。', translation: '白天到田里锄草夜里搓麻线，村里的男女各自操持家务。小孙子还不懂耕田织布，也在桑树荫下学着种瓜。', appreciation: '诗人写农家男女老少各有所忙，展现了一幅朴素的田园劳作图。', category: '田园' },
    { title: '四时田园杂兴（其二）', author: '范成大', dynasty: '宋', content: '梅子金黄杏子肥，麦花雪白菜花稀。日长篱落无人过，惟有蜻蜓蛱蝶飞。', translation: '梅子变得金黄杏子也长得肥大，麦花雪白油菜花已经稀少。白天变长篱笆旁无人经过，只有蜻蜓和蝴蝶在飞舞。', appreciation: '诗人写初夏农村的寂静和果实的丰收，色彩明丽，恬淡自然。', category: '田园' },
    { title: '小池', author: '杨万里', dynasty: '宋', content: '泉眼无声惜细流，树阴照水爱晴柔。小荷才露尖尖角，早有蜻蜓立上头。', translation: '泉眼悄无声息地珍惜着细细的水流，树荫倒映水面喜爱这晴日的柔美。小小的荷叶才露出尖尖的角，早有蜻蜓立在上面。', appreciation: '诗人捕捉初夏小池的细节，写得细腻生动，富有情趣。', category: '夏景' },
    { title: '晓出净慈寺送林子方', author: '杨万里', dynasty: '宋', content: '毕竟西湖六月中，风光不与四时同。接天莲叶无穷碧，映日荷花别样红。', translation: '毕竟是六月的西湖，风光与其他时节大不相同。绿色的荷叶无边无际接天连水，朝阳映照下的荷花格外红艳。', appreciation: '诗人写西湖夏日的壮美荷景，色彩浓烈，气势开阔。', category: '夏景' },
    { title: '春日', author: '朱熹', dynasty: '宋', content: '胜日寻芳泗水滨，无边光景一时新。等闲识得东风面，万紫千红总是春。', translation: '在晴朗的好日子到泗水河边寻访春光，无边无际的景色焕然一新。轻易就认识了春风的面貌，万紫千红都是春天的体现。', appreciation: '诗人写寻春所见，又暗含求学悟道的喜悦，景中寓理。', category: '春景' },
    { title: '观书有感', author: '朱熹', dynasty: '宋', content: '半亩方塘一鉴开，天光云影共徘徊。问渠那得清如许？为有源头活水来。', translation: '半亩大的方塘像一面镜子打开，天光云影倒映其中不停地流动。要问这水怎么这样清澈？因为有源头活水源源不断地流来。', appreciation: '诗人以塘水清澈比喻读书明理，强调不断学习才能保持心境澄明。', category: '哲理' },
    { title: '题临安邸', author: '林升', dynasty: '宋', content: '山外青山楼外楼，西湖歌舞几时休？暖风熏得游人醉，直把杭州作汴州。', translation: '青山之外还有青山楼外还有楼，西湖边的歌舞什么时候才能停歇？暖风把游人吹得醉醺醺的，简直把杭州当成了故都汴州。', appreciation: '诗人讽刺南宋统治者苟且偷安沉迷享乐，表达忧愤之情。', category: '咏史' },
    { title: '游园不值', author: '叶绍翁', dynasty: '宋', content: '应怜屐齿印苍苔，小扣柴扉久不开。春色满园关不住，一枝红杏出墙来。', translation: '大概是园主人怜惜青苔怕被木屐踩坏，轻轻敲柴门好久也没人开。可是满园的春色是关不住的，一枝红杏伸到了墙外来。', appreciation: '诗人游园不遇却意外发现红杏出墙，写出了春意的蓬勃和不可阻挡。', category: '春景' },
    { title: '乡村四月', author: '翁卷', dynasty: '宋', content: '绿遍山原白满川，子规声里雨如烟。乡村四月闲人少，才了蚕桑又插田。', translation: '绿意铺满山原白水涨满河川，杜鹃声里细雨像烟雾一样。乡村四月很少有闲人，刚忙完采桑养蚕又去插秧。', appreciation: '诗人写江南初夏的景色和农忙景象，画面清新富有生活气息。', category: '田园' },
    { title: '墨梅', author: '王冕', dynasty: '元', content: '我家洗砚池头树，朵朵花开淡墨痕。不要人夸好颜色，只留清气满乾坤。', translation: '我家洗砚池边的梅树，朵朵花开像淡淡的墨痕。不需要别人夸赞颜色好看，只愿留下清香的气息充满天地。', appreciation: '诗人借墨梅写自己不求人夸、只留清白的高洁志向。', category: '咏物' },
    { title: '石灰吟', author: '于谦', dynasty: '明', content: '千锤万凿出深山，烈火焚烧若等闲。粉骨碎身浑不怕，要留清白在人间。', translation: '经过千锤万凿才从深山中开采出来，烈火焚烧也像平常一样。就是粉身碎骨也全不怕，要把清白留在人世间。', appreciation: '诗人借石灰的烧制过程，表达自己不怕牺牲、坚守清白的高尚品格。', category: '咏物' },
    { title: '竹石', author: '郑燮', dynasty: '清', content: '咬定青山不放松，立根原在破岩中。千磨万击还坚劲，任尔东西南北风。', translation: '紧紧咬住青山不肯放松，原来根扎在破裂的岩石中。经过千般折磨万般打击依然坚劲，任凭东西南北风怎样吹。', appreciation: '诗人借竹子的坚韧写人的刚强不屈，表现了坚定的意志和节操。', category: '咏物' },
    { title: '所见', author: '袁枚', dynasty: '清', content: '牧童骑黄牛，歌声振林樾。意欲捕鸣蝉，忽然闭口立。', translation: '牧童骑着黄牛，歌声震动了树林。想要去捕捉鸣叫的蝉，忽然闭上嘴站住不动。', appreciation: '诗人捕捉牧童捕蝉的瞬间，写得天真活泼富有童趣。', category: '田园' },
    { title: '村居', author: '高鼎', dynasty: '清', content: '草长莺飞二月天，拂堤杨柳醉春烟。儿童散学归来早，忙趁东风放纸鸢。', translation: '二月里草长莺飞，杨柳轻拂堤岸陶醉在春烟中。孩子们放学回来得早，赶忙趁着东风放起风筝。', appreciation: '诗人写早春乡村的景色和儿童放风筝的欢乐，洋溢着春的生机。', category: '春景' },
    { title: '己亥杂诗', author: '龚自珍', dynasty: '清', content: '九州生气恃风雷，万马齐喑究可哀。我劝天公重抖擞，不拘一格降人才。', translation: '中国的生机要靠风雷般的变革，万马无声的局面实在可悲。我劝老天爷重新振作精神，打破常规降下各种人才来。', appreciation: '诗人呼吁变革现实选拔人才，表现出强烈的忧国忧民情怀。', category: '抒怀' },
    { title: '己亥杂诗·落红', author: '龚自珍', dynasty: '清', content: '浩荡离愁白日斜，吟鞭东指即天涯。落红不是无情物，化作春泥更护花。', translation: '夕阳西下时我怀着浩荡的离愁离别京城，马鞭东指就要走向天涯。落花并不是无情之物，化作春泥还能滋养新的花朵。', appreciation: '诗人以落花自喻，表达虽辞官仍愿为国奉献的赤诚之心。', category: '抒怀' },
    { title: '关雎', author: '佚名', dynasty: '先秦', content: '关关雎鸠，在河之洲。窈窕淑女，君子好逑。参差荇菜，左右流之。窈窕淑女，寤寐求之。求之不得，寤寐思服。悠哉悠哉，辗转反侧。', translation: '雎鸠鸟关关地叫着停在水中的沙洲上，美丽贤淑的姑娘是君子好的配偶。长短不齐的荇菜在左右两边顺水漂流，美丽贤淑的姑娘日日夜夜都想要追求。追求不到手便日思夜想，思念之情悠悠漫长，翻来覆去难以入睡。', appreciation: '这是诗经的开篇，写男子对女子的爱慕追求，情感真挚热烈。', category: '爱情' },
    { title: '蒹葭', author: '佚名', dynasty: '先秦', content: '蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。', translation: '河边的芦苇青苍苍，白露结成了霜。所说的那个人，在水的那一方。逆流而上去追寻她，道路险阻又漫长。顺流而下去找寻她，她仿佛就在水的中央。', appreciation: '诗中写对心上人的追寻和可望而不可即的怅惘，意境朦胧优美。', category: '爱情' },
    { title: '观沧海', author: '曹操', dynasty: '汉', content: '东临碣石，以观沧海。水何澹澹，山岛竦峙。树木丛生，百草丰茂。秋风萧瑟，洪波涌起。日月之行，若出其中；星汉灿烂，若出其里。幸甚至哉，歌以咏志。', translation: '东行登上碣石山，来观赏浩瀚的大海。海水起伏动荡，山岛高高地耸立。树木丛聚生长，百草丰盛茂密。秋风吹过瑟瑟作响，巨大的波浪涌起。日月运行好像从大海中升起，银河灿烂好像也从大海中产生。庆幸极了，用诗歌来抒发情怀。', appreciation: '诗人借大海吞吐日月星辰的景象，抒发了统一天下的雄心壮志。', category: '抒怀' },
    { title: '饮酒', author: '陶渊明', dynasty: '晋', content: '结庐在人境，而无车马喧。问君何能尔？心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此中有真意，欲辨已忘言。', translation: '居住在人世间却没有车马的喧闹。问我怎能这样？心志高远住处自然偏僻。在东篱下采摘菊花，悠闲地望见南山。山中的气象傍晚时分最美，飞鸟结伴飞回巢中。这里边有真正的意趣，想要辨说却已忘了语言。', appreciation: '诗人写归隐田园的闲适生活，表现了淡泊宁静的心境和超脱情怀。', category: '田园' },
    { title: '送杜少府之任蜀州', author: '王勃', dynasty: '唐', content: '城阙辅三秦，风烟望五津。与君离别意，同是宦游人。海内存知己，天涯若比邻。无为在歧路，儿女共沾巾。', translation: '三秦之地护卫着长安城，遥望蜀地风烟迷茫。和你离别的情意，因为我们也都是在外做官的人。四海之内只要有知己，远在天边也像近邻一样。不要在分别的岔路口，像儿女那样让眼泪沾湿手帕。', appreciation: '诗人以海内存知己的名句宽慰友人，送别诗写得胸襟开阔格调高昂。', category: '送别' },
    { title: '次北固山下', author: '王湾', dynasty: '唐', content: '客路青山外，行舟绿水前。潮平两岸阔，风正一帆悬。海日生残夜，江春入旧年。乡书何处达？归雁洛阳边。', translation: '旅途延伸到青山之外，小船行进在绿水之前。潮水涨平两岸显得宽阔，风向正顺高悬着一片白帆。海上的旭日从残夜中升起，江上的春意闯入了旧年。家书要寄到哪里？托归雁带到洛阳边。', appreciation: '诗人写旅途所见，海日残夜江春旧年一句写尽时序交替之妙，蕴含思乡之情。', category: '思乡' },
    { title: '使至塞上', author: '王维', dynasty: '唐', content: '单车欲问边，属国过居延。征蓬出汉塞，归雁入胡天。大漠孤烟直，长河落日圆。萧关逢候骑，都护在燕然。', translation: '轻车简从要去边关慰问，经过居延属国。像随风飘飞的蓬草飘出汉地边塞，像归雁飞入胡地的天空。茫茫大漠中一缕孤烟笔直升起，黄河边上落日浑圆。在萧关遇到巡逻的骑兵，得知都护正在燕然前线。', appreciation: '诗中大漠孤烟直长河落日圆一句写出边塞壮阔雄奇的景象，画面感极强。', category: '边塞' },
    { title: '闻王昌龄左迁龙标遥有此寄', author: '李白', dynasty: '唐', content: '杨花落尽子规啼，闻道龙标过五溪。我寄愁心与明月，随君直到夜郎西。', translation: '杨花落尽杜鹃声声啼叫，听说你被贬到龙标要经过五溪。我把愁苦的心思寄托给明月，随着你一直走到夜郎以西。', appreciation: '诗人把愁心寄予明月，表达对友人被贬的牵挂和深厚情谊。', category: '送别' },
    { title: '行路难', author: '李白', dynasty: '唐', content: '金樽清酒斗十千，玉盘珍羞直万钱。停杯投箸不能食，拔剑四顾心茫然。欲渡黄河冰塞川，将登太行雪满山。闲来垂钓碧溪上，忽复乘舟梦日边。行路难！行路难！多歧路，今安在？长风破浪会有时，直挂云帆济沧海。', translation: '金杯里盛着价值十千的清酒，玉盘里装着价值万钱的佳肴。放下杯筷吃不下去，拔出剑四顾心中茫然。想渡黄河却被冰雪堵塞河道，想登太行山却大雪封山。闲暇时像姜太公在碧绿的溪边垂钓，又像伊尹梦见乘船经过太阳旁边。行路难啊行路难，岔路这么多如今身在何处？总有一天会乘长风破万里浪，挂起云帆横渡沧海。', appreciation: '诗人写仕途受阻的苦闷，又以乘风破浪表达对未来的坚定信念。', category: '抒怀' },
    { title: '望岳', author: '杜甫', dynasty: '唐', content: '岱宗夫如何？齐鲁青未了。造化钟神秀，阴阳割昏晓。荡胸生曾云，决眦入归鸟。会当凌绝顶，一览众山小。', translation: '泰山到底是什么样？在齐鲁大地上青色绵延不尽。大自然把神奇秀美都汇聚在这里，山的南北一面昏暗一面明亮。层云升起激荡胸怀，睁大眼睛看归鸟飞入山中。一定要登上泰山的最高峰，俯瞰众山都显得矮小。', appreciation: '诗人写泰山的雄伟，结尾抒发了不怕困难攀登顶峰的豪情壮志。', category: '抒怀' },
    { title: '春望', author: '杜甫', dynasty: '唐', content: '国破山河在，城春草木深。感时花溅泪，恨别鸟惊心。烽火连三月，家书抵万金。白头搔更短，浑欲不胜簪。', translation: '国都沦陷山河依然存在，春天的长安城草木茂盛荒凉。感伤时事连花都落泪，怨恨离别连鸟鸣都惊心。战火连绵已经三个月，一封家书抵得上万两黄金。满头白发越搔越短，简直插不住发簪了。', appreciation: '诗人写安史之乱中长安的残破和自己的忧国思家之情，沉痛感人。', category: '爱国' },
    { title: '茅屋为秋风所破歌', author: '杜甫', dynasty: '唐', content: '八月秋高风怒号，卷我屋上三重茅。安得广厦千万间，大庇天下寒士俱欢颜！风雨不动安如山。呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！', translation: '八月秋深狂风怒号，卷走我屋顶上三层茅草。怎样才能有千万间宽敞的大房子，庇护天下贫寒的读书人都露出笑颜！风雨中安然不动稳如泰山。唉，什么时候眼前能出现这样的房子，哪怕我自己的茅屋破了冻死也心甘！', appreciation: '诗人由自己的困苦推及天下寒士，表达了忧国忧民的博大胸怀。', category: '抒怀' },
    { title: '白雪歌送武判官归京', author: '岑参', dynasty: '唐', content: '北风卷地白草折，胡天八月即飞雪。忽如一夜春风来，千树万树梨花开。散入珠帘湿罗幕，狐裘不暖锦衾薄。瀚海阑干百丈冰，愁云惨淡万里凝。中军置酒饮归客，胡琴琵琶与羌笛。纷纷暮雪下辕门，风掣红旗冻不翻。轮台东门送君去，去时雪满天山路。山回路转不见君，雪上空留马行处。', translation: '北风席卷大地白草都被吹折，胡地八月就飞起了大雪。忽然好像一夜春风吹来，千万棵树上梨花盛开。雪花散入珠帘打湿了丝幕，狐皮袍子不暖锦被也显得单薄。大沙漠里纵横交错结着百丈厚冰，万里愁云惨淡凝结不散。中军帐里摆酒宴饮归客，奏起胡琴琵琶和羌笛。傍晚大雪纷纷落在军营门外，风扯着红旗因为冻结而不能飘动。在轮台东门送你离去，走时大雪铺满了天山的路。山路曲折看不见你的身影，雪地上只留下马走过的痕迹。', appreciation: '诗人以千树万树梨花开的奇喻写雪景壮美，又写雪中送别的深情。', category: '边塞' },
    { title: '酬乐天扬州初逢席上见赠', author: '刘禹锡', dynasty: '唐', content: '巴山楚水凄凉地，二十三年弃置身。怀旧空吟闻笛赋，到乡翻似烂柯人。沉舟侧畔千帆过，病树前头万木春。今日听君歌一曲，暂凭杯酒长精神。', translation: '在巴山楚水这样荒凉的地方，我被弃置了二十三年。怀念故友只能空吟闻笛赋，回到家乡倒像那看棋烂柯的烂柯人。沉船旁边有千帆驶过，病树前面有万木逢春。今天听了你唱的这首歌，暂且借这杯酒振奋一下精神。', appreciation: '诗中沉舟病树一句蕴含新陈代谢的哲理，表现出豁达乐观的胸襟。', category: '抒怀' },
    { title: '观刈麦', author: '白居易', dynasty: '唐', content: '田家少闲月，五月人倍忙。夜来南风起，小麦覆陇黄。妇姑荷箪食，童稚携壶浆。相随饷田去，丁壮在南冈。足蒸暑土气，背灼炎天光。力尽不知热，但惜夏日长。复有贫妇人，抱子在其旁。右手秉遗穗，左臂悬敝筐。家田输税尽，拾此充饥肠。今我何功德，曾不事农桑。吏禄三百石，岁晏有余粮。念此私自愧，尽日不能忘。', translation: '农家很少有清闲的月份，五月里人们加倍繁忙。夜里南风吹起，小麦盖满田垄一片金黄。妇女们挑着饭菜，孩子们提着水壶。一起到田里送饭，壮劳力正在南面的山冈上割麦。脚下蒸腾着暑热的地气，背上烤着炎热的阳光。力气耗尽不觉得热，只珍惜夏天的白天长。还有一个贫苦的妇人，抱着孩子在他身旁。右手捡拾遗落的麦穗，左臂挎着破旧的筐。家里的田地为了交税都卖光了，拾些麦穗来填饱肚子。如今我有什么功德，竟然不从事农桑劳作。做官俸禄三百石，年底还有余粮。想到这些心里暗自惭愧，整天不能忘怀。', appreciation: '诗人写麦收时农民的辛苦和贫妇的悲惨，表现了对劳动人民的同情和自责。', category: '悯农' },
    { title: '钱塘湖春行', author: '白居易', dynasty: '唐', content: '孤山寺北贾亭西，水面初平云脚低。几处早莺争暖树，谁家新燕啄春泥。乱花渐欲迷人眼，浅草才能没马蹄。最爱湖东行不足，绿杨阴里白沙堤。', translation: '在孤山寺北贾亭西边，湖面刚刚涨平云气低垂。几处早来的黄莺争着飞向向阳的暖树，不知谁家新来的燕子衔着春泥筑巢。杂乱的野花渐渐要迷乱人的眼睛，浅浅的青草刚能遮没马蹄。最爱湖东的景色走也走不够，绿杨荫里的白沙堤最惹人喜爱。', appreciation: '诗人写早春西湖的勃勃生机，字里行间洋溢着对春光的喜爱。', category: '春景' },
    { title: '雁门太守行', author: '李贺', dynasty: '唐', content: '黑云压城城欲摧，甲光向日金鳞开。角声满天秋色里，塞上燕脂凝夜紫。半卷红旗临易水，霜重鼓寒声不起。报君黄金台上意，提携玉龙为君死。', translation: '黑云压城城墙好像要被摧毁，铠甲在阳光下闪着金色的鳞光。号角声响彻秋色满天的边塞，塞上的胭脂在夜里凝成紫色。半卷着红旗逼近易水，霜重鼓寒鼓声沉闷不响。为报答君王黄金台上的厚意，提着宝剑甘愿为您战死沙场。', appreciation: '诗人以奇丽的色彩写战争的激烈悲壮，表现将士报效国家的决心。', category: '边塞' },
    { title: '赤壁', author: '杜牧', dynasty: '唐', content: '折戟沉沙铁未销，自将磨洗认前朝。东风不与周郎便，铜雀春深锁二乔。', translation: '一支折断的铁戟沉埋在沙中没有销蚀，自己拿来磨洗认出是前朝的遗物。如果当年东风不给周瑜方便，那么大乔小乔就会被锁在铜雀台里了。', appreciation: '诗人借一件古物引发对历史的评论，含蓄地抒发怀才不遇的感慨。', category: '咏史' },
    { title: '夜雨寄北', author: '李商隐', dynasty: '唐', content: '君问归期未有期，巴山夜雨涨秋池。何当共剪西窗烛，却话巴山夜雨时。', translation: '你问我什么时候回去，归期还没有定，巴山的夜雨涨满了秋天的池塘。什么时候能一起在西窗下剪烛夜谈，再来诉说今夜巴山夜雨的情景。', appreciation: '诗人以夜雨涨池写羁旅之愁，又想象他日重逢共话的情景，曲折深情。', category: '思乡' },
    { title: '无题', author: '李商隐', dynasty: '唐', content: '相见时难别亦难，东风无力百花残。春蚕到死丝方尽，蜡炬成灰泪始干。晓镜但愁云鬓改，夜吟应觉月光寒。蓬山此去无多路，青鸟殷勤为探看。', translation: '相见很难离别更难，东风无力百花凋残。春蚕到死吐丝才尽，蜡烛烧成灰烛泪才干。早晨照镜只愁云鬓改变颜色，夜里吟诗应觉月光寒冷。蓬莱山离这里没有多远，希望青鸟殷勤地替我探看。', appreciation: '诗中以春蚕蜡炬比喻至死不渝的深情，成为歌颂奉献精神的名句。', category: '爱情' },
    { title: '相见欢', author: '李煜', dynasty: '五代', content: '无言独上西楼，月如钩。寂寞梧桐深院锁清秋。剪不断，理还乱，是离愁。别是一般滋味在心头。', translation: '默默无言独自登上西楼，天上的月亮像一把弯钩。寂寞的梧桐立在深院里锁住了清冷的秋天。剪也剪不断，理也理不清，这就是离别的愁苦。另一种滋味涌上心头。', appreciation: '词人以丝喻愁写亡国之痛，把抽象的愁苦写得真切可感，凄婉动人。', category: '抒怀' },
    { title: '渔家傲', author: '范仲淹', dynasty: '宋', content: '塞下秋来风景异，衡阳雁去无留意。四面边声连角起，千嶂里，长烟落日孤城闭。浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地，人不寐，将军白发征夫泪。', translation: '边塞一到秋天风景就格外不同，大雁飞向衡阳毫无留恋之意。四面的边塞之声伴着号角响起，在群山之中，长烟落日下一座孤城紧紧关闭着城门。饮一杯浊酒思念万里之外的家乡，可是边功未立归家无期。羌笛声悠扬霜满大地，人们都睡不着，将军白了头发士兵流下眼泪。', appreciation: '词人写边塞生活的艰苦和思乡之情，开豪放词风的先声。', category: '边塞' },
    { title: '浣溪沙', author: '晏殊', dynasty: '宋', content: '一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？无可奈何花落去，似曾相识燕归来。小园香径独徘徊。', translation: '听一支新曲饮一杯美酒，天气和亭台还和去年一样。夕阳西下什么时候才能回来？花儿无可奈何地落去，似曾相识的燕子又飞回来了。我独自在小园的花径上徘徊。', appreciation: '词人借花落燕归感叹时光流逝，无可奈何一句写尽人生无可奈何的怅惘。', category: '抒怀' },
    { title: '登飞来峰', author: '王安石', dynasty: '宋', content: '飞来山上千寻塔，闻说鸡鸣见日升。不畏浮云遮望眼，自缘身在最高层。', translation: '飞来峰上矗立着千寻高塔，听说鸡鸣时就能看到太阳升起。不怕浮云遮住远望的眼睛，只因为我站在最高的地方。', appreciation: '诗中蕴含站得高看得远、不惧阻碍的哲理，表现诗人的远大抱负。', category: '哲理' },
    { title: '江城子·密州出猎', author: '苏轼', dynasty: '宋', content: '老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。为报倾城随太守，亲射虎，看孙郎。酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼。', translation: '老夫我暂且发一发少年的狂气，左手牵着黄犬，右手擎着苍鹰，戴着锦帽穿着貂裘，率领千骑席卷平冈。为了报答全城随我出猎的百姓，我要像孙权那样亲自射虎。酒喝得痛快胸怀更加开阔。两鬓微微发白，又有什么关系！什么时候皇帝能像派冯唐那样派人来赦免我？我定要拉开雕弓如满月，朝西北望，射向那天狼星一样的敌人。', appreciation: '词人写狩猎的豪壮场面，抒发了抗敌报国的壮志豪情。', category: '抒怀' },
    { title: '水调歌头', author: '苏轼', dynasty: '宋', content: '明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。', translation: '明月什么时候才有？举着酒杯问青天。不知天上的宫殿，今夜是哪一年。我想乘风飞回天上，又怕那美玉做的楼宇，高处冷得受不了。起身跳舞伴着清影，哪像在人间。月光转过朱红色的楼阁，低低地照进雕花的窗户，照着失眠的人。月亮不该有什么怨恨，为什么总是在人离别时圆呢？人有悲伤欢乐离别相聚，月亮有阴暗晴朗圆满残缺，这些事自古以来就难以周全。只愿人们都能长久健康，即使相隔千里也能共赏这美好的月光。', appreciation: '词人借月抒怀，表达了对亲人的思念和对人生聚散的旷达态度。', category: '思乡' },
    { title: '游山西村', author: '陆游', dynasty: '宋', content: '莫笑农家腊酒浑，丰年留客足鸡豚。山重水复疑无路，柳暗花明又一村。箫鼓追随春社近，衣冠简朴古风存。从今若许闲乘月，拄杖无时夜叩门。', translation: '不要笑话农家腊月酿的酒浑浊，丰收之年他们款待客人鸡肉猪肉管够。山峦重叠水流曲折怀疑无路可走，柳色暗淡花光明丽又出现一个村庄。吹箫击鼓的人结队而过春社将近，衣冠简朴保留着古人的风尚。从今以后如果允许我闲暇时乘着月色，我会拄着拐杖随时来敲你家的门。', appreciation: '诗中山重水复柳暗花明一句写景又含哲理，表现困境中转机的希望。', category: '哲理' },
    { title: '南乡子·登京口北固亭有怀', author: '辛弃疾', dynasty: '宋', content: '何处望神州？满眼风光北固楼。千古兴亡多少事？悠悠。不尽长江滚滚流。年少万兜鍪，坐断东南战未休。天下英雄谁敌手？曹刘。生子当如孙仲谋。', translation: '到哪里去眺望中原故土？满眼风光尽在北固楼上。千古以来有多少兴亡之事？悠悠漫长。就像那滚滚东流的长江水没有尽头。年轻时就统领百万大军，占据东南一带征战不休。天下的英雄谁是他的对手？只有曹操刘备。生儿子就应当像孙权那样。', appreciation: '词人借赞孙权讽刺南宋朝廷软弱，抒发收复中原的壮志难酬之愤。', category: '咏史' },
    { title: '破阵子·为陈同甫赋壮词以寄之', author: '辛弃疾', dynasty: '宋', content: '醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声。沙场秋点兵。马作的卢飞，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！', translation: '醉梦里挑亮灯端详宝剑，梦中回到号角连天的军营。把八百里烤牛肉分给部下享用，各种乐器奏响边塞雄壮的乐曲。秋天的战场上正在检阅军队。战马像的卢一样飞奔，弓弦响如霹雳令人心惊。本想替君王完成统一天下的大事，赢得生前死后的美名。可惜头上已生出白发！', appreciation: '词人追忆军旅生活抒发报国壮志，结尾白发一句写尽壮志未酬的悲愤。', category: '爱国' },
    { title: '过零丁洋', author: '文天祥', dynasty: '宋', content: '辛苦遭逢起一经，干戈寥落四周星。山河破碎风飘絮，身世浮沉雨打萍。惶恐滩头说惶恐，零丁洋里叹零丁。人生自古谁无死？留取丹心照汗青。', translation: '我一生辛苦从读书科举入仕，在抗元斗争中已经度过四年。祖国山河破碎像风中飘飞的柳絮，我自己身世浮沉像雨中漂打的浮萍。在惶恐滩头诉说惶恐不安，在零丁洋里慨叹孤苦零丁。人自古以来谁能免于一死？要留下这颗赤诚之心光照史册。', appreciation: '诗人以丹心照汗青表达视死如归的气节，成为千古传诵的爱国名句。', category: '爱国' },
    { title: '天净沙·秋思', author: '马致远', dynasty: '元', content: '枯藤老树昏鸦，小桥流水人家，古道西风瘦马。夕阳西下，断肠人在天涯。', translation: '枯藤缠绕着老树黄昏时归巢的乌鸦，小桥下流水潺潺旁有人家，古老的道路上西风吹着瘦马。夕阳西下时，断肠的游子漂泊在天涯。', appreciation: '这首小令用几个名词组合成秋郊夕照图，把游子的乡愁写得淋漓尽致。', category: '思乡' },
    { title: '山坡羊·潼关怀古', author: '张养浩', dynasty: '元', content: '峰峦如聚，波涛如怒，山河表里潼关路。望西都，意踌躇。伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦；亡，百姓苦。', translation: '华山的山峰像聚拢过来，黄河的波涛像在发怒，山河内外是潼关的道路。望着西边的长安，心中犹豫徘徊。伤心的是秦汉故地经过之处，万间宫殿都化作了泥土。王朝兴起，百姓受苦；王朝灭亡，百姓也受苦。', appreciation: '曲中兴亡百姓皆苦一句直指历史本质，表现了对百姓疾苦的深切同情。', category: '咏史' },
    { title: '江南', author: '汉乐府', dynasty: '汉', content: '江南可采莲，莲叶何田田。鱼戏莲叶间。鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。', translation: '江南正是采莲的好时节，莲叶多么茂盛圆润。鱼儿在莲叶间嬉戏，一会儿在东边，一会儿在西边，一会儿在南边，一会儿在北边。', appreciation: '这首乐府民歌用回环往复的句式写鱼戏莲叶，展现江南水乡采莲的欢乐景象。', category: '民歌' },
    { title: '长歌行', author: '汉乐府', dynasty: '汉', content: '青青园中葵，朝露待日晞。阳春布德泽，万物生光辉。常恐秋节至，焜黄华叶衰。百川东到海，何时复西归？少壮不努力，老大徒伤悲。', translation: '园中葵菜青青一片，清晨的露水等太阳出来晒干。春天布施恩泽，万物焕发光彩。常常担心秋天到来，花叶会枯黄衰败。百川向东流入大海，什么时候能再向西流回？年轻时不努力，到老了只能白白地悲伤。', appreciation: '诗中以园葵、春光、百川为喻，劝勉人珍惜年华及时努力。', category: '哲理' },
    { title: '敕勒歌', author: '北朝民歌', dynasty: '南北朝', content: '敕勒川，阴山下。天似穹庐，笼盖四野。天苍苍，野茫茫，风吹草低见牛羊。', translation: '敕勒川在阴山脚下。天空像巨大的圆顶帐篷，笼罩着四面的原野。天空蓝蓝的原野茫茫的，风吹低了牧草露出成群的牛羊。', appreciation: '这首民歌用朴素的语言描绘了草原辽阔苍茫的景象，气象雄浑。', category: '民歌' },
    { title: '木兰辞', author: '北朝民歌', dynasty: '南北朝', content: '唧唧复唧唧，木兰当户织。不闻机杼声，惟闻女叹息。问女何所思，问女何所忆。女亦无所思，女亦无所忆。昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。阿爷无大儿，木兰无长兄，愿为市鞍马，从此替爷征。', translation: '叹息声又起，木兰对着门织布。听不到织机的声音，只听到女儿在叹息。问她想什么回忆什么，她都说没有。昨夜看到征兵文书，可汗大举征兵，名册十二卷卷卷都有父亲的名字。父亲没有大儿子，木兰没有哥哥，愿意去买鞍马，从此代替父亲出征。', appreciation: '这首长篇叙事民歌塑造了花木兰代父从军的巾帼英雄形象，语言质朴明快。', category: '民歌' },
    { title: '龟虽寿', author: '曹操', dynasty: '汉', content: '神龟虽寿，犹有竟时。腾蛇乘雾，终为土灰。老骥伏枥，志在千里。烈士暮年，壮心不已。盈缩之期，不但在天。养怡之福，可得永年。', translation: '神龟虽然长寿，还是有终了的时候。腾蛇能乘云驾雾，最终也化为尘土。老马趴在马槽旁，志向仍在千里之外。有志之士即使到了晚年，壮志也不会消减。寿命长短不只由天定，保养身心得当可以延年益寿。', appreciation: '诗人以老骥伏枥自比，抒发了老当益壮自强不息的豪情壮志。', category: '抒怀' },
    { title: '短歌行', author: '曹操', dynasty: '汉', content: '对酒当歌，人生几何！譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧？唯有杜康。青青子衿，悠悠我心。但为君故，沉吟至今。呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。', translation: '面对美酒应当高歌，人的一生能有多长！就像早晨的露水，逝去的日子太多。慷慨激昂，忧思难以忘怀。用什么来解忧？只有杜康美酒。青青的是你的衣领，悠悠的是我的思念。只因为你的缘故，让我沉吟至今。鹿群呦呦鸣叫，吃着野地的艾蒿。我有贵客到来，弹瑟吹笙相迎。', appreciation: '诗人感慨人生短暂，表达了对贤才的渴求和建功立业的抱负。', category: '抒怀' },
    { title: '七步诗', author: '曹植', dynasty: '三国', content: '煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急。', translation: '煮豆子时燃烧豆秸，豆子在锅里哭泣。本来是同一条根上长出来的，煎熬何必这样急迫。', appreciation: '诗人以煮豆燃萁比喻兄弟相残，含蓄而沉痛地表达心中的悲愤。', category: '抒怀' },
    { title: '归园田居', author: '陶渊明', dynasty: '晋', content: '种豆南山下，草盛豆苗稀。晨兴理荒秽，带月荷锄归。道狭草木长，夕露沾我衣。衣沾不足惜，但使愿无违。', translation: '在南山下种豆，杂草茂盛豆苗稀少。清晨起来清除杂草，月夜里扛着锄头回家。道路狭窄草木丛生，傍晚的露水沾湿了衣裳。衣裳沾湿了不值得可惜，只要不违背自己的心愿就好。', appreciation: '诗人写归隐田园的劳作生活，表现了不慕荣利、坚守志向的情怀。', category: '田园' },
    { title: '木瓜', author: '佚名', dynasty: '先秦', content: '投我以木瓜，报之以琼琚。匪报也，永以为好也！', translation: '你送我木瓜，我拿美玉回报你。不是为了答谢，而是为了永远相好！', appreciation: '这首诗经小诗写礼尚往来，表达情谊长久不因物重而看重回报。', category: '友情' },
    { title: '采薇', author: '佚名', dynasty: '先秦', content: '昔我往矣，杨柳依依。今我来思，雨雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！', translation: '当初出征时杨柳随风摇曳，如今归来时大雪纷纷飘落。道路难行走得缓慢，又渴又饿。我心里悲伤，没有人知道我的哀愁！', appreciation: '诗中写戍边士兵归途的艰辛和哀伤，昔往今来的对比尤为动人。', category: '边塞' },
    { title: '静女', author: '佚名', dynasty: '先秦', content: '静女其姝，俟我于城隅。爱而不见，搔首踟蹰。', translation: '文静的姑娘真美丽，在城墙角等我。她躲藏起来看不见，让我抓耳挠腮徘徊不定。', appreciation: '诗中写男女约会的甜蜜与焦急，刻画了小伙子憨态可掬的形象。', category: '爱情' },
    { title: '硕鼠', author: '佚名', dynasty: '先秦', content: '硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。', translation: '大老鼠啊大老鼠，不要再吃我的黄黍！多年来一直供养你，你却不肯照顾我。发誓要离开你，到那安乐的地方。乐土啊乐土，那才是我安身的好去处。', appreciation: '诗中把剥削者比作大老鼠，表达劳动人民对苛政的痛恨和对乐土的向往。', category: '民歌' },
    { title: '陌上桑', author: '汉乐府', dynasty: '汉', content: '日出东南隅，照我秦氏楼。秦氏有好女，自名为罗敷。罗敷善蚕桑，采桑城南隅。青丝为笼系，桂枝为笼钩。', translation: '太阳从东南方升起，照在我秦家的楼上。秦家有个好姑娘，自己起名叫罗敷。罗敷善于养蚕采桑，在城南采桑叶。用青丝做篮子的系带，用桂枝做篮子的提钩。', appreciation: '这首乐府诗刻画了美丽勤劳的采桑女罗敷形象，侧面描写十分精彩。', category: '民歌' },
    { title: '十五从军征', author: '汉乐府', dynasty: '汉', content: '十五从军征，八十始得归。道逢乡里人，家中有阿谁？遥看是君家，松柏冢累累。', translation: '十五岁就参军出征，八十岁才得以回家。路上遇到同乡人，问家里还有什么人。远远看那就是你的家，松柏丛中坟冢一个挨一个。', appreciation: '这首乐府诗写老兵返乡所见家破人亡的惨景，控诉了战争和兵役的罪恶。', category: '边塞' },
    { title: '迢迢牵牛星', author: '佚名', dynasty: '汉', content: '迢迢牵牛星，皎皎河汉女。纤纤擢素手，札札弄机杼。终日不成章，泣涕零如雨。', translation: '遥远的牵牛星，皎洁的织女星。织女伸出纤纤白手，札札地操纵织机。整天织不成布匹，泪如雨下。', appreciation: '诗中以牛郎织女的传说写离愁，表现相思之苦含蓄深情。', category: '爱情' },
    { title: '涉江采芙蓉', author: '佚名', dynasty: '汉', content: '涉江采芙蓉，兰泽多芳草。采之欲遗谁？所思在远道。', translation: '渡过江去采荷花，兰草丛生芳草众多。采了想送给谁？思念的人在远方。', appreciation: '诗中写采花赠远表现思念远方之人的情怀，平淡中见深情。', category: '思乡' },
    { title: '登幽州台歌', author: '陈子昂', dynasty: '唐', content: '前不见古人，后不见来者。念天地之悠悠，独怆然而涕下。', translation: '向前看不见古代的贤君，向后看不见未来的明主。想到天地辽阔漫长无际，独自悲伤地流下眼泪。', appreciation: '诗人登台远望，感慨天地悠悠知己难逢，抒发了怀才不遇的悲凉。', category: '抒怀' },
    { title: '回乡偶书（其二）', author: '贺知章', dynasty: '唐', content: '离别家乡岁月多，近来人事半消磨。惟有门前镜湖水，春风不改旧时波。', translation: '离开家乡已经很多年了，近来人和事大多都已变迁消逝。只有门前镜湖的水，春风吹起的波纹还和旧时一样。', appreciation: '诗人写回乡后物是人非的感慨，以不变的水波反衬人事的变迁。', category: '思乡' },
    { title: '宿建德江', author: '孟浩然', dynasty: '唐', content: '移舟泊烟渚，日暮客愁新。野旷天低树，江清月近人。', translation: '把船停泊在烟雾笼罩的小洲旁，日落时分旅客又添了新的愁绪。原野空旷远处天空低垂到树梢，江水清澈月亮仿佛离人很近。', appreciation: '诗人写暮泊江上的孤寂，以江清月近一句衬托旅人的乡愁。', category: '思乡' },
    { title: '过故人庄', author: '孟浩然', dynasty: '唐', content: '故人具鸡黍，邀我至田家。绿树村边合，青山郭外斜。开轩面场圃，把酒话桑麻。待到重阳日，还来就菊花。', translation: '老朋友准备了鸡肉和米饭，邀请我到田家做客。绿树在村边环绕，青山在城外斜卧。打开窗户面对场院和菜园，端着酒杯谈论桑麻农事。等到重阳节那天，我还要来赏菊花。', appreciation: '诗人写田家作客的淳朴生活和深厚友情，意境恬淡自然。', category: '田园' },
    { title: '从军行（其四）', author: '王昌龄', dynasty: '唐', content: '青海长云暗雪山，孤城遥望玉门关。黄沙百战穿金甲，不破楼兰终不还。', translation: '青海上空长云密布遮暗了雪山，孤城遥望玉门关。黄沙中经历百战磨穿了金甲，不打败楼兰誓不回还。', appreciation: '诗人写边塞将士戍守的艰苦和誓死卫国的豪情，慷慨悲壮。', category: '边塞' },
    { title: '采莲曲', author: '王昌龄', dynasty: '唐', content: '荷叶罗裙一色裁，芙蓉向脸两边开。乱入池中看不见，闻歌始觉有人来。', translation: '荷叶和罗裙像用同一种颜色裁出，荷花和姑娘的脸庞在两边一齐盛开。混入池中分不清哪是荷叶哪是人，听到歌声才发觉有人走来。', appreciation: '诗人写采莲女与荷花融为一体的美景，构思巧妙色彩鲜明。', category: '田园' },
    { title: '相思', author: '王维', dynasty: '唐', content: '红豆生南国，春来发几枝。愿君多采撷，此物最相思。', translation: '红豆生长在南国，春天来了发了几枝。希望你多采摘一些，这东西最能表达相思之情。', appreciation: '诗人借红豆寄托相思，语言朴素而情意深长。', category: '抒怀' },
    { title: '杂诗', author: '王维', dynasty: '唐', content: '君自故乡来，应知故乡事。来日绮窗前，寒梅著花未？', translation: '你从故乡来，应该知道故乡的事情。来的时候那雕花窗前，寒梅开花了没有？', appreciation: '诗人借问梅花写思乡之情，把乡愁寄托在一枝梅花上，含蓄深情。', category: '思乡' },
    { title: '鸟鸣涧', author: '王维', dynasty: '唐', content: '人闲桂花落，夜静春山空。月出惊山鸟，时鸣春涧中。', translation: '人闲适地看桂花飘落，夜里寂静春山显得空旷。月亮升起惊动了山鸟，时时在春涧中鸣叫。', appreciation: '诗人以动衬静，写春山月夜的幽静，意境空灵。', category: '写景' },
    { title: '山居秋暝', author: '王维', dynasty: '唐', content: '空山新雨后，天气晚来秋。明月松间照，清泉石上流。竹喧归浣女，莲动下渔舟。随意春芳歇，王孙自可留。', translation: '空旷的山里刚下过一场雨，傍晚的天气透着秋凉。明月照在松林间，清泉在石上流淌。竹林喧闹是洗衣女子归来，莲叶摇动是渔船顺流而下。任凭春花凋谢，这里仍值得王孙留下。', appreciation: '诗人写秋雨后山中的清新幽静，表现了归隐山林的怡然之趣。', category: '田园' },
    { title: '竹里馆', author: '王维', dynasty: '唐', content: '独坐幽篁里，弹琴复长啸。深林人不知，明月来相照。', translation: '独自坐在幽深的竹林里，弹琴又放声长啸。深林中无人知晓，只有明月来相照。', appreciation: '诗人写竹林独坐的隐逸生活，表现了超然物外的高洁情怀。', category: '抒怀' },
    { title: '山中送别', author: '王维', dynasty: '唐', content: '山中相送罢，日暮掩柴扉。春草明年绿，王孙归不归？', translation: '在山中送别你之后，傍晚我关上了柴门。明年春草再绿的时候，你回来不回来呢？', appreciation: '诗人写送别后的思念，以春草再绿衬托盼归之情，含蓄隽永。', category: '送别' },
    { title: '秋浦歌', author: '李白', dynasty: '唐', content: '白发三千丈，缘愁似个长。不知明镜里，何处得秋霜。', translation: '白发有三千丈那么长，因为愁绪也像这样长。不知明镜里，从哪里得来这秋霜般的白发。', appreciation: '诗人以夸张手法写愁，把无形的愁绪化作有形的长发，奇特而真切。', category: '抒怀' },
    { title: '峨眉山月歌', author: '李白', dynasty: '唐', content: '峨眉山月半轮秋，影入平羌江水流。夜发清溪向三峡，思君不见下渝州。', translation: '峨眉山上挂着半轮秋月，月影倒映在平羌江水中随流而去。夜里从清溪出发驶向三峡，思念你却看不见，船已下到渝州。', appreciation: '诗人写江行所见月色，把思友之情融入江行途中，清丽流畅。', category: '思乡' },
    { title: '送友人', author: '李白', dynasty: '唐', content: '青山横北郭，白水绕东城。此地一为别，孤蓬万里征。浮云游子意，落日故人情。挥手自兹去，萧萧班马鸣。', translation: '青山横卧在城北，白水环绕着东城。在这里一分别，你就像孤蓬万里飘零。浮云飘忽像游子的心意，落日缓缓像故人的深情。挥手从此离去，离群的马也萧萧地鸣叫。', appreciation: '诗人以浮云落日比喻游子故人，把送别之情写得深沉蕴藉。', category: '送别' },
    { title: '客中行', author: '李白', dynasty: '唐', content: '兰陵美酒郁金香，玉碗盛来琥珀光。但使主人能醉客，不知何处是他乡。', translation: '兰陵的美酒散发着郁金的香气，玉碗盛来闪着琥珀般的光泽。只要主人能让客人醉倒，便不知哪里是异乡了。', appreciation: '诗人以美酒写客中之乐，反衬出深藏的思乡之情。', category: '思乡' },
    { title: '山中问答', author: '李白', dynasty: '唐', content: '问余何意栖碧山，笑而不答心自闲。桃花流水窅然去，别有天地非人间。', translation: '问我为什么隐居在碧山，我笑而不答心中自得悠闲。桃花随流水远远流去，这里别有一番天地不是人间。', appreciation: '诗人以笑而不答写隐居之趣，表现了超脱尘俗的闲适心境。', category: '抒怀' },
    { title: '春思', author: '李白', dynasty: '唐', content: '燕草如碧丝，秦桑低绿枝。当君怀归日，是妾断肠时。春风不相识，何事入罗帏。', translation: '燕地的草像碧绿的丝线，秦地的桑树垂下绿枝。当你想到回来的时候，正是我思念断肠的时候。春风和我并不相识，为何要吹进我的罗帐。', appreciation: '诗人以思妇口吻写相思之情，借春景衬托思念之苦。', category: '爱情' },
    { title: '黄鹤楼', author: '崔颢', dynasty: '唐', content: '昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠。晴川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。', translation: '从前的人已经乘着黄鹤飞走了，这里只留下空空的黄鹤楼。黄鹤一去不再返回，白云千载空自悠悠飘荡。晴朗江边清楚地映着汉阳的树木，芳草茂盛长满鹦鹉洲。日暮时分故乡在哪里？江上烟波迷茫使人发愁。', appreciation: '诗人写登黄鹤楼所见所感，由景入情抒发深沉的乡愁，被誉为唐人七律第一。', category: '思乡' },
    { title: '逢入京使', author: '岑参', dynasty: '唐', content: '故园东望路漫漫，双袖龙钟泪不干。马上相逢无纸笔，凭君传语报平安。', translation: '向东望着故乡道路漫漫，两袖沾满泪水怎么也擦不干。在马上相逢没有纸笔，就托你传个话报声平安。', appreciation: '诗人写思乡之情，以传语报平安一个细节写出真挚的乡情。', category: '思乡' },
    { title: '闻官军收河南河北', author: '杜甫', dynasty: '唐', content: '剑外忽传收蓟北，初闻涕泪满衣裳。却看妻子愁何在，漫卷诗书喜欲狂。白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。', translation: '剑外忽然传来收复蓟北的消息，刚听到时泪水沾满了衣裳。回头看妻子哪里还有愁容，胡乱卷起诗书欢喜得要发狂。白天要放声高歌开怀畅饮，趁着大好春光结伴还乡。即刻从巴峡穿过巫峡，顺流下到襄阳奔向洛阳。', appreciation: '诗人听到收复失地的消息欣喜若狂，被称为生平第一快诗。', category: '爱国' },
    { title: '江南逢李龟年', author: '杜甫', dynasty: '唐', content: '岐王宅里寻常见，崔九堂前几度闻。正是江南好风景，落花时节又逢君。', translation: '在岐王府里常能见到你，在崔九堂前也几次听你唱歌。如今正是江南风景最美的时候，落花时节又与你相逢。', appreciation: '诗人借与故人重逢，抒发世事沧桑今昔之感的深沉慨叹。', category: '抒怀' },
    { title: '绝句·迟日江山', author: '杜甫', dynasty: '唐', content: '迟日江山丽，春风花草香。泥融飞燕子，沙暖睡鸳鸯。', translation: '春天的太阳映得江山秀丽，春风吹来花草芳香。泥土融软燕子飞来飞去，沙地暖和鸳鸯睡在上面。', appreciation: '诗人写春日明丽的景物，动静结合，充满春的生机和温暖。', category: '春景' },
    { title: '赠花卿', author: '杜甫', dynasty: '唐', content: '锦城丝管日纷纷，半入江风半入云。此曲只应天上有，人间能得几回闻。', translation: '锦城里管弦之声整日纷纷飘扬，一半随江风一半入云霄。这样的曲子只应天上才有，人间能听到几回呢。', appreciation: '诗人赞美乐曲之美，又含蓄地讽劝花卿不要僭越礼制。', category: '抒怀' },
    { title: '登高', author: '杜甫', dynasty: '唐', content: '风急天高猿啸哀，渚清沙白鸟飞回。无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。', translation: '风急天高猿猴的叫声悲哀，水清沙白鸟儿在盘旋。无边无际的落叶萧萧而下，奔流不尽的长江滚滚而来。万里漂泊悲秋常做客，一生多病独自登台。艰难愁苦让双鬓如霜，潦倒之中又停了这杯浊酒。', appreciation: '诗人写秋景苍茫，抒发身世飘零老病孤愁的深沉悲哀，格律精严。', category: '秋景' },
    { title: '登岳阳楼', author: '杜甫', dynasty: '唐', content: '昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。', translation: '从前听说洞庭湖的盛名，今天登上了岳阳楼。吴楚两地向东南裂开，天地日月都在湖中浮动。亲戚朋友没有一点音信，年老多病只有一只孤舟。北方还有战事，靠窗远望不禁泪流满面。', appreciation: '诗人写洞庭湖的壮阔，又抒发身世之悲和忧国之情，沉郁顿挫。', category: '抒怀' },
    { title: '月夜忆舍弟', author: '杜甫', dynasty: '唐', content: '戍鼓断人行，边秋一雁声。露从今夜白，月是故乡明。有弟皆分散，无家问死生。', translation: '戍楼鼓声响起断绝了行人，边塞秋夜传来一声雁鸣。露水从今夜起变白，月亮还是故乡的最明亮。有弟弟却都分散各地，没有家可以打听生死。', appreciation: '诗人写战乱中思念分散的兄弟，月是故乡明一句道尽思乡之情。', category: '思乡' },
    { title: '前出塞', author: '杜甫', dynasty: '唐', content: '挽弓当挽强，用箭当用长。射人先射马，擒贼先擒王。杀人亦有限，列国自有疆。苟能制侵陵，岂在多杀伤。', translation: '拉弓要拉强弓，用箭要用长箭。射人要先射马，擒贼要先擒王。杀人也有限度，各国自有疆界。只要能制止侵略，哪在于多杀人呢。', appreciation: '诗中以射人擒贼写用兵之道，蕴含以战止战的深刻哲理。', category: '边塞' },
    { title: '八阵图', author: '杜甫', dynasty: '唐', content: '功盖三分国，名成八阵图。江流石不转，遗恨失吞吴。', translation: '功业盖过三分天下的三国，名声成就于八阵图。江水奔流石头不转，留下没能吞灭东吴的遗憾。', appreciation: '诗人借八阵图赞诸葛亮功业，又惋惜他未能完成统一大业。', category: '咏史' },
    { title: '逢雪宿芙蓉山主人', author: '刘长卿', dynasty: '唐', content: '日暮苍山远，天寒白屋贫。柴门闻犬吠，风雪夜归人。', translation: '日暮时分苍山显得遥远，天气寒冷茅屋显得简陋。柴门外听到狗叫，是风雪之夜归家的人。', appreciation: '诗人写雪夜投宿的情景，寥寥几笔勾勒出风雪夜归的画面。', category: '写景' },
    { title: '送灵澈上人', author: '刘长卿', dynasty: '唐', content: '苍苍竹林寺，杳杳钟声晚。荷笠带斜阳，青山独归远。', translation: '青苍的竹林掩映着寺庙，远远传来傍晚的钟声。戴着斗笠披着夕阳，独自向青山深处归去。', appreciation: '诗人写送别僧人归山的情景，意境清幽淡远。', category: '送别' },
    { title: '滁州西涧', author: '韦应物', dynasty: '唐', content: '独怜幽草涧边生，上有黄鹂深树鸣。春潮带雨晚来急，野渡无人舟自横。', translation: '唯独喜爱涧边生长的幽草，树深处有黄鹂在鸣叫。春天的潮水带着傍晚的急雨，荒野渡口无人小船独自横着。', appreciation: '诗人写西涧春景的幽静荒凉，野渡舟横一句写尽闲适恬淡。', category: '写景' },
    { title: '塞下曲·林暗', author: '卢纶', dynasty: '唐', content: '林暗草惊风，将军夜引弓。平明寻白羽，没在石棱中。', translation: '树林昏暗草被风吹动像有猛虎，将军夜里拉弓射箭。天亮去寻找白羽箭，发现射进了石头棱角里。', appreciation: '诗人写将军夜射猛虎误中石的故事，表现将军的神勇。', category: '边塞' },
    { title: '登科后', author: '孟郊', dynasty: '唐', content: '昔日龌龊不足夸，今朝放荡思无涯。春风得意马蹄疾，一日看尽长安花。', translation: '从前的局促窘迫不值一提，今天的心情放荡无边。春风得意马跑得飞快，一天看遍了长安的花。', appreciation: '诗人写进士及第的狂喜，春风得意一句成为流传的成语。', category: '抒怀' },
    { title: '游子吟·续', author: '孟郊', dynasty: '唐', content: '萱草生堂阶，游子行天涯。慈亲倚堂门，不见萱草花。', translation: '萱草长在堂前的台阶上，游子远行走到天涯。慈爱的母亲倚在堂门前，看不见那萱草花。', appreciation: '诗人以萱草代母亲写游子远行母亲思念，含蓄深情。', category: '亲情' },
    { title: '春夜洛城闻笛', author: '李白', dynasty: '唐', content: '谁家玉笛暗飞声，散入春风满洛城。此夜曲中闻折柳，何人不起故园情。', translation: '谁家的玉笛在暗暗地飘送声音，散入春风中飘满了洛阳城。今夜笛曲中听到了折杨柳，哪个人不会涌起思乡之情呢？', appreciation: '诗人借笛声和折柳曲写思乡，把无形的声音化作有形的乡愁。', category: '思乡' },
    { title: '渡荆门送别', author: '李白', dynasty: '唐', content: '渡远荆门外，来从楚国游。山随平野尽，江入大荒流。月下飞天镜，云生结海楼。仍怜故乡水，万里送行舟。', translation: '乘船远行经过荆门山外，来到楚地游览。山势随着平原的出现而消失，长江流入广阔的原野。月亮倒映水中像飞来的明镜，云气聚结像海上的楼阁。仍然喜爱故乡的江水，不辞万里送着我的船。', appreciation: '诗人写离乡远游所见壮丽景色，结尾以故乡水送舟表达深切的思乡之情。', category: '送别' },
    { title: '赠孟浩然', author: '李白', dynasty: '唐', content: '吾爱孟夫子，风流天下闻。红颜弃轩冕，白首卧松云。醉月频中圣，迷花不事君。高山安可仰，徒此揖清芬。', translation: '我敬爱孟夫子，他风流洒脱天下闻名。年轻时便放弃官职，到老都隐居松云之间。月下饮酒常常醉倒，迷恋花草不愿侍奉君王。如高山般怎能仰望，只能在此揖拜他的清芬。', appreciation: '诗人赞美孟浩然的高洁品格和隐逸情怀，表达敬仰之情。', category: '送别' },
    { title: '送友人入蜀', author: '李白', dynasty: '唐', content: '见说蚕丛路，崎岖不易行。山从人面起，云傍马头生。芳树笼秦栈，春流绕蜀城。升沉应已定，不必问君平。', translation: '听说蜀道崎岖难行。山岩仿佛从人面前突起，云气挨着马头生成。芳树笼罩着秦地的栈道，春水环绕着蜀地的城池。仕途的升降早有定数，不必再去问卜的君平。', appreciation: '诗中写蜀道崎岖，又含蓄地劝慰友人不必在意仕途得失。', category: '送别' },
    { title: '宣州谢朓楼饯别校书叔云', author: '李白', dynasty: '唐', content: '弃我去者，昨日之日不可留；乱我心者，今日之日多烦忧。长风万里送秋雁，对此可以酣高楼。蓬莱文章建安骨，中间小谢又清发。俱怀逸兴壮思飞，欲上青天揽明月。抽刀断水水更流，举杯消愁愁更愁。人生在世不称意，明朝散发弄扁舟。', translation: '弃我而去的昨天留不住了，扰乱我心绪的今天烦忧太多。万里长风送着秋雁，面对此景可以登高楼畅饮。您的文章有建安风骨，又有谢朓的清丽。我们都怀着豪情壮志要飞上天去拥抱明月。抽刀断水水更流，举杯消愁愁更愁。人生在世不如意，明朝不如披散头发驾着小舟归隐。', appreciation: '诗人借饯别抒发怀才不遇的苦闷，豪迈中透出深沉的感慨。', category: '抒怀' },
    { title: '行路难·其二', author: '李白', dynasty: '唐', content: '大道如青天，我独不得出。羞逐长安社中儿，赤鸡白雉赌梨栗。弹剑作歌奏苦声，曳裾王门不称情。淮阴市井笑韩信，汉朝公卿忌贾生。', translation: '大道像青天一样宽广，我却唯独走不出去。羞于追逐长安里巷的少年，斗鸡走狗赌梨栗。弹剑作歌唱出苦声，在王侯门下拖长衣襟也不如意。韩信在淮阴市井被人嘲笑，贾谊被汉朝公卿嫉妒。', appreciation: '诗人写自己仕途受挫的愤懑，借古人的遭遇抒发怀才不遇的痛苦。', category: '抒怀' },
    { title: '行路难·其三', author: '李白', dynasty: '唐', content: '有耳莫洗颍川水，有口莫食首阳蕨。含光混世贵无名，何用孤高比云月？吾观自古贤达人，功成不退皆殒身。子胥既弃吴江上，屈原终投湘水滨。', translation: '有耳朵不要去洗颍川水，有嘴巴不要吃首阳蕨。含光混世最可贵的是不求名，何必孤高自比云月？我看自古以来的贤人，功成不退都丢了性命。伍子胥被抛弃在吴江上，屈原最终投水在湘江边。', appreciation: '诗人借古人之事表达功成身退的思想，含蓄地写出世态的险恶。', category: '抒怀' },
    { title: '将进酒', author: '李白', dynasty: '唐', content: '君不见黄河之水天上来，奔流到海不复回。君不见高堂明镜悲白发，朝如青丝暮成雪。人生得意须尽欢，莫使金樽空对月。天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。岑夫子，丹丘生，将进酒，杯莫停。与君歌一曲，请君为我倾耳听。钟鼓馔玉不足贵，但愿长醉不复醒。古来圣贤皆寂寞，惟有饮者留其名。陈王昔时宴平乐，斗酒十千恣欢谑。主人何为言少钱，径须沽取对君酌。五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。', translation: '你没看见黄河水从天上来，奔流到海不再回头。你没看见高堂明镜悲叹白发，早晨还像黑丝傍晚就成雪。人生得意时要尽情欢乐，不要让金杯空对着明月。老天赐我才华必有用处，千金散尽还会再来。烹羊宰牛尽情享乐，一次要喝三百杯。岑夫子，丹丘生，请喝酒，杯莫停。我为你们唱一首歌，请你们倾耳细听。钟鼓美食不值一提，只愿长醉不再醒。自古以来圣贤都寂寞，只有饮酒的人留下名声。陈王曹植当年在平乐观设宴，一斗酒值十千钱尽情欢乐。主人怎么说钱少，只管去买酒来对饮。五花马千金裘，叫童子拿去换美酒，和你们一起消除万古的忧愁。', appreciation: '诗人借饮酒抒发怀才不遇的愤懑，又以天生我材必有用表达豪迈自信。', category: '抒怀' },
    { title: '蜀道难', author: '李白', dynasty: '唐', content: '噫吁嚱，危乎高哉！蜀道之难，难于上青天！蚕丛及鱼凫，开国何茫然！尔来四万八千岁，不与秦塞通人烟。西当太白有鸟道，可以横绝峨眉巅。地崩山摧壮士死，然后天梯石栈相钩连。', translation: '唉呀，多么高多么险啊！蜀道的难走，比登天还难！蚕丛和鱼凫建国时多么遥远！那以后四万八千年，也不和秦地相通人烟。西面太白山只有鸟飞的路，可以横越峨眉山顶。山崩地裂壮士牺牲，然后才有天梯石栈相连。', appreciation: '诗人以夸张的笔法写蜀道的高险，气象雄奇，是浪漫主义的杰作。', category: '写景' },
    { title: '梦游天姥吟留别', author: '李白', dynasty: '唐', content: '海客谈瀛洲，烟涛微茫信难求。越人语天姥，云霞明灭或可睹。天姥连天向天横，势拔五岳掩赤城。天台四万八千丈，对此欲倒东南倾。我欲因之梦吴越，一夜飞度镜湖月。湖月照我影，送我至剡溪。', translation: '航海的人谈起瀛洲，烟雾波涛迷茫实在难寻。越地的人说起天姥山，云霞明灭或许能看见。天姥山连着天横在天边，气势超过五岳压倒赤城山。天台山有四万八千丈高，对着天姥山也要向东南倾倒。我因此梦游吴越，一夜之间飞过月光下的镜湖。湖月照着我的影子，送我到了剡溪。', appreciation: '诗人借梦游写奇景，结尾安能摧眉折腰事权贵表达傲岸不屈的精神。', category: '抒怀' },
    { title: '庐山谣寄卢侍御虚舟', author: '李白', dynasty: '唐', content: '我本楚狂人，凤歌笑孔丘。手持绿玉杖，朝别黄鹤楼。五岳寻仙不辞远，一生好入名山游。庐山秀出南斗傍，屏风九叠云锦张。', translation: '我本是楚地的狂人，唱着凤歌笑孔丘。手里拿着绿玉杖，清晨告别黄鹤楼。为寻仙不辞路远，一生喜欢游历名山。庐山秀美地耸立在南斗星旁，九叠屏风像张开的云锦。', appreciation: '诗人写庐山胜景，抒发寄情山水蔑视权贵的情怀。', category: '写景' },
    { title: '越中览古', author: '李白', dynasty: '唐', content: '越王勾践破吴归，义士还乡尽锦衣。宫女如花满春殿，只今惟有鹧鸪飞。', translation: '越王勾践灭吴归来，将士们回家都穿上了锦衣。宫女如花般站满春殿，如今只有鹧鸪在废墟上飞舞。', appreciation: '诗人借越王宫殿的今昔对比，抒发盛衰无常的感慨。', category: '咏史' },
    { title: '苏台览古', author: '李白', dynasty: '唐', content: '旧苑荒台杨柳新，菱歌清唱不胜春。只今惟有西江月，曾照吴王宫里人。', translation: '旧日的园林荒废的楼台旁杨柳新发，采菱女清脆的歌声唱不尽春意。如今只有西江上的明月，曾经照过吴王宫里的人。', appreciation: '诗人借苏台荒凉反衬昔日繁华，抒发历史兴亡的感慨。', category: '咏史' },
    { title: '秋登宣城谢朓北楼', author: '李白', dynasty: '唐', content: '江城如画里，山晚望晴空。两水夹明镜，双桥落彩虹。人烟寒橘柚，秋色老梧桐。谁念北楼上，临风怀谢公。', translation: '江城像在画里一样，傍晚山中眺望晴空。两条江水夹着一面明镜，两座桥像落下的彩虹。人家的炊烟让橘柚显得清寒，秋色让梧桐更显苍老。谁会想到北楼上，有人迎风怀念谢公。', appreciation: '诗人写秋日登楼所见的明丽景色，又抒发对谢朓的怀念。', category: '秋景' },
    { title: '登金陵凤凰台', author: '李白', dynasty: '唐', content: '凤凰台上凤凰游，凤去台空江自流。吴宫花草埋幽径，晋代衣冠成古丘。三山半落青天外，二水中分白鹭洲。总为浮云能蔽日，长安不见使人愁。', translation: '凤凰台上曾有凤凰游翔，凤凰飞去台空只有江水自流。吴宫的花草埋没在幽径下，晋代的衣冠人物都成了古坟。三山有一半落在青天外，二水把白鹭洲一分为二。总是浮云能遮蔽太阳，看不见长安使人发愁。', appreciation: '诗人借登台怀古抒发对朝政的忧虑和怀才不遇的愁苦。', category: '咏史' },
    { title: '听蜀僧濬弹琴', author: '李白', dynasty: '唐', content: '蜀僧抱绿绮，西下峨眉峰。为我一挥手，如听万壑松。客心洗流水，余响入霜钟。不觉碧山暮，秋云暗几重。', translation: '蜀僧抱着绿绮琴，从峨眉山西面下来。为我挥手弹奏一曲，好像听到万壑松涛声。琴声像流水洗去客中愁绪，余音和傍晚的钟声相和。不知不觉碧山已暮，秋云暗了几重。', appreciation: '诗人写听琴的美妙感受，以万壑松风喻琴声，意境清幽。', category: '抒怀' },
    { title: '金陵酒肆留别', author: '李白', dynasty: '唐', content: '风吹柳花满店香，吴姬压酒唤客尝。金陵子弟来相送，欲行不行各尽觞。请君试问东流水，别意与之谁短长。', translation: '风吹着柳絮满店飘香，吴地女子压酒劝客人品尝。金陵的年轻朋友来送别，要走的不走的各自尽杯。请你问问东流的江水，离别的情意和江水哪个更长。', appreciation: '诗人以江水喻别情，写出与金陵友人的深厚情谊。', category: '送别' },
    { title: '山中与幽人对酌', author: '李白', dynasty: '唐', content: '两人对酌山花开，一杯一杯复一杯。我醉欲眠卿且去，明朝有意抱琴来。', translation: '两人在山中对着山花饮酒，一杯一杯又一杯。我醉了想睡你先走吧，明天如果有兴致就抱着琴来。', appreciation: '诗人写山中饮酒的率真洒脱，表现出随性自然的情趣。', category: '抒怀' },
    { title: '哭晁卿衡', author: '李白', dynasty: '唐', content: '日本晁卿辞帝都，征帆一片绕蓬壶。明月不归沉碧海，白云愁色满苍梧。', translation: '日本友人晁卿辞别京城，一片船帆绕行蓬莱仙山。像明月不归沉入碧海，白云带着愁色笼罩苍梧山。', appreciation: '诗人悼念日本友人的遇难，把友人比作明月，哀婉深情。', category: '送别' },
    { title: '望木瓜山', author: '李白', dynasty: '唐', content: '早起见日出，暮见栖鸟还。客心自酸楚，况对木瓜山。', translation: '早晨起来看见日出，傍晚看见归巢的鸟儿。客居的心中本就酸楚，何况面对着木瓜山。', appreciation: '诗人写客居思乡之愁，借木瓜谐音木瓜山抒发愁绪。', category: '思乡' },
    { title: '独漉篇', author: '李白', dynasty: '唐', content: '独漉水中泥，水浊不见月。不见月尚可，水深行人没。', translation: '在独漉水中搅动泥沙，水浑浊看不见月亮。看不见月亮还可以，水深行人会被淹没。', appreciation: '诗人以水中不见月喻世事浑浊，含蓄地写出了世道的险恶。', category: '抒怀' },
    { title: '紫骝马', author: '李白', dynasty: '唐', content: '紫骝行且嘶，双翻碧玉蹄。临流不肯渡，似惜锦障泥。', translation: '紫骝马边走边嘶鸣，两蹄翻飞像碧玉。临到河边不肯渡水，好像舍不得锦缎做的障泥。', appreciation: '诗人写紫骝马的俊美和灵性，细致传神。', category: '咏物' },
    { title: '玉阶怨', author: '李白', dynasty: '唐', content: '玉阶生白露，夜久侵罗袜。却下水晶帘，玲珑望秋月。', translation: '玉阶上生了白露，夜深了露水浸湿了罗袜。退下水晶帘，望着玲珑的秋月。', appreciation: '诗人写宫女的幽怨，以望月反衬孤独，含蓄不尽。', category: '秋景' },
    { title: '劳劳亭', author: '李白', dynasty: '唐', content: '天下伤心处，劳劳送客亭。春风知别苦，不遣柳条青。', translation: '天下最伤心的地方，就是这送客的劳劳亭。春风知道离别的痛苦，不让柳条发青。', appreciation: '诗人借春风不青柳条写离别的痛苦，构思新奇。', category: '送别' },
    { title: '渌水曲', author: '李白', dynasty: '唐', content: '渌水明秋月，南湖采白蘋。荷花娇欲语，愁杀荡舟人。', translation: '清澈的湖水映着秋月，在南湖采摘白蘋。荷花娇艳得好像要说话，愁坏了荡舟采莲的人。', appreciation: '诗人写采莲女的情景，以荷花娇语衬托人的情思。', category: '秋景' },
    { title: '秋浦歌·其二', author: '李白', dynasty: '唐', content: '秋浦锦驼鸟，人间天上稀。山鸡羞渌水，不敢照毛衣。', translation: '秋浦有锦驼鸟，人间天上都稀少。山鸡羞于面对清澈的水，不敢照自己的羽毛。', appreciation: '诗人以山鸡衬托锦驼鸟的美丽，用侧面描写手法。', category: '咏物' },
    { title: '襄阳歌', author: '李白', dynasty: '唐', content: '落日欲没岘山西，倒著接蓠花下迷。襄阳小儿齐拍手，拦街争唱白铜鞮。', translation: '夕阳将要落山落在岘山西边，倒戴着头巾在花下迷醉。襄阳的小孩齐声拍手，拦着街争唱白铜鞮。', appreciation: '诗人写自己醉后的狂态，表现出洒脱不羁的名士风度。', category: '抒怀' },
    { title: '子夜吴歌·秋歌', author: '李白', dynasty: '唐', content: '长安一片月，万户捣衣声。秋风吹不尽，总是玉关情。何日平胡虏，良人罢远征。', translation: '长安城一片月光，千家万户传来捣衣声。秋风吹不尽的，都是对玉门关外征人的思念。什么时候能平定胡虏，丈夫就不用远征了。', appreciation: '诗人借捣衣声写思妇对征夫的思念，含蓄地表达反对战争之意。', category: '思乡' },
    { title: '子夜吴歌·夏歌', author: '李白', dynasty: '唐', content: '镜湖三百里，菡萏发荷花。五月西施采，人看隘若耶。', translation: '镜湖方圆三百里，荷花盛开。五月西施来采莲，看的人挤满了若耶溪。', appreciation: '诗人写西施采莲的盛况，侧面烘托西施的美貌。', category: '夏景' },
    { title: '春思·其二', author: '李白', dynasty: '唐', content: '燕麦青青不可掐，游子何时到帝家。', translation: '燕地的麦苗青青不能掐断，游子什么时候能到京城呢。', appreciation: '诗人以麦苗青青写思妇盼归，朴素而深情。', category: '思乡' },
    { title: '古风·其三', author: '李白', dynasty: '唐', content: '秦王扫六合，虎视何雄哉！挥剑决浮云，诸侯尽西来。', translation: '秦王扫平六合统一天下，虎视天下多么威武！挥剑斩断浮云，诸侯全都西来臣服。', appreciation: '诗人写秦始皇统一天下的雄才大略，气势磅礴。', category: '咏史' },
    { title: '战城南', author: '李白', dynasty: '唐', content: '去年战桑干源，今年战葱河道。洗兵条支海上波，放马天山雪中草。', translation: '去年在桑干源作战，今年在葱河道作战。在条支海上洗兵器，在天山雪中放马吃草。', appreciation: '诗人写战争的频繁和将士的辛苦，含蓄地表达反战之意。', category: '边塞' },
    { title: '关山月', author: '李白', dynasty: '唐', content: '明月出天山，苍茫云海间。长风几万里，吹度玉门关。汉下白登道，胡窥青海湾。由来征战地，不见有人还。戍客望边邑，思归多苦颜。高楼当此夜，叹息未应闲。', translation: '明月从天山升起，在苍茫的云海之间。长风吹过几万里，吹过玉门关。汉兵下白登道，胡人窥视青海湾。这些征战的地方，从来不见有人生还。戍守的士兵望着边邑，思念归乡愁容满面。高楼上的妻子今夜，叹息声应该不曾停歇。', appreciation: '诗人写边塞将士的思乡之情，意境开阔苍凉。', category: '边塞' },
    { title: '长干行', author: '李白', dynasty: '唐', content: '妾发初覆额，折花门前剧。郎骑竹马来，绕床弄青梅。同居长干里，两小无嫌猜。十四为君妇，羞颜未尝开。', translation: '我刚留齐额短发时，折了花在门前嬉戏。你骑着竹马而来，绕着井栏弄青梅。我们同住长干里，两个小孩天真无猜。十四岁做了你的妻子，害羞得不敢露出笑脸。', appreciation: '诗人以女子口吻写爱情故事，青梅竹马一词流传千古。', category: '爱情' },
    { title: '玉阶怨·续', author: '李白', dynasty: '唐', content: '美人在时花满堂，美人去后花馀床。床中绣被卷不寝，至今三载犹闻香。', translation: '美人在时满堂花开，美人走后只剩花和床。床上绣被卷起无心睡眠，至今三年还能闻到她的香气。', appreciation: '诗人写思念美人之情，以花香反衬人去后的怅惘。', category: '爱情' },
    { title: '子夜吴歌·春歌', author: '李白', dynasty: '唐', content: '秦地罗敷女，采桑绿水边。素手青条上，红妆白日鲜。蚕饥妾欲去，五马莫留连。', translation: '秦地的罗敷女，在绿水边采桑。洁白的手在青枝上，红妆在阳光下鲜艳。蚕饿了我要回去，五马太守不要留连。', appreciation: '诗人写罗敷女的美貌和机智，赞美她的坚贞品格。', category: '春景' },
    { title: '蜀道后期', author: '张说', dynasty: '唐', content: '客心争日月，来往预期程。秋风不相待，先至洛阳城。', translation: '客居的心和时间赛跑，来往都预定好行程。秋风却不等我，先到了洛阳城。', appreciation: '诗人借秋风先到写归期延误的无奈，构思巧妙。', category: '思乡' },
    { title: '送梁六自洞庭山', author: '张说', dynasty: '唐', content: '巴陵一望洞庭秋，日见孤峰水上浮。闻道神仙不可接，孤舟一去复何求。', translation: '在巴陵一望洞庭湖秋色，每天看见孤峰浮在水上。听说神仙不可接近，孤舟一去还求什么呢。', appreciation: '诗人写送别时的孤寂之情，意境深远。', category: '送别' },
    { title: '汾上惊秋', author: '苏颋', dynasty: '唐', content: '北风吹白云，万里渡河汾。心绪逢摇落，秋声不可闻。', translation: '北风吹着白云，万里渡过黄河汾水。心绪本就烦闷又逢草木凋零，秋声更不忍去听。', appreciation: '诗人写北渡汾水时的秋思，借秋风落叶写羁旅愁情。', category: '秋景' },
    { title: '侍宴长宁公主东庄', author: '李峤', dynasty: '唐', content: '别业临青甸，鸣銮降紫霄。长筵鹓鹭集，仙管凤凰调。树接南山近，烟含北渚遥。承恩咸已醉，恋赏未还镳。', translation: '公主的别业临近青翠的郊野，皇帝的车驾从天而降。长长的筵席上鹓鹭群集，仙乐奏出凤凰的曲调。树木连接南山很近，烟雾笼罩北渚遥远。受恩的人都已醉了，留恋赏玩不愿回车。', appreciation: '诗人写公主别业的华贵和宴饮的盛况，辞藻华丽。', category: '抒怀' },
    { title: '风', author: '李峤', dynasty: '唐', content: '解落三秋叶，能开二月花。过江千尺浪，入竹万竿斜。', translation: '能吹落秋天的树叶，能吹开二月的鲜花。吹过江面卷起千尺浪，吹入竹林让万竿竹倾斜。', appreciation: '诗人通篇写风却不出现风字，巧妙地写出风的威力。', category: '咏物' },
    { title: '中秋月', author: '李峤', dynasty: '唐', content: '圆魄上寒空，皆言四海同。安知千里外，不有雨兼风。', translation: '圆月升上寒冷的天空，都说四海一样月色。怎么知道千里之外，没有风雨呢。', appreciation: '诗人借中秋月写哲理，说明事物的复杂性和差异性。', category: '哲理' },
    { title: '咏风', author: '王勃', dynasty: '唐', content: '肃肃凉风生，加我林壑清。驱烟寻涧户，卷雾出山楹。', translation: '飒飒的凉风吹起，给我林间山谷带来清凉。它驱散烟雾寻到溪涧人家，卷开雾气露出山间的房屋。', appreciation: '诗人以拟人手法写凉风，赋予风以人的情态，清新自然。', category: '咏物' },
    { title: '山中', author: '王勃', dynasty: '唐', content: '长江悲已滞，万里念将归。况属高风晚，山山黄叶飞。', translation: '长江水让我悲叹停滞不前，身在万里思念归乡。况且正值秋高风急的傍晚，群山间黄叶纷飞。', appreciation: '诗人写客居思乡之情，以黄叶飞烘托羁旅的愁苦。', category: '思乡' },
    { title: '从军行', author: '杨炯', dynasty: '唐', content: '烽火照西京，心中自不平。牙璋辞凤阙，铁骑绕龙城。雪暗凋旗画，风多杂鼓声。宁为百夫长，胜作一书生。', translation: '烽火照亮了西京，心中自然不能平静。手持牙璋辞别皇宫，铁骑包围龙城。大雪使旗上的图画黯淡，风中夹杂着鼓声。宁做百夫长，胜过做一介书生。', appreciation: '诗人写从军报国的豪情，结尾表达投笔从戎的壮志。', category: '边塞' },
    { title: '咏史', author: '卢照邻', dynasty: '唐', content: '昔有平陵男，姓赵名雍门。布衣谒天子，流落竟不遇。', translation: '从前有个平陵男子，姓赵名叫雍门。穿着布衣拜见天子，流落他乡最终不被赏识。', appreciation: '诗人借古人事迹抒发怀才不遇的感慨。', category: '咏史' },
    { title: '梅花落', author: '卢照邻', dynasty: '唐', content: '梅岭花初发，天山雪未开。雪处疑花满，花边似雪回。', translation: '梅岭的花刚刚开放，天山的雪还没消融。雪地里仿佛满是梅花，花边又像回到了雪中。', appreciation: '诗人以雪和花相互映衬，写出梅雪交融的美景。', category: '咏物' },
    { title: '长安古意', author: '卢照邻', dynasty: '唐', content: '长安大道连狭斜，青牛白马七香车。玉辇纵横过渭桥，金鞭络绎向秦家。', translation: '长安的大道连着小巷，青牛白马拉着七香车。玉辇横穿过渭桥，金鞭络绎奔向秦家。', appreciation: '诗人写长安的繁华景象，借古题写时事气象宏阔。', category: '咏史' },
    { title: '在狱咏蝉', author: '骆宾王', dynasty: '唐', content: '西陆蝉声唱，南冠客思深。不堪玄鬓影，来对白头吟。露重飞难进，风多响易沉。无人信高洁，谁为表予心。', translation: '秋天蝉声阵阵鸣唱，作为囚徒的我思乡更深。难以忍受蝉那黑色的双鬓，来对着我这白头人吟唱。露水深重蝉难以飞进，风多声音容易沉没。没有人相信它的高洁，谁能为我说出心意。', appreciation: '诗人借蝉的高洁自喻，抒发含冤入狱的悲愤和高洁的情怀。', category: '咏物' },
    { title: '于易水送人', author: '骆宾王', dynasty: '唐', content: '此地别燕丹，壮士发冲冠。昔时人已没，今日水犹寒。', translation: '就在这里荆轲辞别燕太子丹，壮士怒发冲冠。当年的英雄已经逝去，今日易水依然寒气逼人。', appreciation: '诗人借易水送别抒发对古代侠士的敬仰和怀才不遇的感慨。', category: '送别' },
    { title: '代悲白头翁', author: '刘希夷', dynasty: '唐', content: '洛阳城东桃李花，飞来飞去落谁家。洛阳女儿惜颜色，行逢陌上叹颜色。', translation: '洛阳城东的桃李花开，飞来飞去落在谁家。洛阳的女儿珍惜自己的容颜，走在路上感叹容颜易老。', appreciation: '诗人以桃李花起兴写年华易逝，表达了人生无常的感慨。', category: '抒怀' },
    { title: '春江花月夜', author: '张若虚', dynasty: '唐', content: '春江潮水连海平，海上明月共潮生。滟滟随波千万里，何处春江无月明。江流宛转绕芳甸，月照花林皆似霰。空里流霜不觉飞，汀上白沙看不见。江天一色无纤尘，皎皎空中孤月轮。江畔何人初见月？江月何年初照人？人生代代无穷已，江月年年望相似。不知江月待何人，但见长江送流水。', translation: '春天的江潮与海面齐平，海上的明月和潮水一同升起。月光随波荡漾千万里，哪处春江没有月色明亮。江水蜿蜒绕过芳香的草地，月光照在花林像撒了一层雪珠。空中飞霜不知不觉飘落，沙洲上的白沙看不见。江天一色没有一点尘埃，皎洁的空中挂着一轮孤月。江边什么人最先看到月亮？江月哪一年最初照到人？人生一代代没有穷尽，江月年年看起来都相似。不知江月在等什么人，只见长江送走流水。', appreciation: '诗人以春江月夜为背景写离愁别绪，又蕴含人生哲理，被誉为孤篇盖全唐。', category: '写景' },
    { title: '池上', author: '白居易', dynasty: '唐', content: '小娃撑小艇，偷采白莲回。不解藏踪迹，浮萍一道开。', translation: '小孩撑着小船，偷偷采了白莲回来。不懂得隐藏踪迹，浮萍被船划开一道口子。', appreciation: '诗人写小孩偷采莲蓬的天真，富有童趣，画面生动。', category: '田园' },
    { title: '问刘十九', author: '白居易', dynasty: '唐', content: '绿蚁新醅酒，红泥小火炉。晚来天欲雪，能饮一杯无？', translation: '新酿的酒泛着绿色泡沫，红泥小火炉烧得正旺。傍晚天快下雪了，能来喝一杯吗？', appreciation: '诗人写雪夜邀友小饮的温馨，语言朴实情谊真挚。', category: '友情' },
    { title: '暮江吟', author: '白居易', dynasty: '唐', content: '一道残阳铺水中，半江瑟瑟半江红。可怜九月初三夜，露似真珠月似弓。', translation: '一道夕阳斜照在江水中，江水一半碧绿一半通红。可爱的是九月初三的夜晚，露水像珍珠月亮像弯弓。', appreciation: '诗人写深秋江上的夕阳和新月，色彩明丽比喻精巧。', category: '秋景' },
    { title: '大林寺桃花', author: '白居易', dynasty: '唐', content: '人间四月芳菲尽，山寺桃花始盛开。长恨春归无觅处，不知转入此中来。', translation: '人间四月里百花都已凋谢，山寺里的桃花才刚刚盛开。常埋怨春天归去无处寻找，没想到它转到这山里来了。', appreciation: '诗人写山寺桃花晚开的惊喜，含蓄地表达对春天的留恋。', category: '春景' },
    { title: '夜雪', author: '白居易', dynasty: '唐', content: '已讶衾枕冷，复见窗户明。夜深知雪重，时闻折竹声。', translation: '已经惊讶被枕冰冷，又看见窗外格外明亮。夜深知道雪下得大，不时听到竹子被压折的声音。', appreciation: '诗人从触觉视觉听觉写夜雪，不写雪字却句句写雪。', category: '冬景' },
    { title: '卖炭翁', author: '白居易', dynasty: '唐', content: '卖炭翁，伐薪烧炭南山中。满面尘灰烟火色，两鬓苍苍十指黑。卖炭得钱何所营？身上衣裳口中食。可怜身上衣正单，心忧炭贱愿天寒。', translation: '卖炭的老翁，在南山里砍柴烧炭。满面灰尘烟火的颜色，两鬓灰白十指乌黑。卖炭得来的钱做什么用？买身上的衣服和口中的粮食。可怜他身上衣服单薄，却担心炭价低廉盼望天寒。', appreciation: '诗人写卖炭老人的辛劳和贫苦，揭露了宫市的掠夺本质。', category: '悯农' },
    { title: '钱塘湖春行·续', author: '白居易', dynasty: '唐', content: '几处早莺争暖树，谁家新燕啄春泥。', translation: '几只早来的黄莺争着飞向向阳的暖树，不知谁家新来的燕子衔着春泥筑巢。', appreciation: '诗人写早春莺燕的活泼，展现春日的勃勃生机。', category: '春景' },
    { title: '秋词', author: '刘禹锡', dynasty: '唐', content: '自古逢秋悲寂寥，我言秋日胜春朝。晴空一鹤排云上，便引诗情到碧霄。', translation: '自古以来人们遇到秋天就悲叹寂寥，我说秋天胜过春天。晴朗天空一只白鹤冲破云层飞上，便把诗情带到了碧蓝的天空。', appreciation: '诗人一反悲秋的常调，以鹤飞冲天写豪迈乐观的情怀。', category: '秋景' },
    { title: '竹枝词', author: '刘禹锡', dynasty: '唐', content: '杨柳青青江水平，闻郎江上踏歌声。东边日出西边雨，道是无晴却有晴。', translation: '杨柳青青江水平静，听到江上有男子踏歌的声音。东边出太阳西边下雨，说是没晴吧却有晴。', appreciation: '诗人以晴谐情写少女对爱情的揣测，民歌风味浓郁。', category: '爱情' },
    { title: '乌衣巷', author: '刘禹锡', dynasty: '唐', content: '朱雀桥边野草花，乌衣巷口夕阳斜。旧时王谢堂前燕，飞入寻常百姓家。', translation: '朱雀桥边长满野草野花，乌衣巷口夕阳斜照。从前王谢两家堂前的燕子，如今飞进了寻常百姓家。', appreciation: '诗人借燕子写世家大族的衰落，抒发历史兴亡的感慨。', category: '咏史' },
    { title: '再游玄都观', author: '刘禹锡', dynasty: '唐', content: '百亩庭中半是苔，桃花净尽菜花开。种桃道士归何处，前度刘郎今又来。', translation: '百亩的庭院里一半是青苔，桃花都没了菜花却开着。种桃的道士去了哪里，从前的刘郎今天又来了。', appreciation: '诗人借玄都观桃花的变迁，讽刺朝政更迭表现不屈的意志。', category: '咏史' },
    { title: '戏赠看花诸君子', author: '刘禹锡', dynasty: '唐', content: '紫陌红尘拂面来，无人不道看花回。玄都观里桃千树，尽是刘郎去后栽。', translation: '京城的路上尘土扑面，没有人不说自己是看花回来。玄都观里千棵桃树，都是刘郎离开后栽种的。', appreciation: '诗人借看桃花讽刺朝中权贵，含蓄地表达不满。', category: '咏史' },
    { title: '左迁至蓝关示侄孙湘', author: '韩愈', dynasty: '唐', content: '一封朝奏九重天，夕贬潮州路八千。欲为圣明除弊事，肯将衰朽惜残年！云横秦岭家何在？雪拥蓝关马不前。知汝远来应有意，好收吾骨瘴江边。', translation: '早晨上奏章给皇帝，傍晚就被贬到八千里外的潮州。本想为圣明君主除去弊政，怎肯因衰老而吝惜残年！云雾横陈秦岭家乡在哪里，大雪阻塞蓝关马儿不肯向前。知道你远来该有深意，好在瘴江边收我的尸骨。', appreciation: '诗人写忠而获罪的悲愤，又以马不前写眷恋朝廷之情，沉郁悲壮。', category: '抒怀' },
    { title: '登柳州城楼寄漳汀封连四州', author: '柳宗元', dynasty: '唐', content: '城上高楼接大荒，海天愁思正茫茫。惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。共来百越文身地，犹自音书滞一乡。', translation: '城上的高楼连接着荒野，海天间的愁思正茫茫。狂风掀动着荷花池水，密雨斜打着薜荔墙。岭树重重遮挡了千里目光，江水弯曲像九回的愁肠。我们一同来到百越文身之地，音信仍然滞留在一方。', appreciation: '诗人写登楼远望的愁苦，表达对友人的思念和贬谪的悲凉。', category: '抒怀' },
    { title: '锦瑟', author: '李商隐', dynasty: '唐', content: '锦瑟无端五十弦，一弦一柱思华年。庄生晓梦迷蝴蝶，望帝春心托杜鹃。沧海月明珠有泪，蓝田日暖玉生烟。此情可待成追忆，只是当时已惘然。', translation: '锦瑟为什么有五十根弦，每一弦每一柱都让我思念青春年华。庄周梦见蝴蝶不知是梦，望帝把春心托付给杜鹃。沧海月明珍珠像流泪，蓝田日暖美玉生出烟雾。这种感情难道要等到追忆时才有，只是当时就已经怅惘了。', appreciation: '诗人借锦瑟追忆往事，意境朦胧凄美，是千古传诵的名篇。', category: '抒怀' },
    { title: '嫦娥', author: '李商隐', dynasty: '唐', content: '云母屏风烛影深，长河渐落晓星沉。嫦娥应悔偷灵药，碧海青天夜夜心。', translation: '云母屏风后烛影深重，银河渐落晨星沉没。嫦娥应该后悔偷了灵药，碧海青天夜夜独自伤心。', appreciation: '诗人借嫦娥写孤寂之情，含蓄地表达自己的清高和寂寞。', category: '抒怀' },
    { title: '贾生', author: '李商隐', dynasty: '唐', content: '宣室求贤访逐臣，贾生才调更无伦。可怜夜半虚前席，不问苍生问鬼神。', translation: '汉文帝在宣室求贤访问被贬的贾谊，贾谊的才华无人能比。可惜半夜虚前移席靠近，不问百姓疾苦却问鬼神之事。', appreciation: '诗人借贾谊之事讽刺统治者不重人才，抒发怀才不遇的感慨。', category: '咏史' },
    { title: '霜月', author: '李商隐', dynasty: '唐', content: '初闻征雁已无蝉，百尺楼高水接天。青女素娥俱耐冷，月中霜里斗婵娟。', translation: '刚听到南飞大雁已听不到蝉鸣，百尺高楼之上水天相接。青女素娥都耐得住寒冷，在月中霜里比赛美丽。', appreciation: '诗人写霜月之美，借神话人物表现高洁清冷的美。', category: '秋景' },
    { title: '寄令狐郎中', author: '李商隐', dynasty: '唐', content: '嵩云秦树久离居，双鲤迢迢一纸书。休问梁园旧宾客，茂陵秋雨病相如。', translation: '你在长安我在洛阳长久分离，远方寄来一封书信。不要问梁园的旧宾客，茂陵秋雨中正病着像司马相如。', appreciation: '诗人写久别收到友人书信的感慨，含蓄地表达自己的失意和病愁。', category: '友情' },
    { title: '隋宫', author: '李商隐', dynasty: '唐', content: '紫泉宫殿锁烟霞，欲取芜城作帝家。玉玺不缘归日角，锦帆应是到天涯。于今腐草无萤火，终古垂杨有暮鸦。地下若逢陈后主，岂宜重问后庭花。', translation: '紫泉宫殿锁在烟霞中，隋炀帝却想以芜城为家。若不是玉玺归于日角之相的李渊，他的锦帆怕是要游到天涯。如今腐草里已没有萤火，自古垂杨上只有暮鸦。地下如果遇见陈后主，怎能再问后庭花呢。', appreciation: '诗人借隋朝灭亡讽刺统治者荒淫误国，怀古伤今。', category: '咏史' },
    { title: '落花', author: '李商隐', dynasty: '唐', content: '高阁客竟去，小园花乱飞。参差连曲陌，迢递送斜晖。肠断未忍扫，眼穿仍欲归。芳心向春尽，所得是沾衣。', translation: '高阁上的客人终究走了，小园里落花纷飞。落花参差落在弯曲的小路上，远远地送着夕阳。伤心断肠不忍打扫，望眼欲穿春仍要归去。花儿的心意随春天结束，得到的只是沾湿衣襟的泪水。', appreciation: '诗人借落花写惜春之情和身世之感，凄婉动人。', category: '春景' },
    { title: '风雨', author: '李商隐', dynasty: '唐', content: '凄凉宝剑篇，羁泊欲穷年。黄叶仍风雨，青楼自管弦。新知遭薄俗，旧好隔良缘。心断新丰酒，销愁斗几千。', translation: '凄凉地吟咏着宝剑篇，漂泊他乡度过年年。黄叶仍在风雨中飘落，青楼里照旧奏着管弦。新朋友遭到薄俗的对待，旧交也因好的缘由相隔。心已断绝新丰酒，消愁还要斗酒几千。', appreciation: '诗人写羁旅漂泊的凄凉和怀才不遇的悲愤，沉郁感人。', category: '抒怀' },
    { title: '凉思', author: '李商隐', dynasty: '唐', content: '客去波平槛，蝉休露满枝。永怀当此节，倚立自移时。北斗兼春远，南陵寓使迟。天涯占梦数，疑误有新知。', translation: '客人离去水波平齐栏杆，蝉停歇露水挂满枝头。永怀思念正当此时节，倚立着独自徘徊。北斗星和春天一样遥远，南陵的使者迟迟不来。在天涯占卜梦境多次，怀疑误有了新知己。', appreciation: '诗人写秋夜思友之情，含蓄地表达羁旅的孤寂和思念。', category: '秋景' },
    { title: '蜂', author: '罗隐', dynasty: '唐', content: '不论平地与山尖，无限风光尽被占。采得百花成蜜后，为谁辛苦为谁甜。', translation: '不论平地还是山顶，无限的风光都被蜜蜂占尽。采了百花酿成蜂蜜后，到底是为谁辛苦为谁甜呢。', appreciation: '诗人借蜜蜂写劳动者的辛苦，含蓄地讽喻不劳而获者。', category: '咏物' },
    { title: '雪', author: '罗隐', dynasty: '唐', content: '尽道丰年瑞，丰年事若何。长安有贫者，为瑞不宜多。', translation: '都说瑞雪兆丰年，丰年又怎样呢。长安城里有贫苦的人，瑞雪不宜下太多。', appreciation: '诗人借咏雪表达对贫苦百姓的同情，立意新颖。', category: '冬景' },
    { title: '不第后赋菊', author: '黄巢', dynasty: '唐', content: '待到秋来九月八，我花开后百花杀。冲天香阵透长安，满城尽带黄金甲。', translation: '等到秋天九月初八重阳节，我的菊花开后百花都凋谢。冲天的菊花香气透满长安城，满城都披上金黄的铠甲。', appreciation: '诗人借菊花抒发豪情壮志，气魄宏大，带有反叛色彩。', category: '咏物' },
    { title: '题菊花', author: '黄巢', dynasty: '唐', content: '飒飒西风满院栽，蕊寒香冷蝶难来。他年我若为青帝，报与桃花一处开。', translation: '飒飒西风中菊花种满庭院，花蕊寒冷香气清冷蝴蝶难来。他年我若做了春神青帝，就让它和桃花一起开放。', appreciation: '诗人借菊花抒发改变命运的抱负，气概不凡。', category: '咏物' },
    { title: '菊花', author: '元稹', dynasty: '唐', content: '秋丛绕舍似陶家，遍绕篱边日渐斜。不是花中偏爱菊，此花开尽更无花。', translation: '秋天的菊花丛环绕房屋像陶渊明家，绕着篱笆看花太阳已西斜。不是在花中偏爱菊花，只是菊花开尽就没有别的花了。', appreciation: '诗人写对菊花的喜爱，赞美菊花凌寒独放的精神。', category: '咏物' },
    { title: '离思', author: '元稹', dynasty: '唐', content: '曾经沧海难为水，除却巫山不是云。取次花丛懒回顾，半缘修道半缘君。', translation: '经历过沧海就难以被别的水吸引，除了巫山的云都不是云。从花丛中走过懒得回头看，一半是为了修道一半是为了你。', appreciation: '诗人以沧海巫山比喻爱情的忠贞，表达对亡妻的深情。', category: '爱情' },
    { title: '行宫', author: '元稹', dynasty: '唐', content: '寥落古行宫，宫花寂寞红。白头宫女在，闲坐说玄宗。', translation: '荒凉的古旧行宫，宫花寂寞地开着红花。白头宫女还在，闲坐着说起唐玄宗。', appreciation: '诗人借行宫白头宫女写盛衰之叹，含蓄深沉。', category: '咏史' },
    { title: '题李凝幽居', author: '贾岛', dynasty: '唐', content: '闲居少邻并，草径入荒园。鸟宿池边树，僧敲月下门。', translation: '闲居很少有邻居，草径通入荒园。鸟儿栖息在池边的树上，僧人月下敲门。', appreciation: '诗人写友人幽居的清幽，僧敲月下门一句留下推敲的典故。', category: '田园' },
    { title: '江上渔者', author: '范仲淹', dynasty: '宋', content: '江上往来人，但爱鲈鱼美。君看一叶舟，出没风波里。', translation: '江上来来往往的人，只喜爱鲈鱼的鲜美。你看那一叶小舟，在风浪中出没。', appreciation: '诗人借鲈鱼写渔民的辛苦，劝人珍惜劳动成果。', category: '悯农' },
    { title: '苏幕遮', author: '范仲淹', dynasty: '宋', content: '碧云天，黄叶地，秋色连波，波上寒烟翠。山映斜阳天接水，芳草无情，更在斜阳外。黯乡魂，追旅思，夜夜除非，好梦留人睡。明月楼高休独倚，酒入愁肠，化作相思泪。', translation: '蓝天碧云，地上黄叶，秋色连着江波，波上寒烟青翠。山映斜阳天连接水，芳草无情，更在斜阳之外。黯然思乡，追寻旅途思绪，夜夜除非有好梦才能入睡。明月下高楼不要独自倚靠，酒入愁肠，化作相思的泪水。', appreciation: '词人写秋日思乡之情，碧云天黄叶地一句成为写秋名句。', category: '秋景' },
    { title: '雨霖铃', author: '柳永', dynasty: '宋', content: '寒蝉凄切，对长亭晚，骤雨初歇。都门帐饮无绪，留恋处，兰舟催发。执手相看泪眼，竟无语凝噎。念去去，千里烟波，暮霭沉沉楚天阔。多情自古伤离别，更那堪，冷落清秋节！今宵酒醒何处？杨柳岸，晓风残月。此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？', translation: '秋蝉凄凉地鸣叫，面对长亭已是傍晚，骤雨刚刚停歇。京城门外设帐饮酒没有心情，留恋之时，兰舟催着出发。握着手含泪相看，竟哽咽说不出话。想到这一去，千里烟波，暮霭沉沉楚天辽阔。多情的人自古以来就伤心离别，更哪堪这清冷的秋天。今夜酒醒在何处？杨柳岸边，晓风残月。这一去经年，应是良辰美景都成虚设。纵有千种风情，又向谁人诉说？', appreciation: '词人写离别的悲伤，杨柳岸晓风残月一句成为千古名句。', category: '送别' },
    { title: '蝶恋花·柳永', author: '柳永', dynasty: '宋', content: '伫倚危楼风细细，望极春愁，黯黯生天际。草色烟光残照里，无言谁会凭阑意。拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。', translation: '久久倚立在高楼上微风吹拂，望尽春愁，黯然从天边生起。草色烟光在夕阳里，无言谁懂我凭栏的心意。打算借疏狂求得一醉，对酒高歌，勉强作乐也无味。衣带渐渐宽松也不后悔，为了她消瘦憔悴也值得。', appreciation: '词人写相思之情，衣带渐宽终不悔一句成为执着追求的名句。', category: '爱情' },
    { title: '望海潮', author: '柳永', dynasty: '宋', content: '东南形胜，三吴都会，钱塘自古繁华。烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。', translation: '东南一带形势绝佳，三吴的都会，钱塘自古繁华。烟柳画桥，风帘翠幕，高低错落十万人家。云树环绕着堤沙，怒涛卷起霜雪般浪花，天堑无边无涯。市上摆满珠玑，家家罗绮满箱，争相斗富。', appreciation: '词人写杭州的繁华景象，气象开阔，描绘细致。', category: '写景' },
    { title: '一剪梅', author: '李清照', dynasty: '宋', content: '红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来，雁字回时，月满西楼。花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。', translation: '红荷花谢了竹席也凉了秋天。轻轻解开罗裙，独自登上兰舟。云中谁寄来锦书，大雁飞回时，月光洒满西楼。花儿独自飘落水独自流。同一种相思，两处的闲愁。这种感情无法消除，刚从眉头消去，又涌上心头。', appreciation: '词人写对丈夫的思念，才下眉头却上心头一句把相思写得真切动人。', category: '思乡' },
    { title: '声声慢', author: '李清照', dynasty: '宋', content: '寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急？雁过也，正伤心，却是旧时相识。满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑？梧桐更兼细雨，到黄昏、点点滴滴。这次第，怎一个愁字了得！', translation: '寻寻觅觅，冷冷清清，凄凄惨惨戚戚。忽暖忽寒的时候，最难休息。三杯两杯淡酒，怎能抵挡晚来的急风？大雁飞过，正伤心时，却是旧时相识。满地菊花堆积，憔悴不堪，如今有谁能摘？守着窗儿，独自一人怎么熬到天黑？梧桐又加上细雨，到黄昏点点滴滴。这情景，怎是一个愁字能说完的！', appreciation: '词人写晚年孤苦的愁苦，连用叠字开篇，被誉为千古绝唱。', category: '抒怀' },
    { title: '如梦令', author: '李清照', dynasty: '宋', content: '常记溪亭日暮，沉醉不知归路。兴尽晚回舟，误入藕花深处。争渡，争渡，惊起一滩鸥鹭。', translation: '常想起溪亭傍晚时分，喝醉了不知回家的路。尽兴后晚上划船回去，误入荷花深处。怎么渡过去，怎么渡过去，惊起了一滩鸥鹭。', appreciation: '词人写少女时期一次郊游的趣事，活泼生动富有情趣。', category: '夏景' },
    { title: '武陵春', author: '李清照', dynasty: '宋', content: '风住尘香花已尽，日晚倦梳头。物是人非事事休，欲语泪先流。闻说双溪春尚好，也拟泛轻舟。只恐双溪舴艋舟，载不动许多愁。', translation: '风停了花也落尽了尘土留香，日头高了懒得梳头。物是人非一切都完了，想说话泪先流下。听说双溪春光还好，也打算泛舟游玩。只怕双溪的小船，载不动这许多愁。', appreciation: '词人写晚年愁苦，载不动许多愁一句把愁写得沉重可感。', category: '抒怀' },
    { title: '醉花阴', author: '李清照', dynasty: '宋', content: '薄雾浓云愁永昼，瑞脑销金兽。佳节又重阳，玉枕纱厨，半夜凉初透。东篱把酒黄昏后，有暗香盈袖。莫道不销魂，帘卷西风，人比黄花瘦。', translation: '薄雾浓云愁闷地度过漫长的一天，瑞脑香在金兽炉中燃尽。又到了重阳佳节，玉枕纱帐，半夜凉意初透。黄昏后在东篱下饮酒，有暗香充满衣袖。别说我不销魂，西风卷起窗帘，人比黄菊花还瘦。', appreciation: '词人写重阳节的相思，人比黄花瘦一句成为写相思的名句。', category: '抒怀' },
    { title: '鹧鸪天', author: '晏几道', dynasty: '宋', content: '彩袖殷勤捧玉钟，当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇底风。从别后，忆相逢，几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中。', translation: '彩袖殷勤地捧着玉酒杯，当年拼了醉红了脸。舞跳到月亮落下杨柳楼心，歌唱到桃花扇底风尽。分别以后，回忆相逢，几回在梦里与你同在。今夜举着银灯照了又照，还怕相逢是在梦中。', appreciation: '词人写重逢的惊喜，今宵剩把银釭照一句把惊喜疑梦写得真切。', category: '爱情' },
    { title: '临江仙', author: '晏几道', dynasty: '宋', content: '梦后楼台高锁，酒醒帘幕低垂。去年春恨却来时。落花人独立，微雨燕双飞。记得小蘋初见，两重心字罗衣。琵琶弦上说相思。当时明月在，曾照彩云归。', translation: '梦醒后楼台紧锁，酒醒后帘幕低垂。去年的春恨又来时。落花中独自站立，微雨中燕子成双飞。记得初见小蘋时，她穿着心字罗衣。琵琶弦上诉说相思。当时的明月还在，曾照着她如彩云般归去。', appreciation: '词人写对歌女的思念，落花人独立微雨燕双飞一句意境优美。', category: '爱情' },
    { title: '采桑子', author: '欧阳修', dynasty: '宋', content: '群芳过后西湖好，狼籍残红，飞絮濛濛，垂柳阑干尽日风。笙歌散尽游人去，始觉春空。垂下帘栊，双燕归来细雨中。', translation: '百花凋谢后西湖依然美好，落花狼藉，飞絮濛濛，垂柳栏杆边整日吹风。笙歌散尽游人离去，才觉得春天空了。垂下窗帘，双燕在细雨中归来。', appreciation: '词人写暮春西湖的景色，恬淡闲适富有情趣。', category: '春景' },
    { title: '踏莎行', author: '欧阳修', dynasty: '宋', content: '候馆梅残，溪桥柳细，草薰风暖摇征辔。离愁渐远渐无穷，迢迢不断如春水。寸寸柔肠，盈盈粉泪，楼高莫近危阑倚。平芜尽处是春山，行人更在春山外。', translation: '客馆旁梅花凋谢，溪桥边柳枝纤细，草香风暖摇动马缰。离愁越远越无穷，迢迢不断像春水。寸寸柔肠，盈盈粉泪，楼高不要靠近危栏倚靠。平原尽头是春山，行人更在春山之外。', appreciation: '词人写离愁，从行人和思妇两方面写，曲折深情。', category: '送别' },
    { title: '生查子', author: '欧阳修', dynasty: '宋', content: '去年元夜时，花市灯如昼。月上柳梢头，人约黄昏后。今年元夜时，月与灯依旧。不见去年人，泪湿春衫袖。', translation: '去年元宵节时，花市灯火像白天一样明亮。月亮升上柳梢头，约好黄昏后相见。今年元宵节时，月亮和灯火依旧。看不见去年的人，泪水湿透了春天的衣袖。', appreciation: '词人借元宵节写爱情的聚散，月上柳梢头一句成为写爱情的名句。', category: '爱情' },
    { title: '鹊桥仙', author: '秦观', dynasty: '宋', content: '纤云弄巧，飞星传恨，银汉迢迢暗度。金风玉露一相逢，便胜却人间无数。柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮。', translation: '纤云展示精巧，流星传递离恨，暗暗渡过遥远的银河。秋风白露中一旦相逢，便胜过人间无数相聚。柔情像水一样，佳期像梦一样，怎忍回头看鹊桥归路。两人的感情如果是长久的，又何必在乎朝朝暮暮相伴。', appreciation: '词人借牛郎织女写爱情，两情久长一句成为歌颂坚贞爱情的名句。', category: '爱情' },
    { title: '苏幕遮·周邦彦', author: '周邦彦', dynasty: '宋', content: '燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。', translation: '烧沉香，消解潮湿暑气。鸟雀呼唤晴天，清晨在檐下鸣叫。叶上初阳晒干了昨夜的雨，水面清圆，一片片荷叶被风举起。故乡遥远，何时归去？家住吴门，久在长安作客。五月渔郎可曾记得我？划着小船，梦中进入荷花丛。', appreciation: '词人写思乡之情，一一风荷举一句写荷花姿态极佳。', category: '思乡' },
    { title: '摸鱼儿', author: '辛弃疾', dynasty: '宋', content: '更能消、几番风雨，匆匆春又归去。惜春长怕花开早，何况落红无数。春且住，见说道、天涯芳草无归路。怨春不语。算只有殷勤，画檐蛛网，尽日惹飞絮。', translation: '还能经得起几番风雨，匆匆春天又归去了。惜春常怕花开太早，何况落花无数。春天且留住，听说道天涯芳草没有归路。埋怨春天却不说话。算来只有殷勤的画檐蛛网，整日惹着飞絮。', appreciation: '词人借惜春抒发壮志未酬的悲愤，含蓄深沉。', category: '抒怀' },
    { title: '永遇乐·京口北固亭', author: '辛弃疾', dynasty: '宋', content: '千古江山，英雄无觅，孙仲谋处。舞榭歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎。', translation: '千古江山，再也找不到像孙权那样的英雄。歌舞的楼台，风流往事总被风雨吹散。斜阳照着草木，寻常的巷陌，人说刘裕曾住在这里。想当年，金戈铁马，气吞万里如虎。', appreciation: '词人借京口怀古抒发抗金壮志，气势豪迈沉郁。', category: '咏史' },
    { title: '青玉案·元夕', author: '辛弃疾', dynasty: '宋', content: '东风夜放花千树，更吹落，星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞。蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。', translation: '东风夜里吹开千树花灯，又吹落如雨的烟花。宝马雕车香气满路。凤箫声响，月光流转，一夜鱼龙舞动。头上戴着蛾儿雪柳黄金缕，笑语盈盈带着暗香走过。在人群中寻找他千百回，忽然回头，那人却在灯火稀疏的地方。', appreciation: '词人借元宵节写孤高自赏的情怀，蓦然回首一句成为千古名句。', category: '节日' },
    { title: '丑奴儿·书博山道中壁', author: '辛弃疾', dynasty: '宋', content: '少年不识愁滋味，爱上层楼。爱上层楼，为赋新词强说愁。而今识尽愁滋味，欲说还休。欲说还休，却道天凉好个秋。', translation: '少年时不懂得愁的滋味，喜欢登高楼。喜欢登高楼，为写新词勉强说愁。如今尝尽了愁的滋味，想说又不说。想说又不说，却说天气凉快好个秋天。', appreciation: '词人写少年和老来的不同心境，对比中显出深沉的愁苦。', category: '抒怀' },
    { title: '贺新郎', author: '辛弃疾', dynasty: '宋', content: '甚矣吾衰矣。怅平生、交游零落，只今余几！我见青山多妩媚，料青山见我应如是。情与貌，略相似。', translation: '我真是老得厉害了。怅惘平生，朋友零落，如今还剩几个！我看青山十分妩媚，料想青山看我也是如此。情与貌，大体相似。', appreciation: '词人借青山写自己的孤高，表达知音稀少的感慨。', category: '抒怀' },
    { title: '虞美人', author: '李煜', dynasty: '五代', content: '春花秋月何时了？往事知多少。小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。', translation: '春花秋月什么时候才能了结？往事能有多少。小楼昨夜又吹来东风，在明月中不堪回首故国。雕花的栏杆玉石的台阶应该还在，只是人的容颜已经改变。问你有多少愁？就像一江春水向东流去。', appreciation: '词人写亡国之痛，以江水喻愁成为千古名句，被誉为绝命词。', category: '抒怀' },
    { title: '浪淘沙令', author: '李煜', dynasty: '五代', content: '帘外雨潺潺，春意阑珊。罗衾不耐五更寒。梦里不知身是客，一晌贪欢。独自莫凭栏，无限江山，别时容易见时难。流水落花春去也，天上人间。', translation: '帘外雨声潺潺，春意将尽。丝绸被子抵挡不住五更的寒冷。梦里不知自己是客，还能贪图片刻欢乐。独自不要凭栏远望，那无限的江山，离别时容易再见时难。流水落花春天已经离去，从天上到人间。', appreciation: '词人写囚徒生活的凄凉和对故国的思念，流水落花一句尤为凄婉。', category: '思乡' },
    { title: '望洞庭湖赠张丞相', author: '孟浩然', dynasty: '唐', content: '八月湖水平，涵虚混太清。气蒸云梦泽，波撼岳阳城。欲济无舟楫，端居耻圣明。坐观垂钓者，徒有羡鱼情。', translation: '八月洞庭湖水涨平，水气弥漫和天相连。水气蒸腾云梦泽，波浪摇撼岳阳城。想渡水却没有船只，闲居又愧对圣明时代。坐看钓鱼的人，只有羡慕鱼的心情。', appreciation: '诗人写洞庭湖的壮阔，又含蓄地表达求仕之意，气蒸波撼一句雄浑。', category: '写景' },
    { title: '与诸子登岘山', author: '孟浩然', dynasty: '唐', content: '人事有代谢，往来成古今。江山留胜迹，我辈复登临。水落鱼梁浅，天寒梦泽深。羊公碑尚在，读罢泪沾襟。', translation: '人事有更替变化，往来成为古今。江山留下名胜古迹，我们再次登临。水落时鱼梁洲水浅，天寒时云梦泽深邃。羊公的碑还在，读完泪水沾湿衣襟。', appreciation: '诗人借登岘山抒发怀古之情，感叹人生短暂，含蓄地表达求名之心。', category: '咏史' },
    { title: '岁暮归南山', author: '孟浩然', dynasty: '唐', content: '北阙休上书，南山归敝庐。不才明主弃，多病故人疏。白发催年老，青阳逼岁除。永怀愁不寐，松月夜窗虚。', translation: '不再向朝廷上书，回到南山破旧的茅屋。没有才能被明主抛弃，多病故人也疏远。白发催人老去，春天逼近岁末。永远怀着愁绪睡不着，松间月光照着空窗。', appreciation: '诗人写怀才不遇的愁苦，不才明主弃一句含蓄地表达怨愤。', category: '抒怀' },
    { title: '旅夜书怀', author: '杜甫', dynasty: '唐', content: '细草微风岸，危樯独夜舟。星垂平野阔，月涌大江流。名岂文章著，官应老病休。飘飘何所似，天地一沙鸥。', translation: '微风吹着岸边细草，高高的桅杆立在夜间孤舟上。星星垂在广阔的平野上，月亮涌动在大江的流水中。名声难道是靠文章得来，做官应该因老病而休。飘飘荡荡像什么，就像天地间一只沙鸥。', appreciation: '诗人写旅途孤寂，星垂月涌一句气象阔大，结尾以沙鸥自喻孤苦。', category: '抒怀' },
    { title: '蜀相', author: '杜甫', dynasty: '唐', content: '丞相祠堂何处寻，锦官城外柏森森。映阶碧草自春色，隔叶黄鹂空好音。三顾频烦天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。', translation: '丞相的祠堂到哪里寻找，在锦官城外柏树茂密处。台阶上映着碧草独自显示春色，树叶间黄鹂空有悦耳的声音。三顾茅庐频繁劳烦定天下大计，辅佐两朝开创大业是老臣的心意。出师还没胜利就先死去，长久地让英雄泪满衣襟。', appreciation: '诗人凭吊诸葛亮，出师未捷身先死一句成为千古名句，赞颂忠臣。', category: '咏史' },
    { title: '客至', author: '杜甫', dynasty: '唐', content: '舍南舍北皆春水，但见群鸥日日来。花径不曾缘客扫，蓬门今始为君开。盘飧市远无兼味，樽酒家贫只旧醅。肯与邻翁相对饮，隔篱呼取尽余杯。', translation: '屋南屋北都是春水，只见成群的鸥鸟天天飞来。花间小路不曾为客人打扫，柴门今天才为你打开。离集市远盘中没有多样菜肴，家境贫寒只有旧酒。肯不肯和邻家老翁对饮，隔着篱笆叫他来喝尽剩下的酒。', appreciation: '诗人写待客的真挚热情，表现了淳朴的友情和生活情趣。', category: '友情' },
    { title: '江汉', author: '杜甫', dynasty: '唐', content: '江汉思归客，乾坤一腐儒。片云天共远，永夜月同孤。落日心犹壮，秋风病欲苏。古来存老马，不必取长途。', translation: '我是江汉间思归的客子，天地间一个迂腐的儒生。和一片云共在天边，和长夜的月亮一同孤独。落日时心还壮健，秋风中病将要痊愈。自古以来养老马，不一定让它跑长途。', appreciation: '诗人写漂泊老病却仍壮心不已，以老马自喻表现不屈的精神。', category: '抒怀' },
    { title: '秋兴八首·其一', author: '杜甫', dynasty: '唐', content: '玉露凋伤枫树林，巫山巫峡气萧森。江间波浪兼天涌，塞上风云接地阴。丛菊两开他日泪，孤舟一系故园心。寒衣处处催刀尺，白帝城高急暮砧。', translation: '白露使枫树林凋伤，巫山巫峡气象萧瑟。江间波浪滔天涌起，塞上风云接地阴沉。丛菊两次开放流下昔日泪水，孤舟系着对故园的思念。到处都在催着裁剪寒衣，白帝城高处傍晚急促地传来捣衣声。', appreciation: '诗人写秋日巫峡的萧瑟，抒发漂泊思乡的愁苦，沉郁顿挫。', category: '秋景' },
    { title: '咏怀古迹·其三', author: '杜甫', dynasty: '唐', content: '群山万壑赴荆门，生长明妃尚有村。一去紫台连朔漠，独留青冢向黄昏。画图省识春风面，环珮空归夜月魂。千载琵琶作胡语，分明怨恨曲中论。', translation: '群山万壑奔赴荆门，生长王昭君的村子还在。一离开汉宫就远连北方沙漠，只留下青冢面对黄昏。画图曾识过她的美丽容颜，环佩空归的只有月夜魂魄。千年琵琶奏出胡地乐曲，分明在曲中诉说着怨恨。', appreciation: '诗人借王昭君写怀才不遇的怨恨，含蓄地抒发自己的身世之感。', category: '咏史' },
    { title: '阁夜', author: '杜甫', dynasty: '唐', content: '岁暮阴阳催短景，天涯霜雪霁寒宵。五更鼓角声悲壮，三峡星河影动摇。野哭千家闻战伐，夷歌数处起渔樵。卧龙跃马终黄土，人事音书漫寂寥。', translation: '岁末阴阳催促着短暂的白昼，天涯霜雪后寒夜放晴。五更时鼓角声悲壮，三峡中星河的倒影动摇。千家野哭声里听到战伐，几处渔樵唱起夷歌。卧龙跃马终究归于黄土，人事音书都寂寥。', appreciation: '诗人写岁末夔州的夜景，抒发战乱中的感慨和对历史人生的思索。', category: '秋景' },
    { title: '闺怨', author: '王昌龄', dynasty: '唐', content: '闺中少妇不知愁，春日凝妆上翠楼。忽见陌头杨柳色，悔教夫婿觅封侯。', translation: '闺中的少妇不知愁苦，春日里盛妆登上翠楼。忽然看见路边杨柳青青，后悔让丈夫去寻求封侯。', appreciation: '诗人写闺中少妇的悔悟，以杨柳色触发愁绪，细腻含蓄。', category: '抒怀' },
    { title: '燕歌行', author: '高适', dynasty: '唐', content: '汉家烟尘在东北，汉将辞家破残贼。男儿本自重横行，天子非常赐颜色。摐金伐鼓下榆关，旌旆逶迤碣石间。', translation: '汉朝的战火在东北燃起，汉将辞别家人去击败残敌。男儿本来就看重驰骋沙场，天子格外地赐予恩宠。敲金击鼓下榆关，旌旗逶迤在碣石之间。', appreciation: '诗人写边塞战争，又同情戍卒的辛苦，是边塞诗的代表作。', category: '边塞' },
    { title: '碛中作', author: '岑参', dynasty: '唐', content: '走马西来欲到天，辞家见月两回圆。今夜不知何处宿，平沙万里绝人烟。', translation: '骑马向西走好像要到天边，离家后月亮已经圆了两次。今夜不知在哪里住宿，万里黄沙没有一点人烟。', appreciation: '诗人写旅途的荒凉和思乡，画面苍凉而壮阔。', category: '边塞' },
    { title: '春梦', author: '岑参', dynasty: '唐', content: '洞房昨夜春风起，故人尚隔湘江水。枕上片时春梦中，行尽江南数千里。', translation: '洞房里昨夜吹起春风，故人还隔着湘江水。枕上片刻的春梦之中，走遍了江南数千里。', appreciation: '诗人借梦写相思，片时春梦行尽千里，构思巧妙。', category: '爱情' },
    { title: '山房春事', author: '岑参', dynasty: '唐', content: '风恬日暖荡春光，戏蝶游蜂乱进房。数枝门柳低衣桁，一片山花落笔床。', translation: '风和日丽荡漾着春光，蝴蝶蜜蜂乱飞进房。几枝门前的柳枝低垂到衣架上，一片山花落在笔床上。', appreciation: '诗人写山居春景的活泼可爱，富有生活气息。', category: '春景' },
    { title: '淮上喜会梁川故人', author: '韦应物', dynasty: '唐', content: '江汉曾为客，相逢每醉还。浮云一别后，流水十年间。欢笑情如旧，萧疏鬓已斑。何因不归去？淮上有秋山。', translation: '我们曾在江汉一带作客，相逢每次都醉着回家。像浮云一样分别后，像流水一样过了十年。欢笑之情还像从前，只是稀疏的鬓发已经斑白。为什么还不归去？因为淮上有秋天的山色。', appreciation: '诗人写久别重逢的喜悦和时光流逝的感慨，感情真挚。', category: '友情' },
    { title: '长沙过贾谊宅', author: '刘长卿', dynasty: '唐', content: '三年谪宦此栖迟，万古惟留楚客悲。秋草独寻人去后，寒林空见日斜时。汉文有道恩犹薄，湘水无情吊岂知。寂寂江山摇落处，怜君何事到天涯。', translation: '贾谊被贬在此住了三年，万古只留下楚地客子的悲伤。秋草中独自寻觅他离去后的踪迹，寒林中只见夕阳西斜。汉文帝虽有道恩情却薄，湘水无情吊唁他哪里知道。寂寥的江山草木凋零之处，可怜你为何来到天涯。', appreciation: '诗人借吊贾谊抒发自己被贬的感慨，借古伤今。', category: '咏史' },
    { title: '李凭箜篌引', author: '李贺', dynasty: '唐', content: '吴丝蜀桐张高秋，空山凝云颓不流。江娥啼竹素女愁，李凭中国弹箜篌。昆山玉碎凤凰叫，芙蓉泣露香兰笑。', translation: '吴地的丝蜀地的桐木张成箜篌在秋天弹奏，空山中云凝结不流动。湘娥啼竹素女忧愁，李凭在京城弹箜篌。声音像昆山玉碎凤凰鸣叫，又像荷花泣露兰花欢笑。', appreciation: '诗人以奇特的想象写箜篌声的美妙，浪漫奇诡。', category: '抒怀' },
    { title: '马诗', author: '李贺', dynasty: '唐', content: '大漠沙如雪，燕山月似钩。何当金络脑，快走踏清秋。', translation: '大漠的沙像雪一样白，燕山的月亮像弯钩。什么时候能戴上金笼头，在清秋时节快跑。', appreciation: '诗人借骏马写自己的抱负，渴望被重用建功立业。', category: '咏物' },
    { title: '梦天', author: '李贺', dynasty: '唐', content: '老兔寒蟾泣天色，云楼半开壁斜白。玉轮轧露湿团光，鸾珮相逢桂香陌。黄尘清水三山下，更变千年如走马。', translation: '老兔寒蟾哭泣着天色，云楼半开墙壁斜白。玉轮碾过露水打湿了圆光，佩玉相会在桂花飘香的路上。黄尘清水在三座山下，千年变化就像跑马一样快。', appreciation: '诗人写梦游天上的奇景，想象瑰丽，富有浪漫色彩。', category: '抒怀' },
    { title: '山石', author: '韩愈', dynasty: '唐', content: '山石荦确行径微，黄昏到寺蝙蝠飞。升堂坐阶新雨足，芭蕉叶大栀子肥。僧言古壁佛画好，以火来照所见稀。', translation: '山石嶙峋小路狭窄，黄昏到寺庙时蝙蝠在飞。升堂坐在台阶上新雨刚足，芭蕉叶大栀子花肥。僧人说古壁上的佛画很好，拿火来照所见却稀少。', appreciation: '诗人写山寺避雨的所见，画面生动，富有生活气息。', category: '写景' },
    { title: '剑客', author: '贾岛', dynasty: '唐', content: '十年磨一剑，霜刃未曾试。今日把示君，谁有不平事。', translation: '十年磨出一把剑，寒霜般的剑刃还没试过。今天拿来给你看，谁有冤屈不平的事。', appreciation: '诗人借剑客写自己的抱负，表达渴望施展才能的急切心情。', category: '抒怀' },
    { title: '题乌江亭', author: '杜牧', dynasty: '唐', content: '胜败兵家事不期，包羞忍耻是男儿。江东子弟多才俊，卷土重来未可知。', translation: '胜败是兵家难以预料的事，能忍辱含羞才是真正的男子汉。江东子弟多才华出众的人，卷土重来胜负还说不定。', appreciation: '诗人借项羽之事抒发议论，认为能忍辱负重才是真男儿。', category: '咏史' },
    { title: '叹花', author: '杜牧', dynasty: '唐', content: '自是寻春去校迟，不须惆怅怨芳时。狂风落尽深红色，绿叶成阴子满枝。', translation: '本来是寻春去得太迟了，不必惆怅埋怨花期。狂风吹落了深红的花朵，绿叶成荫果实挂满枝头。', appreciation: '诗人借寻春迟了写错失良机的感慨，含蓄深沉。', category: '春景' },
    { title: '安定城楼', author: '李商隐', dynasty: '唐', content: '迢递高城百尺楼，绿杨枝外尽汀洲。贾生年少虚垂涕，王粲春来更远游。永忆江湖归白发，欲回天地入扁舟。不知腐鼠成滋味，猜意鹓雏竟未休。', translation: '高高的城楼上百尺高楼，绿杨枝外都是沙洲。贾谊年轻白白流泪，王粲春天还要远游。永远想着白发归隐江湖，想扭转乾坤后乘扁舟而去。不知腐鼠成了美味，猜忌鹓雏之心竟未停止。', appreciation: '诗人借古人写自己的抱负和被猜忌的愤懑，含蓄深沉。', category: '抒怀' },
    { title: '无题·昨夜星辰', author: '李商隐', dynasty: '唐', content: '昨夜星辰昨夜风，画楼西畔桂堂东。身无彩凤双飞翼，心有灵犀一点通。隔座送钩春酒暖，分曹射覆蜡灯红。嗟余听鼓应官去，走马兰台类转蓬。', translation: '昨夜星光灿烂昨夜春风，在画楼西边桂堂东边。身上没有彩凤的双翅可以飞去，心里却有灵犀一点相通。隔座玩送钩游戏春酒温暖，分组猜谜蜡灯通红。可叹我听到鼓声要去办公，骑马去兰台像转蓬一样。', appreciation: '诗人写昨夜宴会的情景和相思，心有灵犀一句成为写心意相通的名句。', category: '爱情' },
    { title: '菩萨蛮', author: '温庭筠', dynasty: '唐', content: '小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。', translation: '小山重叠金光明灭，鬓发像云要遮住雪白的香腮。懒洋洋地起来画蛾眉，梳洗打扮迟迟。照着前后镜看花，花和脸交相辉映。新贴上绣花的罗衣，上面有成双的金鹧鸪。', appreciation: '词人写女子晨起梳妆的情景，刻画细腻，是花间词的代表作。', category: '抒怀' },
    { title: '台城', author: '韦庄', dynasty: '唐', content: '江雨霏霏江草齐，六朝如梦鸟空啼。无情最是台城柳，依旧烟笼十里堤。', translation: '江上细雨霏霏江草茂盛，六朝像梦一样只剩鸟空啼。最无情的是台城的杨柳，依旧像烟雾笼罩十里长堤。', appreciation: '诗人借台城柳写六朝兴亡的感慨，含蓄深沉。', category: '咏史' },
    { title: '蝶恋花·晏殊', author: '晏殊', dynasty: '宋', content: '槛菊愁烟兰泣露，罗幕轻寒，燕子双飞去。明月不谙离恨苦，斜光到晓穿朱户。昨夜西风凋碧树，独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知何处。', translation: '栏杆边的菊花在烟雾中发愁兰花在露水中哭泣，罗幕里有些轻寒，燕子成双飞去。明月不懂得离恨的痛苦，斜光到天亮还穿过红色的门窗。昨夜西风吹凋了碧绿的树叶，独自登上高楼，望尽天涯路。想寄出彩笺和书信，山长水阔不知寄到哪里。', appreciation: '词人写离愁，独上高楼望尽天涯路一句境界开阔，被王国维喻为成大事业的第一境界。', category: '抒怀' },
    { title: '破阵子·春景', author: '晏殊', dynasty: '宋', content: '燕子来时新社，梨花落后清明。池上碧苔三四点，叶底黄鹂一两声。日长飞絮轻。巧笑东邻女伴，采桑径里逢迎。疑怪昨宵春梦好，元是今朝斗草赢。笑从双脸生。', translation: '燕子飞来时正值春社，梨花落后是清明。池上三四点碧苔，树叶下一两声黄鹂。白日长飞絮轻。东邻女伴巧笑，在采桑小路上相逢。怪不得昨夜春梦好，原来是今天斗草赢了。笑容从双颊生出。', appreciation: '词人写春日少女的生活，清新活泼富有生活气息。', category: '春景' },
    { title: '蝶恋花·欧阳修', author: '欧阳修', dynasty: '宋', content: '庭院深深深几许，杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处，楼高不见章台路。雨横风狂三月暮，门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。', translation: '庭院深深有多深，杨柳堆着烟雾，帘幕数不清。华美的车马停在游乐处，楼高看不见章台路。风雨狂暴三月暮，黄昏时关上门，无法留住春天。含泪问花花不说话，落花飞过秋千去。', appreciation: '词人写闺怨，泪眼问花一句把思妇的痴情写得真切动人。', category: '抒怀' },
    { title: '画眉鸟', author: '欧阳修', dynasty: '宋', content: '百啭千声随意移，山花红紫树高低。始知锁向金笼听，不及林间自在啼。', translation: '画眉鸟百转千声随意移动，在红紫山花和高低树木间。才知道锁在金笼里听它叫，不如在林间自由自在地啼鸣。', appreciation: '诗人借画眉鸟写向往自由的心情，含蓄地表达对官场的厌倦。', category: '咏物' },
    { title: '梅花', author: '王安石', dynasty: '宋', content: '墙角数枝梅，凌寒独自开。遥知不是雪，为有暗香来。', translation: '墙角有几枝梅花，冒着严寒独自开放。远远望去知道那不是雪，因为有淡淡的香气飘来。', appreciation: '诗人写梅花凌寒独放，赞美其高洁品格，暗香一词尤为传神。', category: '咏物' },
    { title: '定风波', author: '苏轼', dynasty: '宋', content: '莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。料峭春风吹酒醒，微冷，山头斜照却相迎。回首向来萧瑟处，归去，也无风雨也无晴。', translation: '不要听雨打树叶的声音，不妨一边吟唱一边慢慢走。竹杖草鞋比骑马还轻快，怕什么？一件蓑衣就能在烟雨中度过一生。微寒的春风吹醒了酒，有些冷，山头的夕阳却来相迎。回头看看刚才风雨萧瑟的地方，回去吧，既没有风雨也没有晴天。', appreciation: '词人借雨中行路写旷达的人生态度，也无风雨也无晴一句成为千古名句。', category: '抒怀' },
    { title: '念奴娇·赤壁怀古', author: '苏轼', dynasty: '宋', content: '大江东去，浪淘尽，千古风流人物。故垒西边，人道是，三国周郎赤壁。乱石穿空，惊涛拍岸，卷起千堆雪。江山如画，一时多少豪杰。遥想公瑾当年，小乔初嫁了，雄姿英发。羽扇纶巾，谈笑间，樯橹灰飞烟灭。故国神游，多情应笑我，早生华发。人生如梦，一尊还酹江月。', translation: '大江向东流去，浪花淘尽了千古风流人物。旧堡垒西边，人说就是三国时周瑜大破曹军的赤壁。乱石直插天空，惊涛拍打江岸，卷起千堆雪浪。江山如画，一时有多少英雄豪杰。遥想周瑜当年，小乔刚嫁给他，雄姿英发。手摇羽扇头戴纶巾，谈笑之间，曹军的船队就灰飞烟灭。神游故国，多情应笑我，过早生出白发。人生如梦，还是举杯洒酒祭奠江月吧。', appreciation: '词人借赤壁怀古抒发壮志未酬的感慨，是豪放词的代表作。', category: '咏史' },
    { title: '江城子·乙卯正月二十日夜记梦', author: '苏轼', dynasty: '宋', content: '十年生死两茫茫，不思量，自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处，明月夜，短松冈。', translation: '十年生死两茫茫，不去想，却自然难忘。千里之外的孤坟，没有地方诉说凄凉。纵使相逢应该也不认识了，我满面风尘，两鬓如霜。夜里忽然梦见回到家乡，小小的窗户前，你正在梳妆。相视无言，只有千行泪水。料想年年令人断肠的地方，就是明月之夜的短松冈。', appreciation: '词人写悼念亡妻的深情，真挚动人，是悼亡词的千古绝唱。', category: '爱情' },
    { title: '赠刘景文', author: '苏轼', dynasty: '宋', content: '荷尽已无擎雨盖，菊残犹有傲霜枝。一年好景君须记，最是橙黄橘绿时。', translation: '荷花谢了已经没有撑雨的荷叶，菊花残了还有傲霜的枝条。一年的好景色你要记住，最是橙子黄橘子绿的时候。', appreciation: '诗人写初冬的景色，赞美傲霜的菊花，勉励友人珍惜好时光。', category: '冬景' },
    { title: '卜算子·咏梅', author: '陆游', dynasty: '宋', content: '驿外断桥边，寂寞开无主。已是黄昏独自愁，更著风和雨。无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。', translation: '在驿站外断桥边，寂寞地开放没有主人。黄昏时已经独自忧愁，又加上风吹雨打。无意苦苦争春，任凭百花嫉妒。零落成泥被碾成尘土，只有香气依然如故。', appreciation: '词人借梅花写自己孤高不屈的品格，零落成泥只有香如故成为咏物名句。', category: '咏物' },
    { title: '钗头凤', author: '陆游', dynasty: '宋', content: '红酥手，黄縢酒，满城春色宫墙柳。东风恶，欢情薄。一怀愁绪，几年离索。错、错、错。春如旧，人空瘦，泪痕红浥鲛绡透。桃花落，闲池阁。山盟虽在，锦书难托。莫、莫、莫！', translation: '红润柔软的手，黄封的酒，满城春色宫墙边的柳树。东风无情，欢情淡薄。满怀愁绪，几年离别孤独。错、错、错。春天还像从前，人却白白消瘦，泪痕沾湿了红手帕。桃花飘落，池阁空闲。山盟虽然还在，锦书却难以寄托。罢了、罢了、罢了！', appreciation: '词人写与前妻唐婉的爱情悲剧，凄婉动人，是爱情词的绝唱。', category: '爱情' },
    { title: '夜书所见', author: '叶绍翁', dynasty: '宋', content: '萧萧梧叶送寒声，江上秋风动客情。知有儿童挑促织，夜深篱落一灯明。', translation: '萧萧的梧桐叶送来寒意，江上的秋风触动了客居的思乡之情。知道有孩子在捉蟋蟀，深夜篱笆旁一盏灯还亮着。', appreciation: '诗人写秋夜客居的所见所闻，以儿童捉蟋蟀反衬自己的孤寂。', category: '秋景' },
    //POEMS_END_MARKER
  ],
  // ===== 文言文 =====
  classics: [
    { title: '论语·学而（节选）', source: '《论语》', original: '子曰：学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠，不亦君子乎？', translation: '孔子说：学了知识然后按时温习，不是很愉快吗？有志同道合的朋友从远方来，不是很快乐吗？别人不了解自己却不生气，不就是君子吗？', notes: '子：对人的尊称，这里指孔子；曰：说；时：按时；习：温习；说：同悦，愉快；愠：生气；君子：品德高尚的人', category: '学习' },
    { title: '论语·为政（节选）', source: '《论语》', original: '子曰：温故而知新，可以为师矣。子曰：学而不思则罔，思而不学则殆。', translation: '孔子说：温习旧知识从而能获得新知识，就可以做老师了。孔子说：只学习却不思考就会迷惑，只思考却不学习就会危险。', notes: '温故：温习旧知识；罔：迷惑；殆：危险；可以为师：可以做老师', category: '学习' },
    { title: '论语·里仁（节选）', source: '《论语》', original: '子曰：见贤思齐焉，见不贤而内自省也。', translation: '孔子说：见到贤人就要向他看齐，见到不贤的人就要在心里反省自己。', notes: '贤：有德有才的人；齐：看齐；省：反省', category: '修身' },
    { title: '论语·述而（节选）', source: '《论语》', original: '子曰：三人行，必有我师焉。择其善者而从之，其不善者而改之。', translation: '孔子说：几个人一起走路，其中一定有可以做我老师的人。我选择他们的优点来学习，看到他们的缺点就改正自己。', notes: '三人：几个人；行：走路；焉：相当于于之；善者：好的方面', category: '学习' },
    { title: '论语·卫灵公（节选）', source: '《论语》', original: '子曰：己所不欲，勿施于人。', translation: '孔子说：自己不愿意要的，不要强加给别人。', notes: '己：自己；欲：想要；勿：不要；施：施加', category: '修身' },
    { title: '论语·公冶长（节选）', source: '《论语》', original: '子曰：敏而好学，不耻下问。', translation: '孔子说：聪明而又好学，不以向地位低下的人请教为耻。', notes: '敏：聪明；好学：喜爱学习；耻：以……为耻；下问：向不如自己的人请教', category: '学习' },
    { title: '论语·雍也（节选）', source: '《论语》', original: '子曰：知之者不如好之者，好之者不如乐之者。', translation: '孔子说：懂得它的人不如喜爱它的人，喜爱它的人不如以它为乐的人。', notes: '知：懂得；好：喜爱；乐：以……为乐', category: '学习' },
    { title: '论语·学而（其四）', source: '《论语》', original: '曾子曰：吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？', translation: '曾子说：我每天多次反省自己：替别人办事是不是尽心竭力了？和朋友交往是不是诚实了？老师传授的知识是不是复习了？', notes: '吾：我；日：每天；三省：多次反省；忠：尽心竭力；信：诚实；传：老师传授的知识', category: '修身' },
    { title: '论语·子罕（节选）', source: '《论语》', original: '子曰：三军可夺帅也，匹夫不可夺志也。', translation: '孔子说：三军的主帅可以被夺去，一个普通人的志向是不能被夺去的。', notes: '三军：军队的统称；夺：夺去；匹夫：普通人；志：志向', category: '修身' },
    { title: '学弈', source: '《孟子》', original: '弈秋，通国之善弈者也。使弈秋诲二人弈，其一人专心致志，惟弈秋之为听；一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之。虽与之俱学，弗若之矣。', translation: '弈秋是全国最善于下棋的人。让他教两个人下棋，其中一个人专心致志，只听弈秋的教导；另一个人虽然也在听，心里却以为有天鹅要飞来，想拿起弓箭去射它。虽然和前一个人一起学，却比不上人家了。', notes: '弈：下棋；通国：全国；诲：教导；惟：只；援：引、拿；弓缴：弓箭；弗若：不如', category: '学习' },
    { title: '生于忧患，死于安乐', source: '《孟子》', original: '舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中。故天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身。', translation: '舜从田野中被任用，傅说从筑墙工作中被举用，胶鬲从鱼盐贩子中被举用。所以上天将要把重大责任交给这个人，一定先使他的心意苦恼，使他的筋骨劳累，使他忍饥挨饿，使他身处贫困。', notes: '发：被任用；举：被举用；降大任：下达重大责任；苦：使……苦恼；劳：使……劳累；空乏：使……贫困', category: '修身' },
    { title: '得道多助，失道寡助', source: '《孟子》', original: '天时不如地利，地利不如人和。得道者多助，失道者寡助。寡助之至，亲戚畔之；多助之至，天下顺之。', translation: '有利的时令不如有利的地势，有利的地势不如人的团结。行仁政的人帮助他的人就多，不行仁政的人帮助他的人就少。帮助的人少到极点，连亲戚都会背叛他；帮助的人多到极点，天下人都会顺从他。', notes: '天时：有利的时令；地利：有利的地势；人和：人的团结；寡：少；畔：同叛，背叛；顺：顺从', category: '治国' },
    { title: '富贵不能淫', source: '《孟子》', original: '富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。', translation: '富贵不能使他骄奢淫逸，贫贱不能使他改变志向，威武不能使他屈服，这样的人才叫做大丈夫。', notes: '淫：使……乱；移：使……改变；屈：使……屈服；谓：叫做', category: '修身' },
    { title: '鱼我所欲也', source: '《孟子》', original: '鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。', translation: '鱼是我想要的，熊掌也是我想要的。如果两者不能同时得到，我就舍弃鱼而选择熊掌。生命是我想要的，道义也是我想要的。如果两者不能同时得到，我就舍弃生命而选择道义。', notes: '欲：想要；得兼：同时得到；舍：舍弃；取：选择；生：生命；义：道义', category: '修身' },
    { title: '拔苗助长', source: '《孟子》', original: '宋人有闵其苗之不长而揠之者，芒芒然归，谓其人曰：今日病矣！予助苗长矣！其子趋而往视之，苗则槁矣。', translation: '宋国有个担忧自己的禾苗长得不快就去拔高它的人，疲惫不堪地回到家，对家里人说：今天累坏了！我帮助禾苗长高了！他的儿子跑到田里去看，禾苗已经枯萎了。', notes: '闵：担忧；揠：拔；芒芒然：疲惫的样子；病：疲惫；趋：快走；槁：枯萎', category: '哲理' },
    { title: '庄子·逍遥游（节选）', source: '《庄子》', original: '北冥有鱼，其名为鲲。鲲之大，不知其几千里也；化而为鸟，其名为鹏。鹏之背，不知其几千里也；怒而飞，其翼若垂天之云。', translation: '北海有一种鱼，它的名字叫鲲。鲲的体积大，不知道有几千里；它变化成为鸟，名字叫鹏。鹏的背，不知道有几千里；当它奋起飞翔时，翅膀就像垂在天边的云。', notes: '冥：同溟，海；鲲：大鱼；怒：奋起；垂天：遮天', category: '哲理' },
    { title: '庖丁解牛', source: '《庄子》', original: '庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不中音。', translation: '厨师丁给文惠君宰杀牛，手接触的地方，肩靠着的地方，脚踩的地方，膝盖顶着的地方，都发出霍霍的响声，进刀时发出騞騞的声音，没有不合乎音律的。', notes: '庖丁：厨师；解：宰杀分解；触：接触；履：踩；踦：抵住；向然：响声；中音：合乎音律', category: '哲理' },
    { title: '庄子·秋水（节选）', source: '《庄子》', original: '秋水时至，百川灌河。泾流之大，两涘渚崖之间，不辨牛马。于是焉，河伯欣然自喜，以天下之美为尽在己。', translation: '秋天的水按时到来，许多小河的水都流入黄河。水面宽阔，两岸和沙洲之间，连牛马都分辨不清。于是河神沾沾自喜，认为天下最美的景色都集中在自己这里。', notes: '时：按时；灌：注入；泾流：水流；涘：岸；渚：水中小洲；河伯：河神；尽：全', category: '哲理' },
    { title: '曹刿论战', source: '《左传》', original: '十年春，齐师伐我。公将战，曹刿请见。其乡人曰：肉食者谋之，又何间焉？刿曰：肉食者鄙，未能远谋。', translation: '鲁庄公十年的春天，齐国的军队攻打鲁国。鲁庄公准备迎战，曹刿请求去见鲁庄公。他的同乡说：有权位的人会谋划这件事，你又何必参与呢？曹刿说：有权位的人眼光短浅，不能深谋远虑。', notes: '师：军队；伐：攻打；见：拜见；间：参与；鄙：目光短浅；谋：谋划', category: '历史' },
    { title: '烛之武退秦师', source: '《左传》', original: '秦晋围郑，郑既知亡矣。若亡郑而有益于君，敢以烦执事。越国以鄙远，君知其难也，焉用亡郑以陪邻？', translation: '秦国和晋国围攻郑国，郑国已经知道要灭亡了。如果灭掉郑国对您有好处，怎敢拿这件事来麻烦您。越过别国把远方的郑国作为边邑，您知道这是难事，何必灭掉郑国来增加邻国的土地呢？', notes: '既：已经；亡：灭亡；益：好处；执事：对对方的敬称；越：越过；鄙：边邑；陪：增加', category: '历史' },
    { title: '邹忌讽齐王纳谏', source: '《战国策》', original: '邹忌修八尺有余，而形貌昳丽。朝服衣冠，窥镜，谓其妻曰：我孰与城北徐公美？其妻曰：君美甚，徐公何能及君也？', translation: '邹忌身高八尺多，容貌美丽。早晨穿戴好衣帽，照着镜子，对他的妻子说：我和城北的徐公谁美？他的妻子说：您美极了，徐公怎么能比得上您呢？', notes: '修：长，这里指身高；昳丽：美丽；朝：早晨；服：穿戴；窥：照；孰与：与……比怎么样；及：比得上', category: '治国' },
    { title: '触龙说赵太后', source: '《战国策》', original: '父母之爱子，则为之计深远。媪之送燕后也，持其踵，为之泣，念悲其远也，亦哀之矣。', translation: '父母疼爱孩子，就要为他们作长远的打算。您送燕后出嫁时，拉着她的脚，为她哭泣，想到她要远嫁感到悲伤，也真是够疼爱她了。', notes: '爱：疼爱；计：打算；深远：长远；媪：对老年妇女的尊称；踵：脚后跟；念悲：想到而悲伤', category: '治国' },
    { title: '唐雎不辱使命', source: '《战国策》', original: '秦王谓唐雎曰：寡人以五百里之地易安陵，安陵君不听寡人，何也？唐雎对曰：此庸夫之怒也，非士之怒也。', translation: '秦王对唐雎说：我用五百里的土地交换安陵，安陵君不听从我，为什么呢？唐雎回答说：这是平庸人的发怒，不是有志之士的发怒。', notes: '易：交换；听：听从；庸夫：平庸的人；士：有志之士；辱：辱没', category: '历史' },
    { title: '荆轲刺秦王', source: '《战国策》', original: '荆轲逐秦王，秦王还柱而走。群臣惊愕，卒起不意，尽失其度。', translation: '荆轲追逐秦王，秦王绕着柱子跑。群臣惊慌失措，事情发生得突然出乎意料，都失去了常态。', notes: '逐：追逐；还：同环，绕；走：跑；卒：同猝，突然；不意：意料之外；度：常态', category: '历史' },
    { title: '愚公移山', source: '《列子》', original: '北山愚公者，年且九十，面山而居。惩山北之塞，出入之迂也，聚室而谋曰：吾与汝毕力平险，指通豫南，达于汉阴，可乎？', translation: '北山有个叫愚公的人，年纪将近九十岁，面对山居住。他苦于山北阻塞，出入绕远路，就召集全家商量说：我和你们尽全力铲平险峻的大山，一直通到豫州南部，到达汉水南岸，好吗？', notes: '且：将近；惩：苦于；塞：阻塞；迂：绕远；聚室：召集全家；毕力：尽全力；险：大山', category: '哲理' },
    { title: '两小儿辩日', source: '《列子》', original: '孔子东游，见两小儿辩斗，问其故。一儿曰：我以日始出时去人近，而日中时远也。一儿以日初出远，而日中时近也。', translation: '孔子到东方游历，看见两个小孩在争辩，就问他们原因。一个小孩说：我认为太阳刚出来时离人近，而正午时离人远。另一个小孩认为太阳刚出来时离人远，而正午时离人近。', notes: '辩斗：争辩；故：原因；以：认为；去：距离；日中：正午', category: '哲理' },
    { title: '伯牙鼓琴', source: '《吕氏春秋》', original: '伯牙鼓琴，钟子期听之。方鼓琴而志在太山，钟子期曰：善哉乎鼓琴，巍巍乎若太山。少选之间而志在流水，钟子期又曰：善哉乎鼓琴，汤汤乎若流水。', translation: '伯牙弹琴，钟子期听他弹奏。刚开始弹琴时心里想着泰山，钟子期说：弹得真好啊，像泰山一样巍峨。过了一会儿心里想着流水，钟子期又说：弹得真好啊，像流水一样浩荡。', notes: '鼓：弹奏；志：心里想；太山：泰山；善哉：好啊；少选：一会儿；汤汤：水大的样子', category: '友情' },
    { title: '塞翁失马', source: '《淮南子》', original: '近塞上之人有善术者，马无故亡而入胡。人皆吊之，其父曰：此何遽不为福乎？居数月，其马将胡骏马而归。', translation: '靠近边塞的地方有个擅长术数的人，他的马无缘无故跑到胡人那里去了。人们都来安慰他，他的父亲说：这怎么就不会是福气呢？过了几个月，他的马带着胡人的骏马回来了。', notes: '善术者：擅长术数的人；亡：逃跑；吊：安慰；何遽：怎么就；居：过了；将：带领', category: '哲理' },
    { title: '夸父逐日', source: '《山海经》', original: '夸父与日逐走，入日；渴，欲得饮，饮于河、渭；河、渭不足，北饮大泽。未至，道渴而死。弃其杖，化为邓林。', translation: '夸父和太阳赛跑，追到太阳落下的地方；他口渴，想要喝水，就喝黄河和渭河的水；黄河渭河的水不够喝，他又向北去喝大泽的水。还没走到，半路上就渴死了。他丢弃的手杖，化成了一片桃林。', notes: '逐走：赛跑；入日：追到太阳落下的地方；饮：喝水；河、渭：黄河和渭河；不足：不够；弃：丢弃；邓林：桃林', category: '神话' },
    { title: '精卫填海', source: '《山海经》', original: '炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫，常衔西山之木石，以堙于东海。', translation: '炎帝的小女儿，名字叫女娃。女娃在东海游玩，淹死在海里没有回来，所以化成了精卫鸟，常常衔着西山的树枝和石头，来填塞东海。', notes: '少女：小女儿；溺：淹死；返：回来；衔：含在嘴里；堙：填塞', category: '神话' },
    { title: '虽有嘉肴', source: '《礼记》', original: '虽有嘉肴，弗食，不知其旨也；虽有至道，弗学，不知其善也。是故学然后知不足，教然后知困。', translation: '虽然有美味的肉食，不去品尝，就不知道它的味道美；虽然有极好的道理，不去学习，就不知道它的好处。所以学习之后才知道自己的不足，教人之后才知道自己的困惑。', notes: '虽：虽然；嘉肴：美味的肉食；旨：味美；至道：极好的道理；是故：所以；困：困惑', category: '学习' },
    { title: '大道之行也', source: '《礼记》', original: '大道之行也，天下为公，选贤与能，讲信修睦。故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长。', translation: '大道实行的时候，天下是人们共有的，选拔贤能的人治理天下，讲求诚信培养和睦。所以人们不只赡养自己的父母，不只抚养自己的子女，使老年人能安度晚年，壮年人能发挥作用，小孩子能健康成长。', notes: '大道：指儒家推崇的最高政治原则；为公：共有；与：同举，选举；修睦：培养和睦；亲其亲：赡养自己的父母；子其子：抚养自己的子女', category: '治国' },
    { title: '诫子书', source: '诸葛亮', original: '夫君子之行，静以修身，俭以养德。非淡泊无以明志，非宁静无以致远。', translation: '君子的品行，以宁静心来修养身心，以节俭来培养品德。不恬静寡欲就不能明确志向，不宁静专一就不能达到远大目标。', notes: '行：品行；静：宁静；修身：修养身心；淡泊：恬静寡欲；明志：明确志向；致远：达到远大目标', category: '修身' },
    { title: '出师表（节选）', source: '诸葛亮', original: '臣本布衣，躬耕于南阳，苟全性命于乱世，不求闻达于诸侯。先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中，咨臣以当世之事。', translation: '我本来是个平民，在南阳亲自耕种，只求在乱世中保全性命，不奢求在诸侯中出名。先帝不嫌我地位低微见识浅陋，委屈自己降低身份，三次到草庐中来看望我，向我询问当今天下的大事。', notes: '布衣：平民；躬耕：亲自耕种；苟全：苟且保全；闻达：出名；卑鄙：地位低微见识浅陋；猥：委屈；枉屈：降低身份；咨：询问', category: '忠义' },
    { title: '陈涉世家（节选）', source: '司马迁《史记》', original: '陈涉少时，尝与人佣耕，辍耕之垄上，怅恨久之，曰：苟富贵，无相忘。佣者笑而应曰：若为佣耕，何富贵也？陈涉太息曰：嗟乎！燕雀安知鸿鹄之志哉！', translation: '陈涉年轻的时候，曾经和别人一起受雇耕田，他停止耕作走到田埂上，怅惘叹息了好久，说：如果有一天富贵了，彼此不要忘记。雇农们笑着回答说：你是个受雇种田的人，怎么会富贵呢？陈涉长叹一声说：唉！燕子和麻雀怎么能知道天鹅的志向呢！', notes: '尝：曾经；佣耕：受雇耕田；辍：停止；之：去、往；怅恨：怅惘叹息；苟：如果；若：你；太息：长叹；鸿鹄：天鹅', category: '历史' },
    { title: '周亚夫军细柳', source: '司马迁《史记》', original: '上自劳军。至霸上及棘门军，直驰入，将以下骑送迎。已而之细柳军，军士吏被甲，锐兵刃，彀弓弩，持满。', translation: '皇上亲自去慰劳军队。到了霸上和棘门的军营，直接驱车进入，将军以下的军官骑马迎送。不久到了细柳军营，军营将士都穿着铠甲，兵器锐利，张开弓弩，拉满弓弦。', notes: '劳：慰劳；直：直接；驰入：驱车进入；已而：不久；之：到；被：同披；锐：使……锋利；彀：张开；持满：拉满弓', category: '历史' },
    { title: '鸿门宴（节选）', source: '司马迁《史记》', original: '沛公旦日从百余骑来见项王，至鸿门，谢曰：臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦。', translation: '沛公第二天带着一百多人马来见项王，到了鸿门，道歉说：我和将军合力攻打秦国，将军在黄河以北作战，我在黄河以南作战，然而我自己也没想到能先入关攻破秦国。', notes: '旦日：第二天；从：带着；谢：道歉；戮力：合力；意：料想；关：函谷关', category: '历史' },
    { title: '滕王阁序（节选）', source: '王勃', original: '落霞与孤鹜齐飞，秋水共长天一色。渔舟唱晚，响穷彭蠡之滨；雁阵惊寒，声断衡阳之浦。', translation: '落晚霞和孤独的野鸭一起飞翔，秋天的江水和辽阔的天空连成一种颜色。渔船在傍晚唱歌，歌声传到鄱阳湖边；大雁被寒冷惊动，叫声一直到衡阳的水边才断绝。', notes: '鹜：野鸭；一色：同一种颜色；响：歌声；穷：尽；彭蠡：鄱阳湖；浦：水边', category: '写景' },
    { title: '师说', source: '韩愈', original: '古之学者必有师。师者，所以传道受业解惑也。人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣。', translation: '古代求学的人一定有老师。老师是用来传授道理、教授学业、解答疑难问题的人。人不是生下来就懂得道理的，谁能没有疑惑呢？有了疑惑却不跟从老师学习，那些疑惑就始终不能解答了。', notes: '学者：求学的人；所以：用来……的；传道：传授道理；受：同授，教授；解惑：解答疑难；孰：谁；终：始终', category: '学习' },
    { title: '马说', source: '韩愈', original: '世有伯乐，然后有千里马。千里马常有，而伯乐不常有。故虽有名马，祗辱于奴隶人之手，骈死于槽枥之间，不以千里称也。', translation: '世上先有伯乐，然后才有千里马。千里马经常有，可是伯乐不常有。所以即使有名马，也只能屈辱在马夫的手里，和普通的马一起死在马厩里，不能以千里马的称号出名。', notes: '伯乐：善于相马的人；祗：同只，只是；辱：屈辱；骈死：一同死去；槽枥：马厩；称：著称', category: '抒怀' },
    { title: '陋室铭', source: '刘禹锡', original: '山不在高，有仙则名。水不在深，有龙则灵。斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。', translation: '山不在于高，有仙人就出名。水不在于深，有龙就灵验。这是简陋的屋子，只因我的品德好就不觉得简陋了。苔藓的痕迹长上台阶一片绿色，草色映入窗帘一片青葱。', notes: '名：出名；灵：灵验；斯：这；惟：只；馨：香气，指品德高尚；上：长上', category: '抒怀' },
    { title: '小石潭记', source: '柳宗元', original: '从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。伐竹取道，下见小潭，水尤清冽。', translation: '从小丘向西走一百二十步，隔着竹林，听到水声，像玉佩玉环相碰发出的声音，心里很喜欢它。砍伐竹子开辟道路，下去看见一个小水潭，水格外清澈寒冷。', notes: '篁竹：竹林；鸣：发出声音；珮环：玉佩玉环；乐：喜欢；伐：砍伐；取道：开辟道路；尤：格外；清冽：清澈寒冷', category: '写景' },
    { title: '三峡', source: '郦道元', original: '自三峡七百里中，两岸连山，略无阙处。重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。', translation: '在七百里的三峡中，两岸山连着山，完全没有中断的地方。重重叠叠的岩石和山峰遮住了天空和太阳，如果不是正午和半夜，就看不见太阳和月亮。', notes: '略无：完全没有；阙：同缺，中断；嶂：山峰；亭午：正午；夜分：半夜；曦：日光，这里指太阳', category: '写景' },
    { title: '答谢中书书', source: '陶弘景', original: '山川之美，古来共谈。高峰入云，清流见底。两岸石壁，五色交辉。青林翠竹，四时俱备。', translation: '山水的美丽，从古以来人们都赞叹。高耸的山峰直插云霄，清澈的流水能看见水底。两岸的石壁，色彩斑斓交相辉映。青翠的树林和竹子，四季都有。', notes: '共谈：共同赞叹；入云：直插云霄；见底：能看见水底；交辉：交相辉映；四时：四季；俱：都', category: '写景' },
    { title: '记承天寺夜游', source: '苏轼', original: '元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。念无与为乐者，遂至承天寺寻张怀民。', translation: '元丰六年十月十二日夜晚，我脱下衣服准备睡觉，月光照进门里，我高兴地起来散步。想到没有和我一同游乐的人，就到承天寺去找张怀民。', notes: '户：门；欣然：高兴的样子；念：想到；为乐：游乐；遂：于是；寻：寻找', category: '抒怀' },
    { title: '五柳先生传', source: '陶渊明', original: '先生不知何许人也，亦不详其姓字，宅边有五柳树，因以为号焉。好读书，不求甚解；每有会意，便欣然忘食。', translation: '这位先生不知道是什么地方人，也不清楚他的姓名字号，他的住宅边有五棵柳树，就用它做了别号。他喜欢读书，不在于一字一句的解释；每当对书中的内容有所领会，就高兴得忘了吃饭。', notes: '何许：什么地方；详：清楚；因：就；以为：作为；号：别号；会意：领会；欣然：高兴的样子', category: '抒怀' },
    { title: '桃花源记', source: '陶渊明', original: '晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。', translation: '晋朝太元年间，武陵郡有个人以打鱼为生。他顺着溪流划船，忘记了路程的远近。忽然遇到一片桃花林，生长在溪水的两岸长达几百步，中间没有别的树，花草鲜艳美丽，落花纷纷飘落。', notes: '缘：顺着；远近：路程的距离；夹岸：两岸；鲜：鲜艳；落英：落花；缤纷：繁多飘落的样子', category: '田园' },
    { title: '与朱元思书', source: '吴均', original: '风烟俱净，天山共色。从流飘荡，任意东西。自富阳至桐庐一百许里，奇山异水，天下独绝。', translation: '风和烟都散尽了，天和山是同一种颜色。我乘着船随着江流飘荡，任凭它向东或向西。从富阳到桐庐大约一百多里，奇异的山水，是天下独一无二的。', notes: '俱：都；净：散尽；共色：同一种颜色；从流：随着江流；任意：任凭；许：表示大约；独绝：独一无二', category: '写景' },
    { title: '孙权劝学', source: '《资治通鉴》', original: '初，权谓吕蒙曰：卿今当涂掌事，不可不学！蒙辞以军中多务。权曰：孤岂欲卿治经为博士邪！但当涉猎，见往事耳。', translation: '当初，孙权对吕蒙说：你现在当权管事了，不能不学习！吕蒙用军中事务繁多来推辞。孙权说：我难道想让你研究经典成为博士吗！只是应当浏览群书，了解历史罢了。', notes: '当涂：当道、当权；辞：推辞；治经：研究儒家经典；涉猎：粗略地阅读；见往事：了解历史；耳：罢了', category: '学习' },
    { title: '卖油翁', source: '欧阳修', original: '陈康肃公尧咨善射，当世无双，公亦以此自矜。尝射于家圃，有卖油翁释担而立，睨之，久而不去。', translation: '陈尧咨善于射箭，当时没有对手，他也因此自夸。他曾在自家菜园子里射箭，有个卖油翁放下担子站着，斜着眼睛看他射箭，很久都不离开。', notes: '善射：善于射箭；自矜：自夸；圃：菜园；释：放下；睨：斜着眼睛看；去：离开', category: '哲理' },
    { title: '伤仲永', source: '王安石', original: '金溪民方仲永，世隶耕。仲永生五年，未尝识书具，忽啼求之。父异焉，借旁近与之，即书诗四句，并自为其名。', translation: '金溪百姓方仲永，世代以种田为业。仲永长到五岁，不曾认识笔砚等书写工具，忽然哭着要这些东西。父亲对此感到惊奇，向邻居借来给他，他当即写了四句诗，并自己题写了名字。', notes: '隶：属于；尝：曾经；识：认识；异：对……感到惊奇；焉：对此；书：写；为：题写', category: '学习' },
    { title: '爱莲说', source: '周敦颐', original: '水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖。', translation: '水上和陆地上草本木本的花，值得喜爱的很多。晋朝的陶渊明只喜爱菊花。从唐朝以来，世上的人非常喜爱牡丹。我唯独喜爱莲花从淤泥里长出来却不沾染污秽，在清水里洗涤过却不显得妖艳。', notes: '蕃：多；独：只；予：我；淤泥：河沟里积存的污泥；染：沾染；濯：洗涤；清涟：清水；妖：美丽而不庄重', category: '抒怀' },
    { title: '河中石兽', source: '纪昀', original: '沧州南一寺临河干，山门圮于河，二石兽并沉焉。阅十余岁，僧募金重修，求二石兽于水中，竟不可得。', translation: '沧州南面有一座寺庙靠近河岸，山门倒塌在河里，两个石兽一起沉没了。过了十多年，和尚募捐钱财重修，到水里寻找两个石兽，竟然找不到。', notes: '临：靠近；河干：河岸；圮：倒塌；并：一起；阅：经过；岁：年；募金：募捐钱财；求：寻找；竟：竟然', category: '哲理' },
    { title: '核舟记（节选）', source: '魏学洢', original: '明有奇巧人曰王叔远，能以径寸之木，为宫室、器皿、人物，以至鸟兽、木石，罔不因势象形，各具情态。', translation: '明朝有个手艺奇妙精巧的人叫王叔远，能用直径一寸的木头，雕刻成宫殿、器具、人物，甚至鸟兽、树木石头，没有不顺着木头原来的样子模拟事物的形状，各自具有情态。', notes: '奇巧：手艺奇妙精巧；径寸：直径一寸；为：雕刻成；罔不：无不；因：顺着；象：模拟', category: '技艺' },
    { title: '口技（节选）', source: '林嗣环', original: '京中有善口技者。会宾客大宴，于厅事之东北角，施八尺屏障，口技人坐屏障中，一桌、一椅、一扇、一抚尺而已。', translation: '京城有个擅长口技的人。正赶上有人大摆宴席请客，在厅堂的东北角，设置了一道八尺长的屏风，表演口技的人坐在屏风后面，里面只有一张桌子、一把椅子、一把扇子、一块醒木罢了。', notes: '善：擅长；会：正赶上；大宴：大摆宴席；厅事：厅堂；施：设置；屏障：屏风；抚尺：醒木；而已：罢了', category: '技艺' },
    { title: '满井游记（节选）', source: '袁宏道', original: '高柳夹堤，土膏微润，一望空阔，若脱笼之鹄。于时冰皮始解，波色乍明，鳞浪层层，清澈见底。', translation: '高高的柳树夹着堤岸，泥土微微湿润，一眼望去空旷开阔，就像挣脱笼子的天鹅一样自由。这时冰面刚开始融化，水波忽然闪亮，鱼鳞般的波浪层层叠叠，清澈得能看见水底。', notes: '夹堤：夹着堤岸；土膏：肥沃的泥土；若：像；脱笼之鹄：挣脱笼子的天鹅；于时：这时；冰皮：冰面；解：融化；乍：忽然', category: '写景' },
    { title: '湖心亭看雪', source: '张岱', original: '雾凇沆砀，天与云与山与水，上下一白。湖上影子，惟长堤一痕、湖心亭一点、与余舟一芥、舟中人两三粒而已。', translation: '冰花一片弥漫，天和云和山和水，上下一片白色。湖上的影子，只有长堤一道痕迹、湖心亭一个黑点、和我的一叶小舟、舟中两三个人影罢了。', notes: '雾凇：冰花；沆砀：白气弥漫；一白：全白；惟：只；痕：痕迹；芥：小草，喻小船；粒：米粒，喻人小；而已：罢了', category: '写景' },
    { title: '岳阳楼记（节选）', source: '范仲淹', original: '予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江，浩浩汤汤，横无际涯；朝晖夕阴，气象万千。', translation: '我看那巴陵郡的美景，全在洞庭湖上。它连接着远处的群山，吞吐着长江的水流，水势浩大广阔无边无际；早晨阳光灿烂傍晚天色阴沉，气象变化万千。', notes: '胜状：美景；衔：连接；吞：吞吐；浩浩汤汤：水势浩大；际涯：边际；朝晖：早晨的阳光；夕阴：傍晚的阴云', category: '写景' },
    { title: '醉翁亭记（节选）', source: '欧阳修', original: '环滁皆山也。其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。醉翁之意不在酒，在乎山水之间也。', translation: '环绕着滁州的都是山。它西南方向的各个山峰，树林和山谷尤其美丽，远远望去草木茂盛又幽深秀丽的，就是琅琊山。醉翁的情趣不在酒上，而在山水之间。', notes: '环：环绕；皆：都；壑：山谷；尤：尤其；蔚然：草木茂盛；深秀：幽深秀丽；意：情趣；在乎：在于', category: '写景' },
    { title: '游褒禅山记（节选）', source: '王安石', original: '古人之观于天地、山川、草木、虫鱼、鸟兽，往往有得，以其求思之深而无不在也。夫夷以近，则游者众；险以远，则至者少。', translation: '古人对天地山川草木虫鱼鸟兽的观察，往往有所收获，是因为他们探究思考得深入而且无处不在。道路平坦而且近，游玩的人就多；道路险峻而且远，到达的人就少。', notes: '观：观察；得：收获；以：因为；求思：探究思考；无不在：无处不在；夷：平坦；以：而且；众：多', category: '哲理' },
    { title: '前赤壁赋（节选）', source: '苏轼', original: '清风徐来，水波不兴。举酒属客，诵明月之诗，歌窈窕之章。少焉，月出于东山之上，徘徊于斗牛之间。', translation: '清风缓缓吹来，水面上不起波澜。举起酒杯劝客人饮酒，朗诵明月的诗句，歌唱窈窕的篇章。一会儿，月亮从东边的山头升起，在斗宿和牛宿之间徘徊。', notes: '徐：缓缓；兴：起；属：劝；少焉：一会儿；徘徊：停留；斗牛：斗宿和牛宿，星宿名', category: '写景' },
    { title: '黔之驴', source: '柳宗元', original: '黔无驴，有好事者船载以入。至则无可用，放之山下。虎见之，庞然大物也，以为神，蔽林间窥之。', translation: '贵州一带没有驴，有喜欢多事的人用船装了一头运进去。到了之后却没有什么用处，就把它放在山下。老虎看见它，是个巨大的家伙，以为是神灵，就躲在树林里偷看它。', notes: '黔：贵州一带；好事者：喜欢多事的人；船载：用船装；至则：到了之后；无可用：没有用处；庞然：巨大的样子；蔽：躲避；窥：偷看', category: '寓言' },
    { title: '捕蛇者说（节选）', source: '柳宗元', original: '永州之野产异蛇，黑质而白章；触草木，尽死；以啮人，无御之者。然得而腊之以为饵，可以已大风、挛踠、瘘、疠。', translation: '永州的野外出产一种奇异的蛇，黑色的底子白色的花纹；它碰到草木，草木全都枯死；如果咬了人，没有能抵挡的。然而捉到它把它晾干做成药饵，可以治愈大风、挛踠、瘘、疠等恶疾。', notes: '异：奇异；质：底子；章：花纹；触：碰到；啮：咬；御：抵挡；腊：晾干；饵：药饵；已：治愈', category: '悯农' },
    { title: '阿房宫赋（节选）', source: '杜牧', original: '六王毕，四海一，蜀山兀，阿房出。覆压三百余里，隔离天日。骊山北构而西折，直走咸阳。', translation: '六国灭亡了，天下统一了，蜀地的山秃了，阿房宫建成了。它覆盖了三百多里地，遮天蔽日。从骊山北边建起折向西面，一直通到咸阳。', notes: '毕：灭亡；一：统一；兀：光秃；覆压：覆盖；隔离天日：遮天蔽日；构：建造；走：通向', category: '咏史' },
    { title: '秋声赋（节选）', source: '欧阳修', original: '欧阳子方夜读书，闻有声自西南来者，悚然而听之，曰：异哉！初淅沥以萧飒，忽奔腾而澎湃，如波涛夜惊，风雨骤至。', translation: '欧阳先生正在夜里读书，听到有声音从西南方向传来，惊惧地听着它，说道：奇怪啊！起初淅淅沥沥带着萧飒的声音，忽然奔腾澎湃起来，像夜里的波涛受惊，风雨突然到来。', notes: '方：正；闻：听到；悚然：惊惧的样子；异：奇怪；淅沥：雨声；萧飒：风声；澎湃：波浪汹涌；骤：突然', category: '秋景' },
    { title: '石钟山记（节选）', source: '苏轼', original: '事不目见耳闻，而臆断其有无，可乎？郦元之所见闻，殆与余同，而言之不详；士大夫终不肯以小舟夜泊绝壁之下，故莫能知。', translation: '事情不亲眼看到亲耳听到，就凭主观推断它有或没有，可以吗？郦道元所见所闻的，大概和我相同，可是说得不够详细；士大夫终究不肯乘小船在夜里停泊在绝壁之下，所以不能知道真相。', notes: '目见：亲眼看见；臆断：凭主观推断；殆：大概；详：详细；终：终究；泊：停泊；莫：没有谁', category: '哲理' },
    { title: '病梅馆记', source: '龚自珍', original: '江宁之龙蟠、苏州之邓尉、杭州之西溪，皆产梅。或曰：梅以曲为美，直则无姿；以欹为美，正则无景。', translation: '江宁的龙蟠里、苏州的邓尉山、杭州的西溪，都出产梅花。有人说：梅花以弯曲为美，笔直就没有风姿；以倾斜为美，端正就没有景致。', notes: '皆：都；或：有人；曲：弯曲；姿：风姿；欹：倾斜；正：端正；景：景致', category: '抒怀' },
    { title: '少年中国说（节选）', source: '梁启超', original: '故今日之责任，不在他人，而全在我少年。少年智则国智，少年富则国富，少年强则国强，少年独立则国独立。', translation: '所以今天的责任，不在别人身上，而全在我们少年身上。少年聪明国家就聪明，少年富有国家就富有，少年强大国家就强大，少年独立国家就独立。', notes: '故：所以；责任：重任；智：聪明；则：就；独立：能够独立', category: '爱国' },
    { title: '黄生借书说', source: '袁枚', original: '书非借不能读也。子不闻藏书者乎？七略四库，天子之书，然天子读书者有几？', translation: '书不是借来的就不会认真去读。你没听说过藏书的人吗？七略四库这些书都是天子的藏书，可是天子读书的有几个呢？', notes: '非：不是；子：你；闻：听说；七略四库：皇家藏书；然：可是；有几：有几个', category: '学习' },
    { title: '为学', source: '彭端淑', original: '天下事有难易乎？为之，则难者亦易矣；不为，则易者亦难矣。人之为学有难易乎？学之，则难者亦易矣；不学，则易者亦难矣。', translation: '天下的事情有困难和容易的区别吗？只要去做，那么困难的事情也变得容易了；如果不做，那么容易的事情也变得困难了。人们做学问有困难和容易的区别吗？只要去学，那么困难的也变得容易了；如果不学，那么容易的也变得困难了。', notes: '为：做；之：代词，指事情；亦：也；为学：做学问', category: '学习' },
    { title: '送东阳马生序（节选）', source: '宋濂', original: '余幼时即嗜学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。天大寒，砚冰坚，手指不可屈伸，弗之怠。', translation: '我小时候就特别喜欢读书。家里穷，没有办法买书来看，常常向藏书的人家借书，亲手抄写，计算着日子按时归还。天气十分寒冷，砚台里的墨水结了坚硬的冰，手指冻得不能弯曲伸展，也不敢懈怠。', notes: '嗜：喜爱；致：得到、买；假借：借；笔录：抄写；计日：计算日子；坚：坚硬；屈伸：弯曲伸展；弗：不；怠：懈怠', category: '学习' },
    { title: '扁鹊见蔡桓公', source: '《韩非子》', original: '扁鹊见蔡桓公，立有间，扁鹊曰：君有疾在腠理，不治将恐深。桓侯曰：寡人无疾。', translation: '扁鹊拜见蔡桓公，站了一会儿，扁鹊说：您有病在皮肤纹理上，不治疗恐怕会加深。蔡桓侯说：我没有病。', notes: '有间：一会儿；疾：病；腠理：皮肤纹理；治：治疗；恐：恐怕；深：加深；寡人：君主自称', category: '哲理' },
    { title: '自相矛盾', source: '《韩非子》', original: '楚人有鬻盾与矛者，誉之曰：吾盾之坚，物莫能陷也。又誉其矛曰：吾矛之利，于物无不陷也。', translation: '楚国有个卖盾和矛的人，夸他的盾说：我的盾很坚固，没有什么东西能刺穿它。又夸他的矛说：我的矛很锋利，没有什么东西它刺不穿。', notes: '鬻：卖；誉：夸耀；坚：坚固；莫：没有；陷：刺穿；利：锋利；无不：没有不', category: '寓言' },
    { title: '滥竽充数', source: '《韩非子》', original: '齐宣王使人吹竽，必三百人。南郭处士请为王吹竽，宣王说之，廪食以数百人。宣王死，闵王立，好一一听之，处士逃。', translation: '齐宣王让人吹竽，一定要三百人一起吹。南郭处士请求为齐宣王吹竽，齐宣王很高兴，用几百人的口粮供养他。齐宣王死后，齐闵王继位，喜欢听人一个一个地吹，南郭处士就逃跑了。', notes: '使：让；必：一定；处士：没有官职的读书人；说：同悦，高兴；廪食：官府供粮；立：继位；好：喜欢', category: '寓言' },
    { title: '守株待兔', source: '《韩非子》', original: '宋人有耕者。田中有株，兔走触株，折颈而死。因释其耒而守株，冀复得兔。兔不可复得，而身为宋国笑。', translation: '宋国有个种田的人。田里有个树桩，一只兔子跑过来撞在树桩上，折断了脖子死了。于是他放下农具守在树桩旁，希望能再捡到兔子。兔子不可能再捡到了，他自己却被宋国人嘲笑。', notes: '株：树桩；走：跑；触：撞；折：折断；释：放下；耒：农具；冀：希望；复：再；为：被', category: '寓言' },
    { title: '智子疑邻', source: '《韩非子》', original: '宋有富人，天雨墙坏。其子曰：不筑，必将有盗。其邻人之父亦云。暮而果大亡其财，其家甚智其子，而疑邻人之父。', translation: '宋国有个富人，天下雨墙被冲坏了。他的儿子说：如果不修筑，一定会有盗贼来。他的邻居老人也这样说。晚上果然丢失了很多财物，他们家认为自己的儿子很聪明，却怀疑邻居老人。', notes: '雨：下雨；坏：毁坏；筑：修筑；盗：盗贼；父：老人；云：说；暮：晚上；果：果然；亡：丢失；智：认为……聪明', category: '寓言' },
    { title: '穿井得一人', source: '《吕氏春秋》', original: '宋之丁氏，家无井而出溉汲，常一人居外。及其家穿井，告人曰：吾穿井得一人。有闻而传之者曰：丁氏穿井得一人。', translation: '宋国有一户姓丁的人家，家里没有井，要到外面去打水浇地，常常派一个人在外面。等到他家挖了一口井，告诉别人说：我挖井得到一个人。有人听到后传扬说：丁家挖井挖出了一个人。', notes: '溉汲：打水浇地；居外：在外面；穿井：挖井；闻：听到；传：传扬', category: '寓言' },
    { title: '推敲', source: '《刘公嘉话》', original: '岛初赴举京师，一日于驴上得句云：鸟宿池边树，僧敲月下门。始欲作推字，又欲作敲字，炼之未定。', translation: '贾岛初次到京城参加科举考试，一天在驴背上想出两句诗：鸟宿池边树，僧敲月下门。起初想用推字，又想用敲字，反复琢磨没有定下来。', notes: '赴举：参加科举考试；京师：京城；得句：想出诗句；欲：想；炼：琢磨推敲；未定：没有定下来', category: '学习' },
    { title: '王冕僧寺夜读', source: '《宋学士文集》', original: '王冕者，诸暨人。七八岁时，父命牧牛陇上，窃入学舍，听诸生诵书；听已，辄默记。暮归，忘其牛。', translation: '王冕是诸暨人。七八岁的时候，父亲让他在田埂上放牛，他偷偷溜进学堂，听学生们读书；听完，就默默记下来。傍晚回家，把牛都忘了。', notes: '窃：偷偷地；学舍：学堂；诸生：学生们；已：完毕；辄：就；默记：默默记下；暮：傍晚', category: '学习' },
    { title: '薛谭学讴', source: '《列子》', original: '薛谭学讴于秦青，未穷青之技，自谓尽之，遂辞归。秦青弗止，饯于郊衢，抚节悲歌，声振林木，响遏行云。', translation: '薛谭向秦青学习唱歌，还没有学完秦青的技艺，就自以为全部学到了，于是告辞回家。秦青没有挽留他，在城外的大道上为他饯行，打着节拍唱起悲歌，歌声震动了林木，回声阻挡了天上的行云。', notes: '讴：唱歌；穷：穷尽；谓：以为；辞：告辞；弗：不；饯：饯行；衢：大道；抚节：打节拍；遏：阻止', category: '学习' },
    { title: '纪昌学射', source: '《列子》', original: '甘蝇，古之善射者，彀弓而兽伏鸟下。弟子名飞卫，学射于甘蝇，而巧过其师。纪昌者，又学射于飞卫。', translation: '甘蝇是古代善于射箭的人，他一拉弓野兽就倒下鸟就掉落。他的弟子叫飞卫，向甘蝇学习射箭，技艺超过了他的老师。有个叫纪昌的人，又向飞卫学习射箭。', notes: '善：善于；彀：拉开；伏：倒下；巧：技艺；过：超过；学射：学习射箭', category: '学习' },
    { title: '工之侨献琴', source: '刘基', original: '工之侨得良桐焉，斫而为琴，弦而鼓之，金声而玉应。自以为天下之美也，献之太常。', translation: '工之侨得到一块优良的桐木，砍削做成琴，装上琴弦弹奏，发出金玉般的声音。他自认为这是天下最美的琴，把它献给太常寺。', notes: '良：优良；桐：桐木；斫：砍削；弦：装上琴弦；鼓：弹奏；应：相应；献：献给', category: '寓言' },
    { title: '卖柑者言', source: '刘基', original: '杭有卖果者，善藏柑，涉寒暑不溃。出之烨然，玉质而金色。置于市，贾十倍，人争鬻之。', translation: '杭州有个卖水果的人，善于储藏柑橘，经过寒暑也不溃烂。拿出来光彩耀眼，像玉一样的质地金黄的颜色。放在集市上，价钱是普通的十倍，人们争相购买。', notes: '善：善于；涉：经过；溃：溃烂；烨然：光彩耀眼的样子；贾：同价，价钱；鬻：买', category: '寓言' },
    { title: '答司马谏议书（节选）', source: '王安石', original: '盖儒者所争，尤在于名实，名实已明，而天下之理得矣。今君实所以见教者，以为侵官、生事、征利、拒谏，以致天下怨谤也。', translation: '读书人争论的，尤其在于名义和实际，名义和实际明确了，天下的道理就清楚了。现在您用来指教我的，认为我是侵夺官吏职权、惹事生非、搜刮钱财、拒绝劝谏，以致遭到天下人的怨恨和诽谤。', notes: '盖：发语词；儒者：读书人；名实：名义和实际；见教：指教；侵官：侵夺职权；征利：搜刮钱财；拒谏：拒绝劝谏；怨谤：怨恨诽谤', category: '治国' },
    { title: '黄冈竹楼记', source: '王禹偁', original: '黄冈之地多竹，大者如椽。竹工破之，刳去其节，用代陶瓦。比屋皆然，以其价廉而工省也。', translation: '黄冈这个地方多竹子，大的像椽子一样粗。竹工把它劈开，挖去里面的节，用来代替陶瓦。家家户户的房屋都是这样，因为它的价钱便宜而且省工。', notes: '椽：椽子；破：劈开；刳：挖空；节：竹节；陶瓦：陶制的瓦；比屋：家家户户；然：这样；廉：便宜', category: '写景' },
    { title: '狼', source: '蒲松龄', original: '一屠晚归，担中肉尽，止有剩骨。途中两狼，缀行甚远。屠惧，投以骨。一狼得骨止，一狼仍从。', translation: '一个屠夫傍晚回家，担子里的肉已经卖完了，只剩下一些骨头。路上遇到两只狼，紧跟着他走了很远。屠夫害怕了，把骨头扔给狼。一只狼得到骨头停下了，另一只狼仍然跟着。', notes: '屠：屠夫；尽：卖完；止：只；缀：紧跟；惧：害怕；投以骨：把骨头扔给狼；止：停下；从：跟随', category: '寓言' },
    { title: '曾子杀猪', source: '《韩非子》', original: '曾子之妻之市，其子随之而泣。其母曰：女还，顾反为女杀彘。妻适市来，曾子欲捕彘杀之。', translation: '曾子的妻子去集市，她的儿子哭着要跟着去。他的母亲说：你先回去，等我回来给你杀猪吃。妻子从集市回来，曾子就要捉猪来杀。', notes: '之：去；市：集市；泣：哭；女：同汝，你；还：回去；顾：等我；反：同返，回来；彘：猪；适：刚才', category: '修身' },
    { title: '教学相长', source: '《礼记》', original: '虽有嘉肴，弗食，不知其旨也；虽有至道，弗学，不知其善也。是故学然后知不足，教然后知困。知不足，然后能自反也；知困，然后能自强也。', translation: '虽然有美味的肉食，不去品尝，就不知道它的味道美；虽然有极好的道理，不去学习，就不知道它的好处。所以学习之后才知道自己的不足，教人之后才知道自己的困惑。知道不足，然后能自我反省；知道困惑，然后能自我勉励。', notes: '旨：味美；至道：极好的道理；是故：所以；困：困惑；自反：自我反省；自强：自我勉励', category: '学习' },
    { title: '女娲补天', source: '《山海经》', original: '往古之时，四极废，九州裂，天不兼覆，地不周载。火爁焱而不灭，水浩洋而不息。于是女娲炼五色石以补苍天。', translation: '在远古的时候，大地的四极崩坏了，九州裂开了，天不能完全覆盖大地，地不能全面承载万物。大火熊熊燃烧不灭，洪水滔滔不息。于是女娲炼制五色石来修补苍天。', notes: '四极：大地的四极；废：崩坏；裂：裂开；兼覆：完全覆盖；周载：全面承载；爁焱：大火燃烧；息：停止；炼：炼制', category: '神话' },
    { title: '三人成虎', source: '《战国策》', original: '庞葱与太子质于邯郸，谓魏王曰：今一人言市有虎，王信之乎？王曰：否。二人言市有虎，王信之乎？王曰：寡人疑之矣。三人言市有虎，王信之乎？王曰：寡人信之矣。', translation: '庞葱和太子要到邯郸去做人质，庞葱对魏王说：现在如果一个人说集市上有老虎，大王相信吗？魏王说：不相信。两个人说集市上有老虎，大王相信吗？魏王说：我有些怀疑了。三个人说集市上有老虎，大王相信吗？魏王说：我相信了。', notes: '质：做人质；谓：对……说；市：集市；信：相信；否：不；疑：怀疑；寡人：君主自称', category: '寓言' },
    { title: '晏子使楚', source: '《晏子春秋》', original: '晏子将使楚。楚王闻之，谓左右曰：晏婴，齐之习辞者也。今方来，吾欲辱之，何以也？', translation: '晏子将要出使楚国。楚王听说了，对身边的人说：晏婴是齐国善于辞令的人。现在他要来了，我想羞辱他，用什么办法呢？', notes: '使：出使；闻：听说；左右：身边的人；习辞：善于辞令；方：将要；辱：羞辱；何以：用什么', category: '历史' },
    { title: '狐假虎威', source: '《战国策》', original: '虎求百兽而食之，得狐。狐曰：子无敢食我也！天帝使我长百兽，今子食我，是逆天帝命也。', translation: '老虎寻找各种野兽来吃，捉到了一只狐狸。狐狸说：你不敢吃我！天帝派我做百兽的首领，如果你吃了我，这就违背了天帝的命令。', notes: '求：寻找；食：吃；无敢：不敢；长：首领；逆：违背；命：命令', category: '寓言' },
    { title: '画蛇添足', source: '《战国策》', original: '楚有祠者，赐其舍人卮酒，舍人相谓曰：数人饮之不足，一人饮之有余，请画地为蛇，先成者饮酒。', translation: '楚国有个祭祀的人，赏给他的门客一杯酒，门客们互相商量说：几个人喝这杯酒不够，一个人喝还有剩余，请大家在地上画蛇，先画好的人喝酒。', notes: '祠：祭祀；舍人：门客；卮：古代盛酒器；相谓：互相商量；不足：不够；有余：有剩余；画地：在地上画', category: '寓言' },
    { title: '鹬蚌相争', source: '《战国策》', original: '蚌方出曝，而鹬啄其肉，蚌合而箝其喙。鹬曰：今日不雨，明日不雨，即有死蚌！蚌亦谓鹬曰：今日不出，明日不出，即有死鹬！', translation: '蚌正张开壳晒太阳，鹬去啄它的肉，蚌合上壳夹住了鹬的嘴。鹬说：今天不下雨，明天不下雨，就会有死蚌！蚌也对鹬说：今天不放出来，明天不放出来，就会有死鹬！', notes: '方：正；曝：晒太阳；啄：啄食；箝：夹住；喙：鸟嘴；雨：下雨；出：放出来', category: '寓言' },
    { title: '掩耳盗铃', source: '《吕氏春秋》', original: '范氏之亡也，百姓有得钟者，欲负而走，则钟大不可负，以锤毁之，钟况然有音，恐人闻之而夺己也，遽掩其耳。', translation: '范氏家族灭亡的时候，有个百姓得到了一口钟，想背着它逃跑，但是钟太大背不动，就用锤子砸它，钟发出洪亮的响声，他怕别人听到来抢夺自己，急忙捂住自己的耳朵。', notes: '亡：灭亡；钟：乐器；负：背；走：跑；锤：锤子；毁：毁坏；况然：洪亮的声音；遽：急忙；掩：捂住', category: '寓言' },
    { title: '朝三暮四', source: '《庄子》', original: '宋有狙公者，爱狙，养之成群，能解狙之意，狙亦得公之心。损其家口，充狙之欲。', translation: '宋国有个养猴子的老人，喜欢猴子，养了一群，他能理解猴子的心意，猴子也懂得老人的心思。他减少自己家的口粮，来满足猴子的要求。', notes: '狙：猴子；狙公：养猴的老人；解：理解；得：懂得；损：减少；家口：家里的口粮；充：满足；欲：欲望', category: '寓言' },
    { title: '邯郸学步', source: '《庄子》', original: '子独不闻寿陵余子之学行于邯郸与？未得国能，又失其故行矣，直匍匐而归耳。', translation: '你难道没有听说燕国寿陵的少年到邯郸去学走路吗？没有学到邯郸人走路的本领，又丢掉了自己原来的走法，只好爬着回去了。', notes: '独：难道；寿陵：燕国地名；余子：少年；学行：学走路；国能：邯郸人的本领；故行：原来的走法；直：只好；匍匐：爬行；归：回去', category: '寓言' },
    { title: '叶公好龙', source: '《新序》', original: '叶公子高好龙，钩以写龙，凿以写龙，其室宇雕文，尽以写龙。于是天龙闻而下之，窥头于牖，施尾于堂。', translation: '叶公子高喜欢龙，衣带钩上刻着龙，酒器上刻着龙，房间里的雕刻花纹，全都刻着龙。于是天上的龙听说了就下来看他，把头探进窗户，尾巴拖在厅堂里。', notes: '好：喜欢；钩：衣带钩；写：描绘、雕刻；凿：古代盛酒器；室宇：房屋；雕文：雕刻的花纹；牖：窗户；施：延伸', category: '寓言' },
    { title: '观潮（节选）', source: '周密', original: '浙江之潮，天下之伟观也。自既望以至十八日为最盛。方其远出海门，仅如银线；既而渐近，则玉城雪岭际天而来。', translation: '钱塘江的潮水，是天下雄伟的景观。从农历十六日到十八日最为盛大。当它刚从海门涌出时，只像一条银线；不久渐渐逼近，就像玉城雪岭连着天涌来。', notes: '浙江：钱塘江；伟观：雄伟的景观；既望：农历十六日；盛：盛大；方：当；海门：江海交汇处；既而：不久；际天：连着天', category: '写景' },
    { title: '苏武传（节选）', source: '班固《汉书》', original: '律知武终不可胁，白单于。单于愈益欲降之，乃幽武，置大窖中，绝不饮食。天雨雪，武卧啮雪，与旃毛并咽之，数日不死。', translation: '卫律知道苏武终究不能被威胁，禀告了单于。单于更加想要使他投降，就把苏武囚禁起来，放在大窖中，断绝他的饮食。天下雪，苏武躺着嚼雪，和着毡毛一起吞咽下去，几天都没死。', notes: '胁：威胁；白：禀告；益：更加；降：使投降；幽：囚禁；窖：地窖；雨：下；啮：咬嚼；旃：同毡，毛织品；咽：吞咽', category: '忠义' },
    //CLASSICS_END_MARKER
  ]
};
